/* 令和4年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r04.committeeSessions.push(...[{"id":"r04-20220322-3","meetingId":"r04-c-budget","date":"2022年3月22日","dateIso":"2022-03-22","committee":"予算特別委員会","time":"午前１０時００分～午後 ５時３２分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を116件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"芹澤委員","kind":"質問・要望","question":"今月、特別区議会議長会としても初めて、ふるさと納税に対して反対、見直しを求めて交渉・要望してまいりました。ふるさと納税の抜本的な見直しを求めていくというのが、まず今後のふるさと納税に対して、品川区の考え方を改めて説明を求めました。","respondent":"榎本総務部長","answer":"品川区では令和３年度に３０億７,０００万円の減収になり、区としては、特別区長会を通じて総務大臣宛ての要望書を提出したところです。制度をめぐる問題に対処するように、抜本的な見直しを強く求めてまいります。","id":"exchange-001"},{"speaker":"芹澤委員","kind":"提案","question":"以前、私からは、ふるさと納税についてはぜひマーケティングの視点を持って返礼品を整えていただきたいというご提案をさせていただきました。確認していくと、ふるさと納税として区が業務を、そこまで事務としてはやることがないとの意見を述べました。","respondent":"榎本総務部長、堀越企画部長","answer":"ガバメントクラウドファンディングの企画・調整・実施を各所管課との役割分担をつくり、事務軽減を図り、新たな人員も配置せずに行ってきました。今後も効率的に努めてまいりたいと考えています。 新たにブラインドサッカーの普及・啓発にクラウドファンディングも活用していくという企画立案をしています。委員がおっしゃったような観点も踏まえて、マーケティングの視点も入れながら実施に努めていきたいと考えているところです。","id":"exchange-002"},{"speaker":"芹澤委員","kind":"質問・要望","question":"今、傷口に対して本当に小さなばんそうこうしか使っていない状況ですから、しっかり抑えられるような処置をしていただきたいと思っています。新しい課長が全庁的に対応できるのかというのを危惧しておりますが、ぜひそういった体制整備を求めますが、まずご見解を説明を求めました。","respondent":"堀越企画部長","answer":"民間出身の情報戦略担当課長を、この４月１日付で採用する予定です。全体的な推進を主な議題とするＤＸ推進戦略会議や、それからＡＩやＲＰＡなど、個別のテーマごとの会議体等も設けて全庁的に進めていく予定です。","id":"exchange-003"},{"speaker":"芹澤委員","kind":"質問","question":"新しい民間の方を呼ばれるということで、人材の質についても一部危惧しているところがありますので、お伺いしていきます。兼業もオーケーですよというふうにして高度な人材を確保していくというのも考えの一つかと思いますが、人材の質の担保について説明を求めました。","respondent":"堀越企画部長","answer":"各分野別の課長の採用というのも、そういったところもいろいろ見ながら、必要性についても可能性についても検討していきたいと思ってあります。","id":"exchange-004"},{"speaker":"芹澤委員","kind":"質問・要望","question":"人材の確保、非常に厳しいお話を伺っていて、ぜひ前線でばりばり働いてくれる方を前向きに雇用できるような体制の構築というのを求めたいと思います。は助成金、全ての分野で１００％にしていただきたいと思っていますが、今後のご見解をお聞かせほしいと求めました。","respondent":"堀越企画部長","answer":"ただ、全体の中から見ますと、今のところ約１０％程度ですので、今後、戦略的にオンライン化を進めていく必要があると考えています。移行予定、標準化の終了予定年度が令和７年度ですので、１００％オンライン化を目指していきたいと考えているところです。","id":"exchange-005"},{"speaker":"芹澤委員","kind":"提案","question":"関連して、最後にデジタル基本戦略についてお伺いしたいと思います。２年後にもう一回検証したら、どんどんデジタル化を進めていただきたいという思いでご提案いたしますが、最後にご見解を説明を求めました。","respondent":"堀越企画部長","answer":"対象期間も、先ほどご答弁申し上げたようにシステム標準化の終了予定年度が令和７年度ですので。これについても併せてやっていきたいということで、これらの考え方を基本方針に記載して、この基本方針を基に全庁的に進めていきたいと考えています。","id":"exchange-006"},{"speaker":"芹澤委員","kind":"質問・要望","question":"これは要望で終わります。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"初めに２点伺います。そして、旧東品川清掃作業所跡地への移転も検討してはと質問をいたしましたが、これも併せて伺いたいと思います。","respondent":"榎本総務部長、藤田防災まちづくり部長","answer":"空間をうまく活用した多様な会議室やウェブ会議室など、これからの働き方に対応した会議室の設置を考えてまいります。新庁舎への食堂の設置につきましては、災害時を考慮した厨房施設の在り方など、慎重に検討していきたいと考えていま… 平成３年の開館当時、実施の意義はあったと考えていますが、現在では近傍の水族館などでも実施している状況です。他の地域での検討も行いましたが、現在、進めているところです。","id":"exchange-008"},{"speaker":"石田（秀）委員","kind":"提案","question":"その辺に対する考え方をもう一回お伺いしたいと思うのと、ぜひその辺も改めて検討していただきたいと考えていますので、答弁をお願いします。ぜひそれはどういうふうにやっていくか、もう一度、これは意気込みも併せてお伺いしますとの意見を述べました。","respondent":"榎本総務部長、藤田防災まちづくり部長","answer":"そのほか、ウェブ会議室など、いろいろ対応した会議室の設置を検討していく予定です。いざ緊急事態の感染症の対応ができるかということで、保健センター、健康部門等の連携が取れるように図ってまいりたいと考えています。 展示のコンセプト、管理の手法なども含めまして、ソフト面の検討も併せて行っていくことが重要だと考えています。頂いたご提案につきましては真摯に受け止めまして、今後の検討に活かしていきたいと考えています。","id":"exchange-009"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"中之島公園で噴水をやっておりますけれど、あれで集客ができるわけですから、やはりあれぐらいのことも考えてもらいたいと考えています。品川区から発信しているわけですから、そこだけ、水族館の意気込みだけ最後に聞かせてほしいと求めました。","respondent":"藤田防災まちづくり部長","answer":"しながわ水族館は、平成３年の開館以来、大変多くの方に愛されてきた施設です。社会教育などを牽引していくために、充実した施設づくり、運営体制づくりを進めていく考えです。","id":"exchange-010"},{"speaker":"新妻委員","kind":"質問","question":"さらに、第６波において、これまでの感染状況から活かされたことは何か、伺います。第６波での課題は何か、今後の感染状況をどのように予測され、改善策や準備はどうされるのか、伺います。","respondent":"福内品川区保健所長","answer":"第６波の課題としては、頻回な国や都の方針変更への迅速な対応と、区民への適切な情報提供が課題と考えています。今後、さらなる効率的な業務の実施や、ホームページ等の充実等に取り組んでまいります。","id":"exchange-011"},{"speaker":"新妻委員","kind":"確認","question":"１・２回目接種が終わり、３月２２日現在６か月が経過している人数をお伺いします。さらに、直近の世代別の３回目接種済み数を伺います。","respondent":"秋山保健整備担当部長","answer":"昨年１２月に、未接種の方を含む、区で接種歴の確認ができない方や転入された方およそ６万人に対して、お知らせのはがきを送付いたしました。６０歳から６４歳が１万１,１０３名で５８.８％、６５歳以上は６万２,３７３名で７６.２％、全体では４８％となっています。","id":"exchange-012"},{"speaker":"新妻委員","kind":"質問","question":"２０代、３０代の若い世代への接種率向上について伺います。予約なし接種は本日まで５日間実施されていますが、大井競馬場、来場された方で何かしらの理由により接種ができなかった方がいたのかも伺います。","respondent":"秋山保健整備担当部長","answer":"３月に入り、事前に予定を立てることが難しい方への接種機会を提供し、３回目接種を推進するために実施いたしました。３月１０日の実施以降、大井競馬場で２５名、合計５４名の接種がございました。","id":"exchange-013"},{"speaker":"新妻委員","kind":"質問・要望","question":"随時、最新情報が的確に届くよう要望しますが、どのような情報発信を検討されているのでしょうか。伺います。","respondent":"秋山保健整備担当部長","answer":"１・２回のときに港区と合同で実施した、区外での接種会場の確保に加え、集団接種会場では全ての開設日で事前予約なしの接種を実施し。","id":"exchange-014"},{"speaker":"新妻委員","kind":"質問","question":"このようなことから、接種を迷っている保護者の皆様へ、また５歳から１１歳のお子さんのワクチン接種についてをＡ４のチラシ形式でまとめました。見解を伺います。","respondent":"秋山保健整備担当部長","answer":"区では、５歳から１１歳の接種に関しましては、ご家族、保護者の方がワクチン接種の可否をご自身で判断いただけるよう、情報発信に努めております。しながわパパママ応援アプリも含め、多くの媒体でこうした情報を区民の皆様に届けるよう進めてまいります。","id":"exchange-015"},{"speaker":"新妻委員","kind":"質問","question":"１２歳から１７歳以下の接種券発送のスケジュールと予約開始日、接種会場を伺います。併せて、４回目接種が言及されていますので、伺います。","respondent":"秋山保健整備担当部長","answer":"区の設置する集団接種会場では、４月下旬から、旧荏原第四中学校と大井競馬場にて、専用枠を設けて接種が始められるよう準備を進めてあります。６月以降、医療従事者から接種を開始するとの情報が出ていることは承知しておりますが、ただいま準備を進めております。","id":"exchange-016"},{"speaker":"新妻委員","kind":"質問","question":"宣言は、令和４年度に予定されている環境基本計画改定と並行して行うとのことですが、宣言をいつ頃と想定しているのでしょうか。伺います。","respondent":"中村都市環境部長","answer":"庁内検討をはじめ、複数回の検討を行いまして、年度末までに行う予定としております。したがいまして、宣言につきましても、計画の改定と合わせた宣言を予定しておりますが、可能な限り早期の宣言を行うよう進めてまいります。","id":"exchange-017"},{"speaker":"新妻委員","kind":"質問","question":"区が考える、区民と共に取り組む宣言の実現は、どのようなイメージをされ、どう展開されるのでしょうか。伺います。","respondent":"中村都市環境部長","answer":"連携についてですけれども、エコルとごしでは、省エネ・創エネを通じました脱炭素社会の実現に向けまして周知・啓発を行っていく予定としております。宣言にどのように取り組むかという内容を示す基本計画の改定の中でも、当然のことながら検討を進めてまいります。","id":"exchange-018"},{"speaker":"新妻委員","kind":"質問","question":"見解を伺います。見解を伺います。","respondent":"品川品川区清掃事務所長、中村都市環境部長","answer":"可燃ごみで約４割が生ごみとなっておりまして、区民一人ひとりがごみ減量意識を高めるための啓発活動が重要であると考えております。このような啓発方法について今後検討してまいります。 ただ、もったいないレシピを効果的に、また具体的に啓発していくことが重要だと考えております。もったいないレシピの活用について検討を進めてまいりたいと考えております。","id":"exchange-019"},{"speaker":"新妻委員","kind":"質問・要望","question":"今後の説明会の開催など、区民の意見が伝えられる場をしっかり持っていただきたいと要望します。見解を伺います。","respondent":"中村都市環境部長、藤田防災まちづくり部長","answer":"平成３１年１月に策定いたしました立会川・勝島地区まちづくりビジョンの検討におきまして、その中でも実施しました地域の意見交換会、それから。それから、その後、計画説明や工事説明といったものの実施に伴いましても… この２つの対策を、この土地で実施する計画となっています。区といたしましては、東京都と連携いたしまして地域の課題を一つひとつ解決し、立会川・勝島運河の周辺環境の整備に努めてまいります。","id":"exchange-020"},{"speaker":"新妻委員","kind":"質問・要望","question":"明晴学園の会議体への参加についての区の見解を伺います。常に多世代の声を聞く視点を持っていただき、ＰＴＡや若い方々のご意見・ご要望が反映されるよう要望しますが、見解を伺います。","respondent":"久保田地域振興部長","answer":"八潮地区の方を中心に構成する八潮まちづくり懇談会と、区の部課長で構成します八潮まちづくり庁内検討会の２つを設置する予定であります。施設見学会やまちづくりに関するセミナーなども開催する予定でありまして、まちづくりに参加していただけるよう進めてまいります。","id":"exchange-021"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"本日は、主に品川区の未来を担う子どもに関わる質問を中心に伺います。学校給食の牛乳にプラスチックストローを使用しないことを求める請願が区議会に提出され、全会一致で採択されました。","respondent":"米田教育次長","answer":"平成３０年の請願の採択を受けまして、東京都学校給食会、そして供給元の乳業事業者へ送付いたしました。以降も、事業者等に対する働きかけを継続して行っているところです。","id":"exchange-022"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"区民の請願採択や議会質問を受けて、区教育委員会は乳業事業者へ働きかけを行ったと伺っていますが、また働きかけの内容と頻度を教えてください。ストローレスの取組を一刻も早く開始するよう、強く強く乳業事業者に要請してほしいと求めましたが、ご所見を伺います。","respondent":"米田教育次長","answer":"プラスチック削減は、持続可能な社会を実現する上で重要な取組であると考えており、こちらについて継続的に働きかけを行ってまいりました。","id":"exchange-023"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"洋式化の状況確認と、さらなる推進を求め続け、１０年が経過しました。区としての洋式化率の具体的な達成目標を明らかにするよう強く求め、当時の教育次長から初めて９０％達成を目指すとの答弁が示されました。","respondent":"米田教育次長","answer":"そのうち和式便器数は４６０か所、洋式便器数は２,００４か所となり、洋式化率は８１.３％となる見込みです。東京都が７１.１％、品川区は７７.０％であり、全国と東京都よりは上回っているところです。","id":"exchange-024"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"現在の目標値である９０％達成のおおよその達成年度のめどもお示しください。９０％を達成した後は、できる限り洋式化を推進してほしいと求めましたが、ご所見を伺います。","respondent":"米田教育次長","answer":"年当たり１.５ポイントから２ポイント程度上昇しておりまして、おおむね令和９年前後になろうかと思いますが、９０％に到達する見込みです。なお、９０％到達後も引き続き洋式化に努めてまいります。","id":"exchange-025"},{"speaker":"あくつ副委員長","kind":"確認","question":"そして、それ以降も推進していくという確認をさせていただきました。防災バリアフリー、そして性的マイノリティへの配慮等の観点から、今後、さらなる多目的トイレの整備拡充が必要と考えますが、区の認識を伺います。","respondent":"米田教育次長","answer":"学校の多目的トイレの設置状況といたしましては、区立小学校・中学校・義務教育学校の２８校、９５か所に設置しています。ご指摘の様々な観点も勘案し、今後の多目的トイレの整備につきましては、学校改築の工事等に合わせまして整備・拡充してまいりたいと考えています。","id":"exchange-026"},{"speaker":"あくつ副委員長","kind":"提案","question":"２０１７年第４回定例会の一般質問において、ふるさと納税によるクラウドファンディングの活用を提案し、導入を検討するとの答弁が示されました。昨年の決算特別委員会で、様々な課題があることを伝え、改善を求めておりましたとの意見を述べました。","respondent":"柏原子ども未来部長","answer":"昨年の事業実施におきまして、まず１つ、これが課題であったというところで捉えてあります。品物の課題と、それから通知文の表記が相まって、不快な思いをさせてしまったといったところがあったというところで認識しています。","id":"exchange-027"},{"speaker":"あくつ副委員長","kind":"質問","question":"令和４年度予算案には、ふるさと納税寄附金５００万円が計上されており、お知らせください。ミスマッチ解消と本来の目的を十分に達成するため、本事業をどのように再構築されていくのか、ご所見を伺います。","respondent":"柏原子ども未来部長","answer":"新しい事業展開ができるようにということで今検討しているところでございまして、改めて確認させていただきながら、進めていきたいと思ってあります。その後、区でどういった支援に皆様方をつなげられるかといったところ、事業の再検討をしていきたいと思ってあります。","id":"exchange-028"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"事業者が事前確認を行う登録確認機関を探す時間的・精神的な負担や経済的な負担が発生している状況を認識されているのか、伺います。事前確認を求める事業者に対して、区としてどのような支援策があるのか、示すよう求めました。","respondent":"久保田地域振興部長","answer":"２つ目は、今までに一時支援金等を受給していない事業者のうち、国が定める継続支援関係に当たる登録確認機関があるものに該当しまして。３つ目の、登録支援機関の検索や事前確認の資料の準備、さらには事前確認の事務手数料などに負担を感じていると認識しています。","id":"exchange-029"},{"speaker":"あくつ副委員長","kind":"提案","question":"昨年第２回定例会の、公明党の一般質問で、行政書士等の法的な資格を持った専門家の支援への費用助成を求めました。これまでも会派として重ねて提案・要望してまいりましたが、相談のみにとどまらず、ご所見を伺いますとの意見を述べました。","respondent":"久保田地域振興部長","answer":"今後の対応についてお答えいたします。ビジネス・カタリスト派遣制度により対応しており、今後も本制度を一層工夫・拡充いたしまして、申請が困難である事業者の支援を進めてまいります。","id":"exchange-030"},{"speaker":"せお副委員長","kind":"質問・要望","question":"そこで、品川区もこのような保存方法でしょうか、確認させてください。ですから、５年で破棄することなく、保存期間を延長していただきたいと考えますが、区の接種記録の保存の現状と今後の対応をお知らせください。","respondent":"福内品川区保健所長、秋山保健整備担当部長","answer":"それ以前の記録についても、平成２１年３月から遡って入力を進めているところです。今後につきましても、期限を区切ることなく継続して接種歴の保存を行ってまいります。疫学調査支援システムは、第５波のさなかの９月に開発を開始し、３か月という短期間で運用を開始いたしました。","id":"exchange-031"},{"speaker":"せお副委員長","kind":"質問","question":"そしてその中でも、子どもとその家族のテンションが上がる、どきどきわくわくするような取組はありますでしょうか。説明を求めました。","respondent":"柏原子ども未来部長","answer":"在宅子育て家庭に対する支援といったところで、こういったところに取り組んでいきたいといったところでの予算編成をしたところです。","id":"exchange-032"},{"speaker":"せお副委員長","kind":"質問","question":"昨年の１０月から１２月のように感染者数が減ったときにイベントなどが行えるよう、準備だけはしておいてほしいのですが、見解をお聞かせください。さらに、子どもたちの思い出が増えるのかと思いますが、そのような取組についても見解を説明を求めました。","respondent":"柏原子ども未来部長","answer":"ただ、いつ感染の状況が伸びるのか伸びないのかというところは、なかなか判断が難しいといったところでございました。バスの予約があったり、なかなか判断の難しいところではあったのですが、事業は見合わせたといったところがあります。","id":"exchange-033"},{"speaker":"せお副委員長","kind":"質問","question":"平成１４年から整備された幼保一体施設ですが、一定の需要はあって、ここはここで減らさないでほしいという思いはあります。２点、お願いいたします。","respondent":"柏原子ども未来部長","answer":"幼保一体施設の考え方等です。それを、ゼロ歳児から就学前まで一貫して同一の施設で行うことができるというところが一番大きな利点であろうと捉えてあります。","id":"exchange-034"},{"speaker":"せお副委員長","kind":"質問","question":"現在まさにあるかと思いますが、職員の急なお休みのときなど、幼保でお互いを助けられる仕組みはあるのでしょうか。先ほどのイベントに関してもそうかもしれませんが、今挙げたような連携などの好事例がありますか尋ねました。","respondent":"柏原子ども未来部長","answer":"連携の体制といたしましては、保護者や園児への急な対応など、そういった部分に関係なく全職員で協力して行っているといったところです。もっと効果的なといいますか、より実践的な共有の方法といったところについても、ぜひ工夫して実現に向けていきたいと思ってあります。","id":"exchange-035"},{"speaker":"せお副委員長","kind":"提案","question":"報道があったので東京都にも確認しましたが、保育園のお散歩で園児を置き去りにしてしまう事故が９４件あったということです。そこで、ヒヤリハットは園から品川区にどのように報告していますか尋ねました。","respondent":"柏原子ども未来部長","answer":"それから、そういった園でのヒヤリハットの事例についてです。今、いろいろなやり方がありますけれども、ご提案の内容も含めて検討を進めていきたいと思ってあります。","id":"exchange-036"},{"speaker":"せお副委員長","kind":"質問・要望","question":"そこで、今回はオアシスルームの運用をどのように変更するのでしょうか。ベビーシッターとオアシスルーム共通の課題と言っていいのでしょうか、在宅子育てをされている障害児をお持ちの方は特に、潜在的に思っています。","respondent":"柏原子ども未来部長","answer":"オアシスルームの運用の変更といいますか、１回の面談で済むというところに見直しまして、運用を変えていくといったところです。周知の仕方は工夫が必要かとは思ってありますけれども、そういったことが分かりやすいような形で、広く周知できればと思ってあります。","id":"exchange-037"},{"speaker":"せお副委員長","kind":"提案","question":"そこで、渋谷区の導入方法を、まずは実際に現場でシミュレーションしてみてはどうでしょうか。シミュレーションすることについてと、やってみての課題を共有することについて、ご見解を伺えたらと思いますとの意見を述べました。","respondent":"柏原子ども未来部長","answer":"品川区の今の運用のやり方で、どこでどう合うのか、合わないのか。今ご提案いただいた渋谷区の事例もそうですけれども、ほかの事例等もきちんと詳細な調査を行った上で、次の検討に進めていければと思ってあります。","id":"exchange-038"},{"speaker":"せお副委員長","kind":"質問・要望","question":"２か所目をずっと要望しておりました。１０月からの新事業者には、この考え方を持って事業再編をしていただきたいですが、区の見解を説明を求めました。","respondent":"伊崎福祉部長","answer":"障害児本人の最善の利益の保障や家族支援の重視、２か所目の児童発達支援センターが、各所管で連携して検討していきたいと考えております。","id":"exchange-039"},{"speaker":"せお副委員長","kind":"提案","question":"様々、課題解決のため、まずは区が主体で、区内事業者の連絡会をつくってはいかがでしょうか。では、お話を伺った広島市のように、そこをセットで取り組めないかと考え、提案させていただきましたとの意見を述べました。","respondent":"伊崎福祉部長","answer":"昨年度は、放課後等デイサービスと児童発達支援の合同の連絡会を実施することができたのですが、メール等での情報共有等を行っております。今後も在宅人工呼吸器使用者の方が安心して生活できるよう、関係機関と連携して支援してまいります。","id":"exchange-040"},{"speaker":"せお副委員長","kind":"質問・要望","question":"ぜひ支援計画と非常用電源に早急に取り組んでいただくよう要望いたします。そこで、そのような主に精神的な部分で、今まで教育委員会としてＨＥＡＲＴＳの職員へどのような取組をしてきたか尋ねました。","respondent":"米田教育次長","answer":"学校や関係機関と連携を重ね、対応しておりますが、心理的なストレスを抱えることもあります。教育総合支援センター長や担当係長、定期的なミーティングを行い、情報共有や対策の検討を行っております。","id":"exchange-041"},{"speaker":"せお副委員長","kind":"質問・要望","question":"最後に、すまいるスクールとの連携について伺います。すまいるスクールと教育委員会の連携の場を設けていただきたいと要望しますが、こちらも見解を説明を求めました。","respondent":"米田教育次長","answer":"経費面や設備管理、衛生管理など課題が多く、現時点では実施は困難であると考えております。今後も引き続き、すまいるスクールと学校、あるいは庁内関係部門でも連携して、様々な課題の解決を図ってまいりたい、このように考えてあります。","id":"exchange-042"},{"speaker":"せお副委員長","kind":"質問・要望","question":"子ども未来部と教育委員会に様々考えていただいているとは思うのですが、できるところから検討だけでも始めていってほしいとは思っています。以上で、自民・無所属・子ども未来を代表して、総括質疑を終了いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"のだて委員","kind":"質問・要望","question":"私からは、新型コロナ対策、羽田新ルートの一時停止、リニア中央新幹線の中止を求めて質問をします。いつでも誰でも無料でＰＣＲなどの検査ができるようにすべきだと思いますが、いかがか尋ねました。","respondent":"福内品川区保健所長","answer":"幅広く感染不安などの理由により検査を実施できることとなり、感染状況を踏まえまして、都内では１２月より薬局等で検査を実施しているところです。現在のところ、区として実施する考えはございません。","id":"exchange-044"},{"speaker":"のだて委員","kind":"質問","question":"つまりは、幅広い無症状者への検査の必要性は認めるのか、伺います。これで十分なのか、伺います。","respondent":"福内品川区保健所長","answer":"幅広い検査につきましては、現在、東京都によって行われておりますので、それで賄われていると考えております。現在２５か所で実施されておりまして、１日３件程度のところもありますが、１０件から１５件の検査を実施しているところもあると認識しています。","id":"exchange-045"},{"speaker":"のだて委員","kind":"質問・要望","question":"感染第６波での残業が月８０時間を超えていた保健予防課の保健師・事務職の人数、月の残業時間、平均と最大を伺います。来年度予定していた７人を採用できなかった理由は何か、伺います。","respondent":"榎本総務部長","answer":"今後は、段階的な職員の増員も含めて、機動的な職員体制の構築について引き続き検討してまいります。７名採用に向けて、面接を実施してきましたけれども、結果として２名の埋め合わせができなかったです。","id":"exchange-046"},{"speaker":"のだて委員","kind":"質問","question":"１年目だけでなく、数年いた保健師も退職してしまうという話も聞いています。保健師が定着しない理由は何か、改善策をどう考えているのか、伺います。","respondent":"榎本総務部長","answer":"経験の浅い職員が多いため、やはり２年目、背景に育成の難しさがあるのではないかと分析しております。保健行政を取り巻く状況を勘案しつつ、採用と育成のバランスをよく考えながら、引き続き増員を図っていきたいと考えています。","id":"exchange-047"},{"speaker":"のだて委員","kind":"質問・要望","question":"過去最高の特別区民税などは、苦しんでいる区民への支援にこそ活用することを求めて、次の質問に移ります。伺います。","respondent":"中村都市環境部長","answer":"区は国の求めに応じまして、落下物対策の義務化、それから駐機中の機体の抜き打ち検査といった取組を進めてきていることが説明されてきております。対策の着実な実施、取組内容について理解を深めてもらうための丁寧な説明を、引き続き国に求めてまいります。","id":"exchange-048"},{"speaker":"のだて委員","kind":"質問・要望","question":"なぜ、コロナで減便になっている間だけでも一時停止を求めないのか、改めて伺います。羽田空港の国際便は、コロナ前から何割減便になっているのか、伺います。","respondent":"中村都市環境部長","answer":"区へもそうした声もありまして、国にも確認しておりますけれども、国は速やかな復便のために継続していくとしております。国内線は旅客便で１７％減だということです。","id":"exchange-049"},{"speaker":"のだて委員","kind":"質問・要望","question":"原因が究明されるまで、羽田新ルートの使用中止を求めるべきです。いかがか尋ねました。","respondent":"中村都市環境部長","answer":"航空機由来とは断定はできないです。こういったことを求めることは、今、検討の予定はございません。","id":"exchange-050"},{"speaker":"のだて委員","kind":"質問","question":"国が調査して、落下した痕跡はないということでしたけれども、それはもう調査は終わったということなのか、伺います。このことも防がなければ、やはり区民への被害が出るということになりますので、どうすれば防げるのか、伺います。","respondent":"中村都市環境部長","answer":"それから、落下物につきましては、今まで国からは、落下物対策総合パッケージというものが２０１８年に公表されまして、実施されてきております。","id":"exchange-051"},{"speaker":"のだて委員","kind":"質問・要望","question":"事実が認められた場合は、直ちに中止を求めるべきですけれども、いかがでしょうか。この間も、部品脱落件数は増えておりますので、そうした下でどうやったら防げるのか、改めて伺います。","respondent":"中村都市環境部長","answer":"これまで０件だったというところですので、安全性は十分確保されていると、区としても認識しております。ただ、これはずっと続けていかなければいけないというものですので、この落下物対策については、不断の努力を国に求めてまいります。","id":"exchange-052"},{"speaker":"のだて委員","kind":"質問・要望","question":"必要性、環境破壊、新幹線の４倍の電力消費、事業性など、問題だらけのリニアは中止すべきだと、共産党は求めてきました。計画ルートの沿道４０ｍで家屋調査が進められていますが、家屋調査の対象件数と、調査が終了した件数を伺います。","respondent":"末元都市整備推進担当部長","answer":"家屋調査の対象件数は約２,０００件で、北品川地区から国道１号線までエリアを順次実施しています。調査が終了した件数については、ＪＲ東海からは示されてございません。","id":"exchange-053"},{"speaker":"のだて委員","kind":"質問・要望","question":"調査結果の説明は、ルート上の町域ごとに教室型説明会を実施することをＪＲ東海に求めるべきです。調査掘進の結果、本格掘進、つまりトンネル工事を中止する場合もあるのか、伺います。","respondent":"末元都市整備推進担当部長","answer":"ＪＲ東海からは、調査掘進後の説明会については、沿線の各地区を対象に、オープン型説明会を開催していくと聞いてあります。調査掘進の結果、トンネル工事を中止する場合もあるのかですが、これにつきましては、事業者であるＪＲ東海が判断すべき事柄と認識しています。","id":"exchange-054"},{"speaker":"のだて委員","kind":"質問・要望","question":"町会長など住民が求めているのですから、ぜひ実施するよう求めてほしいと求めました。リニアで陥没事故が起きないと言えるでしょうか、伺います。","respondent":"末元都市整備推進担当部長","answer":"トンネル施工検討委員会を開催するなど、様々な対策を検討し、適切に工事を行うとしています。令和３年１０月より調査掘進が開始され、周辺への影響と対策の有効性を実地で試行していると聞いてあります。","id":"exchange-055","title":"町会・自治会支援"},{"speaker":"のだて委員","kind":"質問","question":"５ｍ幅、地上に影響がないとしてきた前提の大深度地下法の欠陥が浮き彫りになっており、住宅街の真下を通るリニアも直ちに中止すべきです。以上で私の質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"},{"speaker":"中塚委員","kind":"質問・要望","question":"そして再開発中止の３点を伺います。そこで、抗議文提出に至った経過や理由を伺います。","respondent":"榎本総務部長","answer":"品川区以外でも同様の動きがありまして、区議会の決議が可決されたことを受けて、足並みをそろえてやることが効果的であると考えたためです。武力による解決ではなく、国際連合憲章が求める紛争解決の手段により、紛争の収束を図るべきと考えております。","id":"exchange-057"},{"speaker":"中塚委員","kind":"質問・要望","question":"いかがでしょうか。品川区は、ロシアによるウクライナ侵略の解決には、さらなる国際世論が必要だと思うのか、伺います。","respondent":"榎本総務部長","answer":"ただし、「軍の撤退を求め」と書いてある点につきましては、防衛・外交に関わる面があるため、区の立場は少し異なるものです。ロシアは国際世論に真摯に耳を傾けるべきであり、各国は紛争解決に向け、あらゆる平和的手段を講じるべきと考えております。","id":"exchange-058"},{"speaker":"中塚委員","kind":"質問","question":"区立保育園、幼稚園の廃園は検討すべきではないと思いますが、いかがでしょうか。品川区は区立認可保育園について、そして区立幼稚園について、検討すべき問題とは何だと考えているのか、伺います。","respondent":"柏原子ども未来部長","answer":"こういったところから、保育園・保育の供給量の適正化を考え、検討していく時期に入っているのだというところで捉えているものです。幼児教育無償化の影響も考えられますけれども、私立幼稚園とともに、これは検討していく時期だというところで捉えているものです。","id":"exchange-059"},{"speaker":"中塚委員","kind":"質問","question":"検討すべき問題は何かと伺ったところ、認可保育園および幼稚園について、現在のありようについて適正化が必要だと話がありました。区立認可保育園・幼稚園を減らしていく検討ではないと明言できるのか、改めて伺います。","respondent":"柏原子ども未来部長","answer":"これに対して、ニーズの数に対して適正な供給量を検討するというのは、事業の運営サイドとしては当然のことであると捉えてあります。そういった数の部分を含めての検討ですので、結果として適正な数というのはどういったものかというものを検討していくものと考えているものです。","id":"exchange-060"},{"speaker":"中塚委員","kind":"質問","question":"適正な数とは何かとお話がありましたが、つまりは減らす検討だということなのでしょうか。きちんとご説明ください。","respondent":"柏原子ども未来部長","answer":"適正な数、適正な供給に関する数を検討したいですので、それが結果的に、目指すべきといいますか、到達すべき数の値になってくると思いますので、それが供給量についての適正化を図るといったところの検討だというものです。","id":"exchange-061"},{"speaker":"中塚委員","kind":"質問","question":"ここでは「数の供給」と述べましたが、この数とは、区立認可保育園の園数を指すということでよろしいのか、伺います。そして、何が問題なのか、改めて伺います。","respondent":"柏原子ども未来部長","answer":"応募の数も減ってきているといったところもあります。適正な供給量とはどういったところにあるのだというのを検討するというところで、数という意味においては、そういった意味を持っているものです。","id":"exchange-062"},{"speaker":"中塚委員","kind":"質問・要望","question":"結局は、区立保育園に係る人件費削減が、品川区の待機児解消策ではなかったのでしょうか。区立認可園および幼稚園の園数を減らす検討はやめるよう改めて求めますが、いかがか尋ねました。","respondent":"柏原子ども未来部長","answer":"これはトータルで考えて、供給の数というのはどういったものが適正なのかというのを検討したいと言っているところですので、その到達点として。","id":"exchange-063"},{"speaker":"中塚委員","kind":"質問・要望","question":"区は、地権者がなぜ反対しているのか、その理由をどう考えているのか、伺います。そして、なぜ今までどおりの住宅や、今の場所での今の商売が選択できないのか、伺いたいと思います。","respondent":"末元都市整備推進担当部長","answer":"再開発に反対されているという点については、今の住環境が変化すること、あるいは生活再建の不安を抱えておられることと認識しています。次に、なぜ今のままの住宅の場所や、今の場所で商売ができないかです。","id":"exchange-064"},{"speaker":"中塚委員","kind":"質問","question":"その反対の理由を、変化する方が不安を抱えているとおっしゃいましたが、具体的にどういうことか、改めて伺います。そして、なぜ今のままの住宅や今の商売が今の場所でできないのか、改めてしっかり、答えるよう求めました。","respondent":"末元都市整備推進担当部長","answer":"先ほどの、やはり今の慣れ親しんだ住環境、あるいは慣れ親しんだ商売のやり方というものが変化することについての不安だったりと考えています。","id":"exchange-065"},{"speaker":"中塚委員","kind":"質問","question":"計画に反対し、同意もしていないのに、なぜ本組合に強制加入させられるのか、なぜ土地と建物を取り上げることができるのか、伺います。そして、その根拠となっている都市再開発法は何条で、どういう仕組みなのかを伺います。","respondent":"末元都市整備推進担当部長","answer":"新しくできる建物の床の権利に置き換える手続を、都市再開発法第８７条の規定に基づきまして、従前の権利はなくなるものです。区は、法令に基づく手続を適正に進めるとともに、事業主体である再開発組合に対して働きかけてまいります。","id":"exchange-066"},{"speaker":"中塚委員","kind":"質問","question":"なぜ強制加入か、なぜ土地を奪うことができるのか、その仕組みを改めて伺いたいと思います。要するに、同意がなくても土地・建物を奪い取れるということなのか、伺います。","respondent":"末元都市整備推進担当部長","answer":"都市再開発法第８７条です。一旦、従前の権利は第８７条により消滅いたしますが、事後に、従後の権利に置き換わるというものです。","id":"exchange-067"},{"speaker":"中塚委員","kind":"質問","question":"土地も建物も一方的に奪いながら、どこが、住むことも転居も自由に選べると言えるのか、伺います。こんなことはやめるべきだと思いますが、いかがか尋ねました。","respondent":"末元都市整備推進担当部長","answer":"新しい建物に床の権利を受け取ることも、補償金を受け取り、事業地外に転出することも、権利者自身が選択できる仕組みとなっています。まちの課題を解決していくため、地域主体で検討されているまちづくりが早期に実現するよう、今後も引き続き支援してまいります。","id":"exchange-068"},{"speaker":"中塚委員","kind":"質問","question":"これを、追い出しと呼ばずに何と呼ぶのか、伺います。改めて、従わなければ奪い取る、選択の余地を与えないとは、再開発はあまりにもひどいと思わないのか、伺います。","respondent":"末元都市整備推進担当部長","answer":"地域内の各権利者がそれぞれに権利を主張しているだけでは、まちは何も変わりません。土地の高度利用を図り、新たに道路や公園等の公共施設を整備することで、防災性の向上やにぎわいの創出を図ることが重要だと考えております。","id":"exchange-069"},{"speaker":"中塚委員","kind":"質問","question":"それはあなた方ではないですか。伺います。","respondent":"末元都市整備推進担当部長","answer":"区としましては、先ほど申し上げました再開発事業の趣旨について、一人でも多くの権利者の方々にご理解いただけるよう、事業主体である再開発組合に対して働きかけてまいります。","id":"exchange-070"},{"speaker":"中塚委員","kind":"質問・要望","question":"こうした再開発に税金を１,５００億円もつぎ込む、住民合意のまちづくりを求めて、総括質疑を終わりたいと思います。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-071"},{"speaker":"くにば委員","kind":"質問","question":"お伺いします。製造業の支援、活性化の取組、重点施策についても説明を求めました。","respondent":"久保田地域振興部長","answer":"平成２８年の経済センサス調査でも、製造業は区内全業種の付加価値額の第１位であり、区としましても、主要業種の一つと認識しています。区の主要業種であります製造業に対する支援としましては、展示会への共同出展の支援、引き続き活性化に向けて積極的に展開してまいります。","id":"exchange-072"},{"speaker":"くにば委員","kind":"質問","question":"次に、ものづくり人材育成についてお伺いいたします。学校への出張授業なども実施し、再度、ものづくり人材の育成を拡充してはいかがか尋ねました。","respondent":"久保田地域振興部長、米田教育次長","answer":"区はこれまでもいろいろな取組を進めてきたところですけれども、近年では製造業の人材確保支援というものに対して重点的に取り組んでいるところです。品川区産業支援交流施設で… ものづくりの取組と学習ということでは継続して行われておりまして、ものづくり教室を行い、サッカーレゴロボットなどの取組を行っているところです。","id":"exchange-073"},{"speaker":"くにば委員","kind":"質問・要望","question":"昨年１０月の衆議院議員選挙以降、参議院議員選挙と区長選挙を見据えて、何か新しい施策は展開してきたのでしょうか。お伺いいたします。","respondent":"齋藤選挙管理委員会事務局長","answer":"区長選挙の投票率についての認識ですが、区議会議員選挙では、そういった広報が十分されておりません。今後はマイナンバーカード、マイナポータルを活用いたしまして請求できるようにして、より簡便な形で投票できるように努めてまいります。","id":"exchange-074"},{"speaker":"くにば委員","kind":"質問","question":"品川区も、人出の多いショッピングモールや高校の校庭などにバスで出向き、移動式期日前投票所の実施を検討してはいかがでしょうか。投票所に足を運ぶ人に比べると、熟考せずに投票してしまう懸念があるのではと思いますけれども、その点のお考えを説明を求めました。","respondent":"齋藤選挙管理委員会事務局長","answer":"様々な投票率向上の取組の一つと考えておりますので、今後も研究させていただきたいと思います。１回投票して、それが習慣化するということは、投票率向上につながるものと認識しております。","id":"exchange-075"},{"speaker":"くにば委員","kind":"提案","question":"このような、３９歳以下が１.７％しかいないアンケートが、年齢のバランスを考慮していると言えるのでしょうか。年５回程度開催している区政モニター集会を、三十代を増やすのであれば、平日午後だと参加可能な方が限られてしまうのではないか尋ねました。","respondent":"堀越企画部長","answer":"やはり私どもといたしましては、その部分につきましては、どのような仕組みがいいかというのは検討していきたいと思ってあります。そうすると、高校生の方などというような、様々な課題が考えられますので、そういった面についても検討していきたいと考えているところです。","id":"exchange-076"},{"speaker":"くにば委員","kind":"質問・要望","question":"併せて、漫画などを用いたポスターを、若い方々が集まる施設やイベントで掲示・宣伝するなどの策を講じたほうがよろしいのではないでしょうか。具体的な改善策についても、何かお考えがあれば説明を求めました。","respondent":"堀越企画部長","answer":"そういった部分も含めて、どのようなことができるのかというのは検討していきたいと思ってあります。今ご指摘いただいたデジタル化の部分も含めて、様々な方法があると思いますので、検討していきたいと思ってあります。","id":"exchange-077"},{"speaker":"くにば委員","kind":"質問・要望","question":"次に、品川区世論調査における区民の定住意向についてお伺いいたします。「交通の便がいいから」、「災害に強いから」が１.４％から９.３％に大幅増、「治安が良いから」が６.３％から３４.５％に大幅増となっています。","respondent":"堀越企画部長、滝澤災害対策担当部長、久保田地域振興部長","answer":"世論調査におきましては、近年の災害の頻発化を踏まえて、災害に関しての項目を定住性に関するご質問の中に加えております。繰り返しになりますが… これまでの世論調査の傾向としまして、阪神・淡路大震災後や東日本大震災後に、防災への関心が非常に高まっているのは事実です。自主避難施設の開設や… 町会・自治会の防犯カメラの設置助成や、まもるっち、また８３運動などを進めてきました。","id":"exchange-078"},{"speaker":"くにば委員","kind":"質問","question":"調査方式についても伺います。今年の秋に実施する第２５回品川区世論調査も再びネットと郵送での回答方式にするのか、検討状況を説明を求めました。","respondent":"堀越企画部長","answer":"コロナというところもありまして、今回、そういう形で、回答数につきましても一定のものが得られたと思ってあります。ですので、より回答しやすくという観点から考えましても、次回につきましてもこの方法で実施させていただきたいと考えているところです。","id":"exchange-079"},{"speaker":"くにば委員","kind":"質問・要望","question":"続きまして、介護職員の待遇改善についてお伺いいたします。款別審査で藤原委員が介護職員の賃上げを求めたところ、やはり保険制度の中で賃金が定められているので、賃上げは困難といった考えを示されました。","respondent":"伊崎福祉部長","answer":"これらを実施することで、介護職員の人材の確保および業務効率化の取組の強化を図ってきているところです。来年度は新たに介護職の魅力発信事業を新規事業として実施し、介護職員の確保と定着にさらに力を入れていきたいと考えております。","id":"exchange-080"},{"speaker":"くにば委員","kind":"質問・要望","question":"魅力があるから働いてほしいというような、それは、やりがい搾取につながりかねないと考えています。続いて、高齢者福祉施設に導入しております、ＩＣＴ見守りシステムについて伺います。","respondent":"伊崎福祉部長","answer":"令和２年度に、今ちょうどやっているところですが、八潮南特別養護老人ホームに導入しております。情報等を民間施設に周知するとともに、区といたしましても、しっかりと計画的に進めていきたいと考えております。","id":"exchange-081"},{"speaker":"くにば委員","kind":"質問・要望","question":"ぜひとも品川区でも、胎児１人のという考え方をしていただきたいのですけれども、そちらについての、まずは見解をお聞かせください。そして、この制度の実施をぜひとも願っておりますけれども、その実施の可能性についてもお伺いいたします。","respondent":"福内健康推進部長","answer":"多胎児の支援についてですが、妊娠期から親の身体的・経済的負担が大きく、また育児についても様々な悩みや困難さがあると認識しております。子育て家庭を支援するため、妊婦全員を対象とした相談事業を実施しておりまして、胎児の数だけお渡しする。","id":"exchange-082"},{"speaker":"くにば委員","kind":"提案","question":"ホームページの具体的な問題点、改善提案と要望を約５０項目、書き連ねて提出いたしました。品川区ホームページの問題点の根っことなっている点をお伺いいたしますとの意見を述べました。","respondent":"堀越企画部長","answer":"それで、各課のコンテンツにつきましては、管理・運営に関しては各課で行うという形になってあります。いろいろな助言や調整をしながら行ってきておりますので、さらに見やすいホームページになるように努めていきたいと考えています。","id":"exchange-083"},{"speaker":"くにば委員","kind":"意見","question":"そのような現状のクオリティのばらつきを打開する方策など、何かお考えがありましたらご答弁ください。再度、所管課に任せるなど、方向性や検討を説明を求めました。","respondent":"堀越企画部長","answer":"生活支援、まずは正確な発信に努めながら、その中でどのようにしていくか。いい事例や、そういったものを共有していくというのが大事かと思っていますので、そういったことも含めて考えていきたいと思ってあります。","id":"exchange-084"},{"speaker":"くにば委員","kind":"意見","question":"それらの見解をお聞かせください。併せまして、ホームページ全体のリニューアルの検討状況、今後のスケジュールをお教えくださいとの意見を述べました。","respondent":"堀越企画部長","answer":"次に、先ほど申し上げましたホームページの運営要綱におきまして、広報広聴課と各課の役割分担等を定めております。さらに見やすくするためにどうするかという部分、今お答えしたものの仕組み化やルール化といったことも含めて考えて、努めていきたいと考えています。","id":"exchange-085"},{"speaker":"くにば委員","kind":"質問・要望","question":"最後に、今から申し上げることは、庁内のあらゆる部局にお伝えしたい要望です。ぜひともその点、ホームページの広報の際に意識していただきながら、ホームページ作り・更新をしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-086"},{"speaker":"田中委員","kind":"質問・要望","question":"生活者ネットワークはかねてより、子どもの意見表明・参加を促進する施策を求めてきましたが、なかなか前に進んでいないように感じています。子どもの最善の利益を優先するためにも、都の補助金を活用すべきですが、現在の検討状況を伺います。","respondent":"柏原子ども未来部長、米田教育次長","answer":"今ご紹介がございました、東京都の令和４年度の予算ということで、子どもの意見表明・参加促進、理解促進事業等々のお話を頂きました。そうした東京都の動きを注視しながら… 今、子ども未来部長からもありましたが、教育委員会としても、理解促進事業に関しましては、詳細につきまして、まだ情報が示されていないという状況ですので、同じような内容になります。","id":"exchange-087"},{"speaker":"田中委員","kind":"提案","question":"改めて、子どもの意見表明とアドボケイトの仕組みを、区長部局と教育委員会にそれぞれ求めますが、見解を伺います。２つの提案について、それぞれ見解を伺いますとの意見を述べました。","respondent":"柏原子ども未来部長、米田教育次長","answer":"在り方をいろいろ検討しているというところがありますが、そういった意見表明といいますか、意見を聞いているという機会があります。国の検討が今ちょっと止まっている状況ではありますけれども、区として新しく児童相談所設置の際に… グループでの話合いの仕方を身につけながら、発達段階に応じて、その後の社会に参画する資質・能力を高めているところです。","id":"exchange-088"},{"speaker":"田中委員","kind":"質問・要望","question":"そして区と区教育委員会としても、子どもたちに条例や条約の周知を積極的に行うよう求めますが、見解を伺います。結果、誰にとっても優しいまち品川となるよう求めますが、見解を伺います。","respondent":"柏原子ども未来部長、米田教育次長","answer":"都の動向・動きを見ながら、どういった形での周知が必要か、できるかというのは検討したいと思ってあります。保育課、本課で相談を受けながら対応して、必要な事業ができるようにということでやっているところです。 ただ、こども基本条例に関しては、東京都から具体が示されていないというのが現状です。出前授業等につきましても、今後の都の動向を注視してまいりたいと考えています。","id":"exchange-089"},{"speaker":"田中委員","kind":"質問・要望","question":"国が飛行機からの落下物の痕跡がないと結論づけた根拠はどこにあるのかを示すよう、区は強く国に求めるべきですが、見解を伺います。そして、飛行機由来の氷塊であると、事実関係が明らかになった場合には、品川区は新ルートの廃止に踏み込んで申し入れるべきですが、見解を伺います。","respondent":"柏原子ども未来部長、中村都市環境部長","answer":"本課がそれに対応するということになったり、近隣の園に相談して譲ってもらったりといった、都合をつけたりという措置をしております。そういった状況です。 これ以上の調査というのは、現物がない以上はなかなか難しいのかと、区としても考えております。したがいまして、このことを原因として、区が直接、中止云々ということは、現在検討するというところは考えておりません。","id":"exchange-090"},{"speaker":"田中委員","kind":"質問","question":"改めて区として、どうやって区民に注意を促すのかという部分も伺いたいと思います。そして、区は区民の立場に立った対応で国へ対応してくださるのか、伺います。","respondent":"中村都市環境部長","answer":"それで、落下物を発見した場合の連絡先についてですけれども、これは国からもかねてから説明もありましたけれども、まず警察への通報が第一です。様々、関連の部署に連絡していただければ、国へ連絡をするというふうになっております。","id":"exchange-091"},{"speaker":"田中委員","kind":"質問","question":"こういうことをしてください」ということを周知しているのでしょうか。周知すべきだと思いますが、それも併せて伺います。","respondent":"中村都市環境部長","answer":"落下物が発見された場合は、国が責任を持って調査を行うと、航空事業者と共に対応していくということを確認しています。これは、区も区民の立場に立って対応していくというつもりです。","id":"exchange-092"},{"speaker":"田中委員","kind":"質問・要望","question":"より専門的な情報と調査力を持つ国と事業者が落下物でないことを明確に証明できないのであれば、落下物と認定すべきです。もし、区内で落下物が発生したときには、品川区も区民の立場に立った主張を、国と事業者に対して行うべきと改めて主張しますが、見解を伺います。","respondent":"中村都市環境部長","answer":"この事例が解決するまで、区民の窓口になりまして、国や航空会社に対応を求めていくという考えです。引き続き、証拠となるような物品が速やかに回収されますように、区としましても国に求めてまいります。","id":"exchange-093"},{"speaker":"田中委員","kind":"質問・要望","question":"先ほども伺ったのですけれども、もし区内で氷塊が落ちたときには、どうしたらいいのですか。小山三丁目に必要な施設等を庁内へ諮ったときに、要望が上がった項目の施設全てと、区が準備組合に要望した施設を全てお知らせください。","respondent":"中村都市環境部長、末元都市整備推進担当部長","answer":"ただ、それが難しいかどうかは別にしまして、状況に応じて、そんなご案内をするというふうに考えております。そして、実際には落下物の種類を問わず、国はこれまでも速やかに現地の調査をしているところですし… 福祉部からヘルパーステーション、小規模多機能型居宅介護または小規模多機能型居宅介護施設、あと介護予防活動拠点の要望がありました。","id":"exchange-094"},{"speaker":"田中委員","kind":"質問・要望","question":"白紙撤回を、ぜひ区長、区民の思いを酌み取り、自治体の長として求めてほしいと求めましたが、見解を伺います。つまり、地域にとって本当に必要な施設よりも、規制緩和率が優先され、施設が設定・設置されているのではないかと懸念しますが、見解を伺います。","respondent":"中村都市環境部長、末元都市整備推進担当部長","answer":"区としても引き続きの調査は求めてまいりますが、ただやはり難しいのかという考えは持っております。厳密な落下物対策を、引き続き国に求めていくというところで、中止云々というところではないと考えております。 それによってどんな緩和を受けられるかというのは、まさに今、行政と協議を進めているところです。先ほど申し上げたようにしておりますが、そこをあとどう判断するかは、民間事業の範囲の中で決められるものと考えています。","id":"exchange-095"},{"speaker":"田中委員","kind":"質問・要望","question":"内容証明で改めて求めたところ、幾つか求めた資料のうち、準備組合規約と令和３年度通常総会議案書は公開されたとのことです。伺います。","respondent":"中村都市環境部長、末元都市整備推進担当部長","answer":"渋谷区の事案につきましては、落下物と断定はできなかったというところであるとすれば、現在、落下物は羽田空港ではゼロという状況の中です。そういった中で、一時休止というところではなく… 個人情報の取扱いなど、適切に対応していると、再開発準備組合の事務局から伺ってあります。あくまで、まちづくりの団体の情報共有の場です。","id":"exchange-096","title":"町会・自治会支援"},{"speaker":"田中委員","kind":"質問・要望","question":"区として、区内全体の再開発事業の進め方について、一度立ち止まり、改善策を講じるべきと考えますが、見解を伺います。区民の理解も得られないと考えますが、見解を伺います。","respondent":"末元都市整備推進担当部長","answer":"話合いの進め方などについては、準備組合の運営につきましては、準備組合自らの責任においてなされるべきものと考えています。一人でも多くの権利者の方々にご理解いただけるよう、事業主体である再開発組合ならびに再開発準備組合に対して働きかけを進めてまいります。","id":"exchange-097"},{"speaker":"田中委員","kind":"質問","question":"そのことについて、区はどのようにお考えですか。伺います。","respondent":"末元都市整備推進担当部長","answer":"話合いが十分でないということをおっしゃっていただいていますけれども、先ほどからの繰り返しになりますが、一人でも多くの方々にご理解いただけるよう、再開発準備組合ならびに組合に対して働きかけてまいります。","id":"exchange-098"},{"speaker":"田中委員","kind":"質問","question":"見解を伺います。〔時間切れにより答弁なし〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-099"},{"speaker":"大倉委員","kind":"質問","question":"伺いますが、教育現場におけるタブレット端末導入による現状と課題をお知らせください。様々な職業の、より多くの職種の方々の話を聞ける機会をつくるということも有効だと考えますが、区のお考えを伺います。","respondent":"米田教育次長","answer":"これは学校におります学校地域コーディネーターの紹介等も行いまして、地域の方の協力を得て実施しているというところが、現状の基本です。近隣にいらっしゃらない職業の方からお話を伺う機会の創出につきましては、今後、検討を行ってまいりたいと考えています。","id":"exchange-100"},{"speaker":"大倉委員","kind":"提案","question":"全て要望を聞くというところだけではなくて、こちらから提案ということもされている中で、ぜひ進めてほしいと求めました。避難だけの避難訓練ではなく、より充実した防災教育につながると考えますが、区のお考えを伺いますとの意見を述べました。","respondent":"米田教育次長","answer":"東京消防庁と連携して、先ほど申し上げました消防庁のアプリを活用して、火災発生時の正しい対応について学んだところです。ご提案にもありました、各学校の工夫の中で可能性があるものと考えておりますので、今後も充実に努めてまいりたいと考えております。","id":"exchange-101"},{"speaker":"大倉委員","kind":"提案","question":"専門的な方からのアドバイスを受けられることは、子どもたちの成長や興味を喚起することに大いに役立つと思いますが、区のお考えを伺います。","respondent":"米田教育次長","answer":"生徒同士が意見交換をしながら、動画等を見ながら、フォーム等を見ながら互いに高め合っていけるような指導を実施しています。企業、学校の実態やニーズなどを踏まえまして、先ほどもありました関係課や体育担当の校長等とで協議・検討を進めてまいりたいと考えています。","id":"exchange-102"},{"speaker":"大倉委員","kind":"質問・要望","question":"地域のある風景が写った写真を２０枚、その風景を探してもらうという、タブレット端末を利用した取組がありました。ぜひ様々チャレンジをしていただきながら、活用について進めていってほしいと求めましたが、最後にお考えを説明を求めました。","respondent":"米田教育次長","answer":"子どもたちがより主体的に、対話的に、深い学びができるというようなことで考えているところです。今後も、このような全体の共有を図りつつ、タブレットやＩＣＴ環境のより一層の活用の充実に向けた取組を図っていければと考えているところです。","id":"exchange-103"},{"speaker":"大倉委員","kind":"質問","question":"次に、品川区の伝統工芸について伺います。品川区の伝統工芸品の特徴、特に収益性と技術継承について、お考えをお知らせください。","respondent":"久保田地域振興部長","answer":"こうした課題につきましては、伝統工芸保存会では、会員同士がコラボ作品などに取り組んだりして、課題の解決に向けて進めているところです。私のほうで一概にお答えすることはできませんが、品川区としましては、収益や人材の確保について支援してまいりたいと考えております。","id":"exchange-104"},{"speaker":"大倉委員","kind":"質問","question":"学校への出前授業、「伝統の技と味／しながわ展」などのイベント出店なども行っていますが、現在の活動状況について伺います。さらに、出前授業ですが、先ほども学校の中でタブレットの活用というところで様々伺ってきました。","respondent":"久保田地域振興部長","answer":"コロナ禍での影響についてですけれども、出前授業はここ２年、実施できていない状況です。しかしながら、令和３年度につきましては、令和４年の１月２９日と３０日に、感染症対策を徹底しまして実施したところです。","id":"exchange-105"},{"speaker":"大倉委員","kind":"質問","question":"先ほどもありましたが、品川区らしさのある品目というところでも課題があるのかと考えていますが、お考えを伺えればと思います。伝統工芸品をつくる方々と、品川区に限らず他自治体にある企業や学校などとの仲介を行うといった支援について、区の考えを伺います。","respondent":"久保田地域振興部長","answer":"先ほども申し上げましたように、引き続き、伝統工芸保存会等と意見調整をしながら調査・研究してまいりたいと考えているところです。私どもとしましては進めていきたいという意向はありますが、今後、進めていきたいと考えているところです。","id":"exchange-106"},{"speaker":"大倉委員","kind":"質問・要望","question":"次に、広報について伺います。これからも続けていっていただきたいと思っておりまして、連携していってほしいと求めましたが、説明を求めました。","respondent":"久保田地域振興部長","answer":"中小企業センターの１階ロビーでの実演や、様々な広報活動に努めてきているところであり、こうしたことも引き続き進めていきたいと考えています。４月から再開するですので、提案や要望をお聞きしながら、区としても支援を進めていきたいと考えています。","id":"exchange-107"},{"speaker":"大倉委員","kind":"質問・要望","question":"品川区民の住宅のそばに設置される恒久的な施設だと伺っていますが、品川区としても区民に向けて丁寧な説明の実施が必要と考えております。伺いますが、目黒川水質浄化対策検討会について、ご説明ほしいと求めました。","respondent":"藤田防災まちづくり部長","answer":"令和３年度は、検討会を１回、具体的な作業を進める作業部会については２回、開催されてあります。計画の概要を伝える説明会の実施に当たりましては、機械の設置場所の近くも含めて、令和３年１２月２日に説明会を開催したと聞いてあります。","id":"exchange-108"},{"speaker":"大倉委員","kind":"質問","question":"目黒川水質浄化対策検討会の議事録や記録、説明会の資料は、今、閲覧できるのでしょうか。お知らせください。","respondent":"藤田防災まちづくり部長","answer":"こうしたことを実施していくと聞いてあります。説明会については、説明の概要については確認することができるようになっておりますので、一定の情報提供はできているのかと考えています。","id":"exchange-109"},{"speaker":"石田（秀）委員","kind":"提案","question":"私たちの会派が地域の皆様や各種団体から頂いた声を基に要望や提案した施策であり、着実に具体化されることを望みます。そして、本日の総括質疑や款別審査において、我が会派の委員からの要望・提案も事業実施されることを要望しますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-110"},{"speaker":"若林委員","kind":"質問・要望","question":"令和４年度品川区一般会計、後期高齢者医療特別会計、介護保険特別会計および災害復旧特別会計の各予算案について賛成いたします。会派からの意見・要望を真摯に受け止められ、今後の区政へ活かされるよう要望し、意見表明といたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-111"},{"speaker":"高橋（伸）委員","kind":"提案","question":"東京２０２０大会レガシーを継承、保健所体制の強化、発達障害児支援の強化などが予算化されています。予算審査で会派所属議員が行った提案・提言が十分に事業執行に反映され、さらなる区民福祉の向上が図られることを望み、意見表明といたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-112"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"環境基本計画改定に当たり、２０３０年までにＣＯ２削減目標を２０１０年度比５０％に引き上げることを求めます。３５人学級を全学年に、さらに少人数学級へ進めることを求めますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-113"},{"speaker":"須貝委員","kind":"質問・要望","question":"世界で、国を守るウクライナを見捨てずに、世界平和をぶち壊すプーチン政権を倒すべきです。以上で、品川改革連合の意見表明を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-114"},{"speaker":"吉田委員","kind":"提案","question":"生活者ネットワークは、今からでも両計画の中止を国に対して求めるべきと主張します。ここまで生活者ネットワークが指摘・提案させていただいた意見を予算執行に活かしていただくことを要望し、意見表明といたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-115"},{"speaker":"大倉委員","kind":"提案","question":"引き続き丁寧な対応と併せて、過去２年間の経験をＢＣＰ計画へ反映し、迅速な対応ができるよう求めます。今回の予算特別委員会において、我が会派の所属議員が質問の中で指摘・提案した各項目を真摯に受け止め、予算を執行することを強く要望してとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-116"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/201716?Template=document&Id=1158#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":118374,"voices":265}},{"id":"r04-20220323-10","meetingId":"r04-cm03","date":"2022年3月23日","dateIso":"2022-03-23","committee":"議会運営委員会","time":"午前１０時３０分～午前１１時００分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/982514?Template=document&Id=5454#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":9546,"voices":35}},{"id":"r04-20220415-10","meetingId":"r04-cm04","date":"2022年4月15日","dateIso":"2022-04-15","committee":"議会運営委員会","time":"午後 １時００分～午後 ２時１９分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を17件整理しています。","topics":[{"id":"topic-01","title":"特別委員会の調査事項等","agenda":"特別委員会の調査事項等","exchanges":[{"speaker":"芹澤委員","kind":"質問・要望","question":"一般廃棄物処理基本計画が１０か年計画で、２０１３年度からスタートしているかと思いますので、ぜひまたご議論いただきたい。デメリットを両方ご検討いただいて、それぞれデジタル化を推進していただきたいという思いで、それぞれ項目を書いております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"あくつ委員","kind":"質問","question":"２番目の組織体制に関することということで、品川区もこれをやると言っていますので、どういう組織体制をやっていくのだと。３番目、これも代表質問等で私どももやりましたけれども、議論をしてはどうかということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"せお委員","kind":"提案","question":"自民・無所属・子ども未来からも、令和３年度と引き続き、行財政改革特別委員会と災害・環境対策特別委員会を提案したいと思います。この基本計画に関してもそうですが、品川区がどのように環境に対して配慮できるかというところを議論できればと考えていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"},{"speaker":"安藤委員","kind":"提案","question":"常任委員会の部署をまたがった調査が必要な点などから、４つの特別委員会を提案させていただきました。ＣＯ２削減、先ほどもありました環境計画の改定、自然エネルギーの推進、プラスチック削減ということで、提案しますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"須貝委員","kind":"意見","question":"現在、品川区には各所管において喫緊の重要課題がありますので、５つの常任委員会の審議時間を増やし、集中的に議論をするべきだと思います。医療などに対して、各常任委員会でしっかり時間をかけて議論するべきだと思いますので、特別委員会を設置することは反対しますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"},{"speaker":"芹澤委員","kind":"意見","question":"ほかの会派の皆様も、２つというご意見が多いのかと思いますので、私どもとしては、まず、２つを希望しています。新しい災害・環境対策特別委員会が入っていますが、これもまだまだ議論が必要なのだろうと思いますので、この２つを引き続き希望いたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"},{"speaker":"安藤委員","kind":"提案","question":"必要だと思う４つを提案したのですけれども、考え方として共通して出されたところでまとめていくということも１つの考え方だとは思うのです。そこら辺は、また会派の皆様の考えもあるでしょうから、少し柔軟に対応していくことが必要かなと考えていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"せお委員","kind":"質問・要望","question":"議員数などからも考えて、２つが妥当かなと思っています。災害・環境対策特別委員会もまだ１年ですし、そのまま継続で、行財政改革特別委員会と２つでやっていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"あくつ委員","kind":"質問・要望","question":"例えば、組織体制についてはいろいろと検討すべきだなと思うので、これはぜひ入れていただきたいなというところです。建設委員会から全部こちらに移管というか、特出しをしたほうがいいのではないかと、改めて考えを述べさせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"芹澤委員","kind":"提案","question":"おおむね、あくつ委員のご提案に賛成であります。先ほど、安藤委員からもご提案がありましたが、結構かぶっている項目が多いので、そこは重点的に拾っていただけるとありがたいなと思っていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"},{"speaker":"安藤委員","kind":"提案","question":"やはりＣＯ２の問題だと思いますので、私たちも提案させていただいているのですが、そういったところの削減というところ。その目標も、当然計画に入ってくるのですけれども、そこら辺をしっかりと調査していくような委員会になればいいのではないかなと思っていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"せお委員","kind":"質問・要望","question":"私たちから要望を出させていただいたところで見ていくと、また同時に進んでいくものかなとも思いますので、そこを含めたところ。清掃・リサイクルのところに大きく入ってくる項目であると思いますので、ここら辺もまとめて大きく議論ほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"安藤委員","kind":"提案","question":"私たちの提案の新型コロナウイルスのほうで、新型コロナウイルスのほうで特別委員会ということがなかなか一致できなのであれば、無理にそれを防災の中に入れていこうということではないということだけ少し補足したいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-013"},{"speaker":"あくつ委員","kind":"意見","question":"一応「食品ロスなど」と入れていただいているのですけれども、「食品ロス削減」と入れてもらえますか。ほかのものが「削減」ということで、「食品ロス」で終わっているので、一応形の上の話なのですが、との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-014"},{"speaker":"安藤委員","kind":"意見","question":"１点、ここは見過ごせないなというのが、行財政改革特別委員会の３番のデジタル化の備考です。「の活用」というのは、逆の方面からの議論も必要だったりするので、この「活用」というのは取っていただければと思っていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"},{"speaker":"あくつ委員","kind":"質問","question":"ただ、「マイナンバーの活用」というところにとどまって、それに対して賛否を論ずるということはいいのではないですか。活用するという前提ではないので、このままでいいのではないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"中塚委員","kind":"質問","question":"共産党自身はマイナンバー反対ですから、マイナンバー自身を議論の対象にすることに反対ではなくて、それは自由な議論で構わないと思います。マイナンバー自身は反対しているので、入り口からそのようなことだということで、あとは行財政改革特別委員会で大いに意見をぶつけ合ってください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/982514?Template=document&Id=5456#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":19317,"voices":94}},{"id":"r04-20220418-6","meetingId":"r04-cm04","date":"2022年4月18日","dateIso":"2022-04-18","committee":"区民委員会","time":"午後 １時００分～午後 ２時５３分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を21件整理しています。","topics":[{"id":"topic-01","title":"南品川櫻河岸まちなか観光案内所の開設","agenda":"南品川櫻河岸まちなか観光案内所の開設","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"２つ伺いたいのですけれども、改めてこの購入にかかった費用は幾らかということと、改修工事にかかった費用は幾らか伺いたいと思います。ぜひいろいろ活用していただきたいと思っているのですけれども、様々な対応をされていくと、併せて伺いたいと思います。","respondent":"篠田文化観光課長","answer":"改修にかかった経費ですけれども、こちら改修に当たっての調査・検討経費、合わせまして２,３５０万円余という金額になってあります。今後も、いわゆるロケーション対応ということで私どもの窓口になりまして、積極的に活用していただきたいというふうに考えているところです。","id":"exchange-001"},{"speaker":"くにば委員","kind":"質問・要望","question":"３点お伺いいたします。３点目ですけれども、内容の２番、３点お伺いいたします。","respondent":"篠田文化観光課長","answer":"なかなかちょっと見込みというものは立てるのは難しいところであるのですが、週に３日間、月木土という形で開設を想定していますので。","id":"exchange-002"},{"speaker":"くにば委員","kind":"質問・要望","question":"もちろん年間の委託料が２５０万円程度発生をし続けるということで、ぜひともシティプロモーションの観点で、活用してほしいと求めました。遠方のほうからいらしていただける方などを呼び込めるような形で、ぜひともそのＰＲのほう、積極的に進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"横山委員","kind":"確認","question":"２点お伺いいたします。１点目なのですけれども、確認なのですが、改修工事はどのように整えていったのかというところ、確認だけお願いいたします。","respondent":"篠田文化観光課長","answer":"倉庫として使っていたような雰囲気があったのですけれども、それがかなりきれいに磨き上げられたので、きれいになっているような状況です。インスタグラム等も含めて、イベント等の際に取り上げていくという形で対応してまいりたいというふうに考えているところです。","id":"exchange-004"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"１点だけお伺いいたします。しなロケの品川区フィルムコミッションの中にも、これは紹介をしていくということでよろしいか尋ねました。","respondent":"篠田文化観光課長","answer":"しなロケに関しましては、私どもも非常に力を入れているところです。１つ貴重なコンテンツが増えたですので、こちらも活用しながら、積極的に広報してまいりたいというふうに考えているところです。","id":"exchange-005"}]},{"id":"topic-02","title":"ブラインドサッカー応援プロジェクト「ガバメントクラウドファンディング」の実施","agenda":"ブラインドサッカー応援プロジェクト「ガバメントクラウドファンディング」の実施","exchanges":[{"speaker":"横山委員","kind":"確認","question":"１点だけ確認をお願いいたします。最終的には３００万円とあるのですけれども、１５０万円達成という段階で、そういったことは出てくるのか尋ねました。","respondent":"辻スポーツ推進課長","answer":"サイトの見せ方として、まず今目標金額１５０万円として、国内大会と代表選手の強化という、どちらも書いてあります。達成、１５０万円を超えた分に関しては、強化のお金等に使いますということをまた新たに追記するような形にさせていただいています。","id":"exchange-006"},{"speaker":"西村委員","kind":"意見","question":"４％ほど集まっていらして、何か周知のきっかけになるような取組を今後お考えかどうか、説明を求めました。","respondent":"辻スポーツ推進課長","answer":"今ちょうど始めて１週間というところなので、ちょっと伸び悩んでいるといいますか、芳しくないところというふうに認識しております。今はそのぐらいですので、区のバナーにも載せるということもちょっと検討させていただいて、広く集めて達成したいと考えております。","id":"exchange-007"}]},{"id":"topic-03","title":"令和元年請願第２１号、選択的夫婦別姓制度の国会審議を求める意見書を国に提出することを要望する請願","agenda":"令和元年請願第２１号、選択的夫婦別姓制度の国会審議を求める意見書を国に提出することを要望する請願","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひ前向きなお考えをお伺いできたらなと、冒頭述べておきたいと思います。１点質問ですけれども、この選択的夫婦別姓の国会審議を求める意見書の現在の状況ですが、現状を伺いたいと思います。","respondent":"吉野戸籍住民課長","answer":"令和４年３月２９日現在ですけれども、東京都１４区２１市、全国で３３７件になります。東京都に関しましては、令和３年６月７日に採択されております。","id":"exchange-008"},{"speaker":"中塚委員","kind":"質問・要望","question":"選択肢を増やす話ですから、皆が自分の思いを実現できる、そのようなものだと思います。この請願は、国会での審議を求める請願だということをぜひ踏まえていただいて、皆様に賛成をしていただけたらと呼びかけて終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"西村委員","kind":"質問・要望","question":"なかなか難しい部分はあるかなとは思っておりますが、今回のこの結果で夫婦同姓維持を希望している方、現行の同姓維持を求める声が国民の約７割と。選択的夫婦別氏制度の導入を求める声は３割弱ということが分かっております。","respondent":"吉野戸籍住民課長","answer":"先ほどご説明させていただいたとおり、令和３年度に関しましては、今度は一歩踏み込んだ内容になっております。そのため、言い回しがちょっと違うので、なかなか一概に比較は難しいかなと考えています。","id":"exchange-010"},{"speaker":"西村委員","kind":"意見","question":"今回の世論調査で私が個人的に注目すべきかなと思っている点が、２４.４％から４２.２％と大幅に増加した点かなと思っています。個人的な意見ですが、述べしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"くにば委員","kind":"質問","question":"そして全国で３１、令和２年が、都内１４区２２市、全国で２０７の自治体、先ほど令和３年に関しての数字はお伺いしたとおりです。まず、これらの要因などの分析を、品川区のほうではどう分析をなさっているのかということを伺いたいです。","respondent":"吉野戸籍住民課長","answer":"これはあくまでも、世論調査を基にさせていただきましたので、なかなかニーズのほうは高まっているのかなとは思っております。実は公的なところでの公表がありませんので、今これだけ請願、陳情が上がっているというところで把握した数になります。","id":"exchange-012"},{"speaker":"くにば委員","kind":"質問・要望","question":"やはり意見書の採択がどうしても区部で進んでいないことに関して、その点を知りたかったので、先ほどの質問をさせていただきました。１４区、あとは２２市と２１市、それぞれ見解と数字を説明を求めました。","respondent":"吉野戸籍住民課長","answer":"東京都は１４区、こちらのほうは間違いがありません。やはり国の動向がいまだにはっきりしていないというところが一番大きな要因ではないかなというふうに考えております。","id":"exchange-013"},{"speaker":"藤原委員","kind":"確認","question":"それが１４区でということの確認が１点。やはり女性のほうが維持するほうが少ないというふうに、数字に出ているのだと思うのですが、その辺についていかがか尋ねました。","respondent":"吉野戸籍住民課長","answer":"それから、１４区の請願なのですけれども、こちらのほうは変わっていないという認識でおります。最後の３つ目なのですけれども、委員もおっしゃるとおり、そういったところで意識が変わってきたために数値が下がってきているのかなと考えています。","id":"exchange-014"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"東京都が１４区ということだと思うのですが、品川区近隣の区というものはあるのかどうか、分かれば教えていただきたいということが１点です。区として、この７６１という数字は、これが多いのかどうなのか、どのように思われているのかということを伺いたいと思います。","respondent":"吉野戸籍住民課長","answer":"こちら、あと文京区は２回請願が出ております。実際には前回から、やはり７６１名の方が要望されていますので、多くなってきているかなというふうに考えております。","id":"exchange-015"},{"speaker":"中塚委員","kind":"質問・要望","question":"若干続けて伺いたいのですけれども、先ほどこの選択的夫婦別姓制度の導入を求める世論調査で、一概には比較は難しいという説明でした。一概には比較は難しいとは、改めてどのようなことか伺いたいと思います。","respondent":"吉野戸籍住民課長","answer":"今回に関しましては、平成２９年度と令和３年度を比べますと、夫婦同姓維持に関して、最初の選択肢、ここだけが唯一比較できるかなと考えています。","id":"exchange-016"},{"speaker":"中塚委員","kind":"質問・要望","question":"それは２人が同意をしたからそうしたのであって、いやいや、それも２人で話し合ったことなのだからいいのではないのかなと私は思います。あくまで国会審議を求める意見書の提出を求めるものだという、と求めている中、ご賛同いただけたらなと重ねてお願い申し上げたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"皆さんの議論を踏まえて、また確認だけさせてほしいと求めました。そのような方向で国にもしっかりと向き合ってもらいたいということで要望してきているところでありますが、現在、今ご報告をいただきました。","respondent":"吉野戸籍住民課長","answer":"今現在、令和４年４月現在なのですけれども、区民の方からの問合せ、相談等はありません。","id":"exchange-018"},{"speaker":"新妻副委員長","kind":"質問","question":"そのようなお考えもあるのかなとも思うのですが、そのようなお問合せは、意見はないということなのですね。引き続いて、ではそれに対して、区としてはどのように受け止めていらっしゃるのか、説明を求めました。","respondent":"吉野戸籍住民課長","answer":"やはり国の動向、こちらのほうがどのように動くのかというところに尽きるかなと考えています。国の動向によって、我々の進むべき道が分かるのかなと考えていますので、現時点では、国の動向を注視しているというような現状であります。","id":"exchange-019"},{"speaker":"中塚委員","kind":"質問・要望","question":"やはり自信といいますか、問合せがないということイコール求めていないというわけではないという点は、区に指摘をしておきたいと思います。国の動向を注視するということですけれども、それだけに区議会は意見書を提出して、区民の声を国に届けるべきだと述べたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"くにば委員","kind":"質問・要望","question":"あくまでこれは選択的夫婦別姓を強制的に求めるものではなく、そういった議論ですので、こちらに関しても中塚委員と同様の意見です。前々回等で採択を求めておりますし、ぜひとも全会一致でこの意見書採択を求めるという形で進めたいと、今回継続を求めるものであります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/227651?Template=document&Id=2924#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":17952,"voices":78}},{"id":"r04-20220418-7","meetingId":"r04-cm04","date":"2022年4月18日","dateIso":"2022-04-18","committee":"厚生委員会","time":"午後 １時００分～午後 ３時２６分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を47件整理しています。","topics":[{"id":"topic-01","title":"令和４年陳情第２０号、二度目の障害者福祉課窓口対応に関する改善の陳情","agenda":"令和４年陳情第２０号、二度目の障害者福祉課窓口対応に関する改善の陳情","exchanges":[{"speaker":"石田（秀）委員","kind":"質問・要望","question":"１つだけお伺いしたいのは、私はそんなに悪いことではなくて、それはそれですぐ対応したということでいいと思っている。電話してもそれは親切にやったと私は思いますが、そこら辺のことは役所はどのようにしようというふうになっているのか尋ねました。","respondent":"松山障害者支援課長","answer":"皆様からご提供いただいた個人情報については、例えば、あらかじめ明示した収集目的の範囲内で利用するということになっています。今回については、同じ相談で同じ人が対応したというところで、ご本人に対しては不利益を生じないように対応させていただいたものです。","id":"exchange-001"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"その辺もぜひその方にはご理解をいただければ非常にありがたいと思うので、書面でというのもあるのか、面会してその辺をご理解いただくのか。一部趣旨採択というのも変だから、そこら辺は文書でなくても、ぜひこういうことだとご理解いただくような対応をしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問","question":"今回の窓口改善としては３度目ということなのですけれども、今回はしおりの改正内容を失念して文書を渡すことができなかったということなのですけれども、ふだんはしおりとともに、改正された内容の文書というのは渡されているということなのか尋ねました。","respondent":"松山障害者支援課長","answer":"先ほどご説明いたしましたように、しおりと変更点の文書については、窓口でしおりをお渡しする際に併せてお渡ししているです。今回、失念したというところなので、窓口のところにも、しおりと添付をした文書をお渡ししていますという旨の表示を改めてさせていただきました。","id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、そのときはこうした改正内容がついていないことがあったように感じるので、本当についているのかというのが思うところなのです。３度にわたって陳情されているので、常に改正内容の紙１枚をつけて渡しているというのが、そこはいかがか尋ねました。","respondent":"松山障害者支援課長","answer":"全員の方に、改正内容とともに変更点があることを説明して一緒に渡すということで、改めて周知を図ったです。先ほどご説明しましたように、次年度のしおりにつきましては、組み込む形でお渡しができるかと考えています。","id":"exchange-004"},{"speaker":"石田（ち）委員","kind":"質問","question":"しおりに改正点を一緒に組み込むようになったのは、しばらくはされていなかったけれども、今回渡されるようになったということなのですか。この間、こういう陳情もあった上でセットにするようになったのか、そこの時点を伺いたいのですけれども。","respondent":"松山障害者支援課長","answer":"継続性というところでは非常に難しいこともありますので、しおりの中に１ページを組み込んで、しおりと一緒にお渡しする。しおりの中で変更点を掲載するようにするというふうに、今、業者と調整を図っているです。","id":"exchange-005"},{"speaker":"石田（ち）委員","kind":"質問","question":"それを回答できるようにということなので、窓口の方がそれを説明できるようにもなるということなのでしょうか。この方も変更点の説明をしてほしいということもあるので、そうしたことの徹底というのはどのようにされているのか。","respondent":"松山障害者支援課長","answer":"しおりの主な変更点についての説明です。課全体でそれぞれ係の担当職員がおりますので、担当職員につないで、担当職員が窓口に出てご説明をするという流れです。","id":"exchange-006"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そうしていただきたいですし、本当に残念だと私は思いましたので、引き続き工夫のほどよろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"鈴木（ひ）副委員長","kind":"確認","question":"その確認だけお願いしたいのが１点と、それから、これは大体８月頃に出ると思うのです。そこは令和３年度のことを反映されたものにしていただけないのかという思いがしているのですけれども、いかがか尋ねました。","respondent":"松山障害者支援課長","answer":"平成２９年の陳情の趣旨採択以来、変更点というのは障害者支援課独自で毎年作っているものです。変更点につきましてもホームページには掲載していますので、そちらもご覧いただければと考えています。","id":"exchange-008"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"それで書いてほしいと思ったので質問したのです。令和３年度のしおりが８月に出されるので、それであれば、令和３年度の変更点が入ったものということです。","respondent":"松山障害者支援課長","answer":"ただし、あるいは施設があるという概要を分かりやすくご説明するものですので、概要を載せて知っていただくのがしおりだと考えております。詳細につきましては、それぞれの担当から、説明の求めに応じてご説明をするという形を取らせていただきます。","id":"exchange-009"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"悩みを抱えながら、相談の窓口に行かれると思いますので、そこは気持ち的にも寄り添っていただいた対応をぜひお願いしたいと思っています。そこら辺の研修というのは、今、具体的にはどのようになっているのかという点についても伺えたらと思います。","respondent":"松山障害者支援課長","answer":"１回目を直近でやったところですけれども、毎年この時期に窓口研修ということで、まずは座学で行います。その後、実地ということで、ベテランの職員がついて、実際の窓口での研修ということになります。","id":"exchange-010"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"かなり様々な問題を抱えて相談をするというときに、プライバシーを保てる環境をつくっていただきたいというのを何人かの方から伺ったのです。新庁舎を検討するに当たっては、そういうところもぜひ配慮していただきたいというご意見も伺ったのですけれども、その点についてはいかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"もう一つ、このしおりというのは印刷物なので、印刷するときまでで、あとは、このしおりも全部、ホームページで掲載されるようになっていますよね。そういうところというのは、新しい情報がすぐにホームページに掲載される仕組みというのはつくられているのか、その点についても伺いたいです。","respondent":"松山障害者支援課長","answer":"東京都の指定を受けただけでは、なかなかこちらとしても確認ができませんので、東京都のホームページを見て確認した上で掲載をしています。ただ更新するだけでは埋もれてしまうので、そこをご覧いただけると、変更した最新の情報が分かるというような仕組みに変更しております。","id":"exchange-012"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"こういう陳情が続けて出されたというのは残念なことだったと思うのですけれども、こういうことを機会に、ぜひ対応をよろしくお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-013"},{"speaker":"若林委員","kind":"確認","question":"何点か端的に確認します。真ん中があって、どのブースで。","respondent":"松山障害者支援課長","answer":"どこのブースで相談を受けたかというご質問ですが、今のところ、詳細については不明です。","id":"exchange-014"},{"speaker":"若林委員","kind":"質問","question":"そういう詳細が、この場で出てこないということは少し疑問です。ということが１つと、お役目というか、担当というのはどういう方なのか尋ねました。","respondent":"松山障害者支援課長","answer":"確かに３つあるのですが、コロナ対策の観点から、右と左のブースをご利用いただくという形になっています。実は窓口職員はローテーションで対応しておりますので、今、情報がない状況です。","id":"exchange-015"},{"speaker":"若林委員","kind":"質問","question":"年間、窓口で、どのブースでも結構ですが、しおりは何冊渡されているのか。それから、改訂内容を書いた紙が何枚配られるのかというのはいかがか尋ねました。","respondent":"松山障害者支援課長","answer":"ですから、窓口で配るのは、残り２,０００部ほどになっております。なお、改訂用紙につきましては、同じ部数、３,０００部ということになります。","id":"exchange-016"},{"speaker":"若林委員","kind":"質問","question":"そうすると、２,０００部が窓口用ということで、では、年間何部ぐらい余るのか尋ねました。","respondent":"松山障害者支援課長","answer":"大体５００部程度は余る形なので、いつも毎年３,０００部ぐらいがちょうどいい部数だと認識しております。","id":"exchange-017"},{"speaker":"若林委員","kind":"確認","question":"お伺いしましたが、窓口の方は誰に聞いても良いか分からない」という記述、訴えがあります。この事実、これは一方的、陳情者のお話なので、まずこれが、対応した区としてこのとおりでいいのかどうか、確認させてください。","respondent":"松山障害者支援課長","answer":"担当した職員の対応についてです。ただし、こういった対応が、陳情者の方がそうお感じになられたとしたら、本当に申し訳なかったと考えています。","id":"exchange-018"},{"speaker":"若林委員","kind":"質問・要望","question":"厚生委員としては大変に残念だと思いますので、新しくしおりに１ページ入れ込んでやるというのは、これは本当にそのとおりだと。最後、感想みたいなものですけれども、またしっかり改善をしていただきたいと要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"その点お伺いさせていただきたいのと、この陳情の対応をもう一回確認させていただきたいのですけれども、今回はどのように対応されたのか。その２点お願いします。","respondent":"松山障害者支援課長","answer":"陳情の対応についてです。こちらは、陳情者の方が文書で改善策をお求めになられたので、文書で対応させていただいたという経緯です。","id":"exchange-020"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"では、陳情者の方は、その文書の対応で納得されたということで考えていいということか尋ねました。","respondent":"松山障害者支援課長","answer":"恐らく陳情者の方は、その前に陳情を出されているので、こちらの審議内容についても踏まえた上でお考えになることだと考えております。お求めに応じて、こちらのほうは謝罪したということも併せて、文書で回答させていただきました。","id":"exchange-021"},{"speaker":"高橋（し）委員","kind":"確認","question":"１つは、先ほどの携帯電話の話なのですけれども、分からないので確認したいのです。いろいろお話を伺ったのですけれども、それとも課全体というところに課題があったのか、それはどう思われますかということです。","respondent":"松山障害者支援課長","answer":"個人の職員はもちろん課に属しておりますので、特に個人の問題とするということは私は考えておりませんので、課全体として対応していく。ほかの方もありますし、また人事異動なりで人が替われば、その継続については課として取り組むべき問題だと考えております。","id":"exchange-022"},{"speaker":"高橋（し）委員","kind":"意見","question":"課全体で取り組んでいるというということで、先ほどいろいろご答弁されていましたので、そのことも含めて課全体でお願いしたいと思います。でも、課のほうで対応されたというのは、納得できましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-023"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"なぜかというと、先ほど少し話をしたけれども、一部個人情報の問題があるにしても、趣旨採択。こういう処理経過とかを出すことによって、課の中でいろいろな形でそれに取り組むことになると思うので、趣旨採択でお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"若林委員","kind":"質問・要望","question":"先ほど質問の中で意見、要望も言わせていただきました。形としては、前回同様、改善のこともありましたので、結論を出すで、趣旨採択ということでお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"要望させていただきましたけれども、そういったことも取り入れていただけたらと思います。採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"せお委員","kind":"確認","question":"扱い方のご確認をお願いしますということですので、先ほどの課長のご説明で、取扱いは適切かと感じています。窓口の対応のほうは、できる限りの改善をしていただけるというお話ですので、こちらの部分、趣旨採択でお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"高橋（し）委員","kind":"意見","question":"結論を出すで、先ほどいろいろお話ししましたが、本当に様々な課題があるのですけれども、課全体で、研修を含め周知徹底をしていくというお話がありましたので、趣旨採択で、その旨、陳情された方にもご説明ほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-028"}]},{"id":"topic-02","title":"東大井三丁目における都有地（都営元芝アパート跡地）を活用した特別養護老人ホーム等の整備","agenda":"東大井三丁目における都有地（都営元芝アパート跡地）を活用した特別養護老人ホーム等の整備","exchanges":[{"speaker":"石田（ち）委員","kind":"提案","question":"「事業者が提案する併設施設等を併設することも可能」ということが米印のところに書かれているのですけれども、もし提案等があればどれぐらい設置できるのかというのと、伺いたいと思いますとの意見を述べました。","respondent":"寺嶋福祉計画課長","answer":"説明会の後の事業者公募、我々のほうでは規模等を見込むことは難しいのですけれども、そのぐらいは建つのだろうと見込んでおります。最低定員８０人以上で、１割以上のショートステイを持ったということで、手堅い線でこれぐらいはいくだろうと見込んでいるところです。","id":"exchange-029"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"４階建てぐらいで８０人以上程度の特別養護老人ホームということで、ここは都の土地ですので、定期借地ということですよね。こういう形で返却が求められていくということなのか、伺いたいのと、幾らになるのかを伺いたいと思います。","respondent":"寺嶋福祉計画課長","answer":"５０年の定期借地といった場合、５０年経ったら更地にして返すというのは、そういう制度でやっているのはほかにもあると認識しています。","id":"exchange-030"},{"speaker":"石田（ち）委員","kind":"確認","question":"それで、５０年の定期借地というのは決まっていて、それ以上の延長というのは全くないものなのかというのを確認したいと思います。事業者にとっての今回のここへの建設のメリットというのは、区としてはどう考えているのか、伺いたいと思います。","respondent":"寺嶋福祉計画課長","answer":"東京都の建設費補助もありますし、一定程度低廉になるという見込みがありますので、運営できる法人の体力があれば可能であろうかと考えております。","id":"exchange-031"},{"speaker":"石田（ち）委員","kind":"質問","question":"この資料にも「都の施設整備費補助制度あり」というのがあるのですが、この建設に当たって、この都の補助制度しかない感じですか。品川区からの補助というのはない中で建設するということになるのか、伺いたいと思います。","respondent":"寺嶋福祉計画課長","answer":"区の事業に対して国や都から補助金が入るという例はありますけれども、都の事業に対して区から補助するというのは想定しておりません。都の建設費補助が、今のところ情報として持っている補助制度であると認識しております。","id":"exchange-032"},{"speaker":"石田（ち）委員","kind":"質問","question":"今年の５月下旬の住民説明会、これは住民というのはどのぐらいの範囲で行うのかを伺いたいのと、事業者公募要領はいつ頃出されるのか。都のホームページなどで公表はされるのか、伺いたいと思います。","respondent":"寺嶋福祉計画課長","answer":"説明会の対象範囲ですけれども、敷地の境界から３０ｍの範囲で案内のお知らせを配布するということで、準備を進めているところです。通常の建築物建設の説明会が、１５ｍを建てたとしても３０ｍまで案内しておけば、この範囲を設定したものです。","id":"exchange-033"},{"speaker":"鈴木（ひ）副委員長","kind":"確認","question":"そのようなものも想定されていますけれども、そういうのは想定されないのか、その点を伺いたいと思います。品川区が公募するのではなくて、東京都が公募するということであるのか、その確認もお願いしたいと思います。","respondent":"寺嶋福祉計画課長","answer":"事業全体のスキーム説明であるとか、先ほど言った説明会の段取りであるとか、公募の審査自体も区が行う。こういう表記をしていると捉えておりますので、事業者の公募は区のほうで、こういう役割分担が今のところ想定されております。","id":"exchange-034"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"ということは、東京都に対しての意見書を提出するというのは、公募を区が行って、第１次審査をやった結果として、区が、公募の第１次審査も踏まえた形での意見書という形で東京都に上げて、その結果で決まっていくみたいな、そんな感じの流れになるということか尋ねました。","respondent":"寺嶋福祉計画課長","answer":"意見書を出すというものの中の一番大きな要因は、やはり区のほうで１次審査をして、意見書の内容だと捉えております。それを東京都がいかように判断されるかは、また。","id":"exchange-035"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"今回の公募要領の中でも、全国から事業者を募集するということで考えられているのか、その点も伺いたいと思います。","respondent":"寺嶋福祉計画課長","answer":"そうすると、そこはまさに検討の部分だろうと思います。あえてそんなに制限をかける必要もないのかというところで、今、東京都も含めて最終調整をしているという状況です。","id":"exchange-036"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"例えば建設費用とかは、おおよそ１００ベッドぐらいの特別養護老人ホームを造る場合に、その点についても伺いたいと思います。１ベッド当たりおよそ９００万円となると思うのですが、それぐらいの整備補助ということで考えていいのか、その点についても伺いたいと思います。","respondent":"寺嶋福祉計画課長","answer":"１００ベッドの特別養護老人ホームを造ろうとすると、２０億円から３０億円ぐらいという、それぐらいはかかると。大体１００床造ると、１０億円弱ぐらいは補助金として入ってくるというのは、我々も計算はしております。","id":"exchange-037"}]},{"id":"topic-03","title":"品川区立心身障害者福祉会館の自立訓練","agenda":"品川区立心身障害者福祉会館の自立訓練","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"生活訓練の利用者が年々減少するという、その減少する理由を伺いたいのと、生活訓練の方は違う施設へということで、そうすると、品川区立心身障害者福祉会館では、自立訓練の生活訓練はもうやらないという判断になったということでいいのかということを伺います。","respondent":"松山障害者支援課長","answer":"機能訓練は生活訓練のサービス対応を内包して実施できるということで、ニーズが高まっているです。昨年度、品川宿という定員２０名の事業所ができておりますので、そちらを現状でもご利用いただいているです。","id":"exchange-038"}]},{"id":"topic-04","title":"を聴取します。 (3)母子健康手帳のリニューアル","agenda":"を聴取します。 (3)母子健康手帳のリニューアル","exchanges":[{"speaker":"せお委員","kind":"質問・要望","question":"私は２年ほど前から母子健康手帳のリニューアルを要望させていただいていたので、うれしく思うところです。そこら辺の考え方を聞かせてください。","respondent":"若生健康課長","answer":"いろいろな配慮が必要なお子様に対しての別の形での手帳等とのご質問と認識しておりますが、この健康手帳のほうが、厚生労働省のほうからも。","id":"exchange-039"}]},{"id":"topic-05","title":"新型コロナウイルス感染症に係る保健所・保健センターの対応","agenda":"新型コロナウイルス感染症に係る保健所・保健センターの対応","exchanges":[{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"１日の感染者数とかも併せてお聞かせいただきたいのが１点と、宿泊施設者が２０３人で、感染状況がどんな状況になっているのかを伺いたいと思います。陽性率についても、区の保健所としてはどう見られているのか、伺いたいと思います。","respondent":"坂野保健予防課長","answer":"ただ、ピークは３０％ほどで来ていますので、若干下がってきていると。若干下がってきているが、まだ結構高めで来ているということが言えるかと思います。","id":"exchange-040"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"３月のときよりもまた上昇してきているように見えるので、感染が増えているのか、そこら辺のところの評価というあたりも伺えたらと思います。学校とか保育園とか、そういうところの感染状況だったり、クラスターの状況というのがどんな状況になっているのかということも伺いたいと思います。","respondent":"坂野保健予防課長","answer":"東京都の今年の２月ぐらいです。クラスターということなのですが、これをもってクラスターという言い方をするかどうかというのは、いろいろ考えるところがあるところです。","id":"exchange-041"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"５人以上と言われるクラスターというのは、保育園にしても学校にしても高齢者施設にしても、現状というところでは起こっていないと捉えていいのか。第７波の懸念というのもされていますけれども、そこら辺のところは、どう見られているのかも伺えたらと思います。","respondent":"坂野保健予防課長","answer":"一つの施設で５人以上というところなのですけれども、単純に足して５人になったら、これはクラスターだろうという考えは私は取っていないのです。東京ではピークアウトしてきている感じですけれども、地方にあってはこれから増えてきているという印象はあります。","id":"exchange-042"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"たしか品川区で２５か所ぐらいですかね、それはたしか４月、それは延長されるということがあるのか。ぜひ延長していただきたいと思っているのですけれども、その点についても分かったら説明を求めました。","respondent":"坂野保健予防課長","answer":"今、東京都の事業については資料が手元にないのですけれども、東京都のほうは延長する。ただ、いつまでとか、そういうのは分かりません。","id":"exchange-043"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"延長されるということでよかったと思います。活用されているので、本当に検査が必要な人がしっかりと受けられるというところでは、ぜひ区のほうとしても進めていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"}]},{"id":"topic-06","title":"品川区新型コロナウイルスワクチン追加接種","agenda":"品川区新型コロナウイルスワクチン追加接種","exchanges":[{"speaker":"石田（秀）委員","kind":"質問・要望","question":"もう１点、１つは、そういう状況というのは起こりそうなのですか。それから、有効期限は来そうなのかというのを説明を求めました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"すみません、私、説明が１点漏れてしまいました。発信する予定ではありますが、皆さんに接種をしていただきたいという思いから、周知はしてまいりたいと考えています。","id":"exchange-045"},{"speaker":"石田（秀）委員","kind":"確認","question":"もう一つ確認なのだけれども、６人分とか、役所でも午後４時とかに急に呼ぶことがあったではないですか。それは日々廃棄しなければならないわけで、そういう量も結構あるというような話になっていたのだけれども、そちらはどういう感じなのか尋ねました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"実際問題として、１バイアルで６人分取れますが、やはり６人分の予約が入らないと、４人分とか５人分で、１人分が廃棄ということはあるというのは聞いております。","id":"exchange-046"},{"speaker":"石田（ち）委員","kind":"質問","question":"４回目の接種についてなのですけれども、厚生労働省から、２か月後に発送するようにという通知が来て以降は何も来ていない状況だけれども、５月中旬の発送を見込んで準備中ということで、これは、この後、厚生労働省から何もなくても発送してもよくて、接種を進めていくということでいいのか尋ねました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"５月中に送れるように準備をしなさいということが言われていますので、今、準備を進めているところです。最悪のことを考えて、今、どちらに転んでも動けるようにということで準備をしてしているとご理解いただければと思います。","id":"exchange-047"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/567724?Template=document&Id=3624#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":36953,"voices":158}},{"id":"r04-20220418-8","meetingId":"r04-cm04","date":"2022年4月18日","dateIso":"2022-04-18","committee":"建設委員会","time":"午後 １時００分～午後 ５時１１分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を72件整理しています。","topics":[{"id":"topic-01","title":"の１、幹部職員の異動","agenda":"の１、幹部職員の異動","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"まだ１か月経っておりませんけれども、感じているところを伺いたいと思います。７人か８人ぐらい乗られているということで、席は１０席ですか、それが大体埋まっているというような状況だということでした。","respondent":"鈴木都市計画課長","answer":"試行運行を開始して以降、４人から６人ぐらいの利用が、私が見る限りでは毎回あったかなです。いろいろ説明、京急のバス停は２０数本ありますので、しなバスが停留する時間帯の余裕もなかったです。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"近くの方からもお話をちょっと伺ったのですけれども、やっぱり中間に停留所が欲しいという意見もお聞きしました。そういった中で、今回、設置されていないわけなのですけれども、区のお考え、そして、この間の検討状況を伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"この付近にバス停を設置したかったというところは非常に思いとしてはあったのですが、やはり京急バスとの協議の関係上、ここでのバス停を断念したです。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問","question":"協議の結果ということなのですが、その中でどういった話合いがあったのかというところもお聞きしたいと思います。これはいつ頃、実施あるいは設置をされていくのか、見込みを伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"協議の内容をもう少し詳しくご説明しますと、やはり民間の路線バスを圧迫しないという考えから、ここでのバス停がなかなか難しかったです。先ほどご説明しましたように、利用者連絡会の立ち上げについては１２月頃というふうな予定ですが、そうしたことで考えているところです。","id":"exchange-003"},{"speaker":"のだて委員","kind":"質問","question":"停留所については、陳情にも書いてありますけれども、本数がやっぱり少なくて利用しづらいという意見があるわけです。停留所を設けていくということで、利用を促進することにもつながるのではないかなというふうに思うのですけれども、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"京急バスも、本数が少なくなっている理由としては、やはり利用者が少ないというところがこの路線の課題であるということで伺っているところです。やはり民間事業者の圧迫につながるところのバス停設置、違う方向に、今回の判断に至ったです。","id":"exchange-004"},{"speaker":"のだて委員","kind":"質問","question":"そうした民間とも協力というのですか、共存できるような形があるのではないかなというふうに思うのですが、最後に改めて伺いたいと思います。そういった方を含めて、移動を保障するということが必要だというふうに思うのですけれども、区のお考えを伺います。","respondent":"鈴木都市計画課長","answer":"路線バスを開始したわけですので、民間を圧迫するようなことはまず避けたい、するべきではないと。それはやはり区内で担っていただいている民間事業者を補完するという形で、これからも公共交通、取組を進めていきたいです。","id":"exchange-005"},{"speaker":"のだて委員","kind":"質問・要望","question":"最後に伺いたいのですが、どちらが駅の方向か分からないという声も伺いまして、今の協議の状況を伺いたいと思います。引き下げていただきたいと思うのですが、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"１点目の看板の設置ですが、いろいろ地域の声としてお聞きして、必要な検討をしていきたいです。先ほどご説明した利用者アンケートあるいは沿線の連絡会の中で、料金についても声はいろいろお聞きしながら必要な検討を行っていきたいです。","id":"exchange-006"},{"speaker":"のだて委員","kind":"質問","question":"最後に、西大井循環ルートの協議が整ったら、試行運行は３年あると思うのですけれども、その間に実証していくということか伺います。","respondent":"鈴木都市計画課長","answer":"そのとおりで、整い次第、バスを手配し、バス停を設置し、一刻も早く循環ルートも試行運行を開始していきたいです。","id":"exchange-007"},{"speaker":"西本委員","kind":"質問・要望","question":"カウントの仕方が、１つ確認なのですが、シルバーパスのカウントがきちんとされているかなと思うのです。そこを民間バスとのすみ分けをしっかりしながら、広報活動も必要なのかと思いますが、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"１週間なのかはこれからですが、１日の利用状況を、受託者が１日ずっと張りついて乗って利用者を集計するということも今考えてあります。考え方として、そうしたところの集計結果を踏まえて、よりよい利便性向上につながる広報をしっかりしていきたいです。","id":"exchange-008"},{"speaker":"西本委員","kind":"意見","question":"１か月後、２か月とかという形で時系列で見ていくということも１つの方法かもしれないので、そちらのほうにつなげられる可能性もあるのです。なので、その辺も調査研究していただきますようお願いして終わりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"},{"speaker":"芹澤副委員長","kind":"質問・要望","question":"端的に伺いますが、私はよくグーグルマップを使うのですけれども、しなバスのマップ検索はどういうふうに登録されていらっしゃるのか。これは当然、そういったウェブで検索したときに使えるようになっているのかだけお聞かせいただきたいのですが、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"基本的には、あるいは「品川区コミュニティバス」で品川区のホームページに飛んで、そこでルートはお示ししているというところが１点あります。そのほかについては、今いただいたご質問を戻って確認をしていきたいです。","id":"exchange-010"},{"speaker":"芹澤副委員長","kind":"質問・要望","question":"やはり検索にぜひ載せていただきたいと思っていて、登録すれば検索に引っかかるようになると思いますので、ぜひ前向きにご検討ほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"芹澤副委員長","kind":"意見","question":"今、協議をされていらっしゃるということで、その協議を見守っていきたいと思っています。非常に難しいものだと思いますが、ぜひ、なるべく使いやすい利便性の高いものをつくり上げてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"},{"speaker":"塚本委員","kind":"質問・要望","question":"試行が始まってまだ日も浅い状況ですし、やっていく中でいろいろなご意見はきっとあるだろうと思います。様々そこにお住まいの方々からご要望は出てきているという状況ですけれども、そういった個々のルートや停留所のご要望については。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"のだて委員","kind":"意見","question":"本日結論を出すということで、採択を主張します。やはりより使いやすくしてほしいという声ですし、住民の声でもあると思いますので、採択ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-014"},{"speaker":"西本委員","kind":"質問","question":"気持ちは非常に理解できますので否定するものではないのですが、現実問題どうなのだといったときに、難しいなという現状だと思います。今の状況では、かなり検討した結果がこうであるということがよく分かりましたので、不採択を主張いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"}]},{"id":"topic-02","title":"令和４年陳情第２１号、羽田増便による都心航路上の航空機から落下物が相次ぐ事態に関する陳情","agenda":"令和４年陳情第２１号、羽田増便による都心航路上の航空機から落下物が相次ぐ事態に関する陳情","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"その痕跡がないというのはどういったことなのか、どこをどう調査すると、そこを伺いたいと思います。そこも伺います。","respondent":"鈴木都市計画課長","answer":"基本的にはパイロットが気象条件等を考慮し個別に判断しているため、一概にどのタイミングでというところはお示しできないというのが国の言い方です。","id":"exchange-016"},{"speaker":"のだて委員","kind":"質問・要望","question":"つまり、風向きは違う方向だったということなのか、そこも確認させてほしいと求めました。ちょっと言い方は難しい、そういうふうになってくるのではないかと思うのですが、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"そのルートから落ちた場合に、当日の風速から考えて、３５０ｍ先のところに横にそれて落ちる可能性は極めて低いということでは聞いているです。","id":"exchange-017"},{"speaker":"のだて委員","kind":"質問・要望","question":"それと、航空機由来ではないという国の判断ですけれども、そうすると、別の理由は、どういったことが考えられるのでしょうか。なので、区としても、この調査を徹底的にやるように求めていただきたいと思うのですが、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"国の説明は、水平距離で東へ３５０ｍというところで、当日の気象条件からも勘案して可能性が極めて低いという言い方です。国の見解は、重ねてですが、可能性は極めて低く断定できない… 失礼いたしました。国の説明にありますように、区としても、さらに何か調査を求めるということは考えてございません。","id":"exchange-018"},{"speaker":"のだて委員","kind":"質問・要望","question":"陳情者の方は撤回を求める、私も中止を求めていくべきだというふうに思いますが、いかがでしょうか。中止をするということが、一旦止めるということが困難なのか、仕組み上どうなっているかというところを伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"１点目の今回の事案を含めて、氷塊に関しましては、冒頭ご説明しました落下物防止対策基準の中で氷塊に関する取組も定められているです。国は落下物防止の取組を進めているですので、こうした取組の確実な実施とともに、区としては国にしっかり働きかけていきたいです。","id":"exchange-019"},{"speaker":"のだて委員","kind":"質問・要望","question":"区は対策の徹底を求めていきたいということなのですが、やはりこれまでも徹底をしてきて。実際、国が判断を変えれば、やはり住民にも被害を与え続けている危険な羽田新飛行ルートは中止をすべきだと強く求めておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"西本委員","kind":"質問","question":"落下物の件なのですが、もしもこういうことが起きたときに、どういう説明があるのですか。例えば、このルートに関係する自治体に、直接、国交省から話があるのかということをまずお聞きしたいのですけれども。","respondent":"鈴木都市計画課長","answer":"今回の渋谷の件、それ以外、そうした事案が発生あるいは疑いがある場合は、直ちに直接国から、今回の件も品川区のほうに連絡が入っているです。","id":"exchange-021"},{"speaker":"西本委員","kind":"質問・要望","question":"そのときに、区として、責任の所在をどう国に求めていくのか。そこをはっきりさせてほしいと求めましたが、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"ルート下を外れて、３５０ｍ外れたところに落下したというところから、可能性が極めて低いというところで断定はできないという言い方です。この落下物の総合パッケージでは、いろいろ制度を変えて、早めに補償を受けられるような制度も新たに構築しています。","id":"exchange-022"},{"speaker":"西本委員","kind":"質問","question":"その中において、品川区の責任をどうとるのですかということを必ず言われますよ、必ず。なので、態度については、しっかり考えていくべき事例ではないのか、その案件ではないかなと思いますが、その辺はいかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"当然、区としては、しっかり国の責任において行っていただくよう国に求めていくという立場になろうかと思います。そうしたところは、区としても、引き続き国のほうには求めていきたいです。","id":"exchange-023"},{"speaker":"西本委員","kind":"質問・要望","question":"もうそろそろこの羽田新ルートについては、区としての考え方をまとめる時期に来ているのではないのでしょうか。私はそれを強く求めたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"芹澤副委員長","kind":"質問・要望","question":"継続でお願いいたします。固定化回避ということで品川区も国に求めていて、本事業については、引き続きこれは見守っていきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"塚本委員","kind":"質問・要望","question":"継続でお願いしたいと思います。区としても常に要望していただきたいですし、また、情報提供等もしっかりと迅速に行っていくということはお願いをしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"のだて委員","kind":"意見","question":"直ちに結論を出して、これはやはり落下物の危険があるという下でこの新ルートを実施すべきではないというふうに思います。騒音とか大気汚染などの問題もありますので、羽田新ルートは中止にすべきですので、採択ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-027"},{"speaker":"西本委員","kind":"質問・要望","question":"おかしいではないですか。なので、やっぱりこうやって陳情が出ているわけですから、ちゃんとした議論をすべきだと思うし、根拠のある中での議論をすべきだと指摘します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"}]},{"id":"topic-03","title":"令和４年陳情第２２号、リニア中央新幹線の教室型説明会を求める陳情","agenda":"令和４年陳情第２２号、リニア中央新幹線の教室型説明会を求める陳情","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"それが１か月でどれだけ進んだのか伺いたいと思います。そうした下で、いつ頃これをやられるのか伺います。","respondent":"中道まちづくり立体化担当課長","answer":"令和３年６月のシールドトンネルにおける安全・安心等の取組みの説明会、こちらは３００名です。実際に本掘進の前に調査掘進で、どういったところで取り組んでいくかというのは、また説明をしていきたいというふうに聞いているところです。","id":"exchange-029"},{"speaker":"のだて委員","kind":"質問","question":"今回いろいろ調査をするということで、振動とか騒音の調査もしていると思うのですが、その調査結果がどうなっているのか伺います。この調査掘進が、この１か月の間でどれだけ稼働しているのかというところも伺いたいと思います。","respondent":"中道まちづくり立体化担当課長","answer":"約３００ｍやるというところで、今、ＪＲ東海は第一三共と個別で調査掘進のことに関しては調整をしているというところは聞いているところです。今、分析中というところで、具体的に何かというところは示されていないところです。","id":"exchange-030"},{"speaker":"のだて委員","kind":"質問・要望","question":"実際には終わっていないということですから、中間報告もするべきだというふうに思うのですけれども、いかがでしょうか。そうしたところで、リニアも示していくべきではないかというふうに思うのですが、いかがか尋ねました。","respondent":"中道まちづくり立体化担当課長","answer":"今の説明会に参加された人数ですが、きゅりあんで行いました合同の説明会になりますので、そのほかの方たちも参加しております。丁寧に工事を進めているといったところで、もう少し調査をしていますので、そうしたところを区は注視していきたいというふうに考えてあります。","id":"exchange-031"},{"speaker":"のだて委員","kind":"質問","question":"このやり取りは定期的に行われているのか、どういった形でやられているのか、そこも伺いたいと思います。今回、地元説明の場の拡充ということでオープンハウス型の実施と書かれておりますけれども、このオープンハウス型を実施するとなった理由を伺います。","respondent":"中道まちづくり立体化担当課長","answer":"説明会であったり、最低でも５回は、そこの住民の方には情報は周知しているのかなというふうに感じてはあります。説明の伝え方といったところ、こうした教室型説明会が情報の場として適正か、または区民に寄り添った説明ではないかと聞いているところです。","id":"exchange-032"},{"speaker":"のだて委員","kind":"質問","question":"知らない人もいるという状況ですから、この教室型説明会もぜひ実施すべきだというふうに思いますが、いかがでしょうか。ＪＲ東海自身が、こうした工事を安全に行っていける事業者なのかどうか、区の認識を伺いたいと思います。","respondent":"中道まちづくり立体化担当課長","answer":"ＪＲ東海も、そうしたことを踏まえて、今までこういった形で関係資料の中に記載のとおり、説明会を開催してきたところです。区民に対して説明をしていくのか、そこを考えるのは、ＪＲ東海の責務かというふうに区は思っているところです。","id":"exchange-033"},{"speaker":"のだて委員","kind":"質問・要望","question":"柔軟にということですから、区としても実施することを求めていただきたいというふうに思いますが、いかがでしょうか。そうすべきではないと私は思いますが、そういう法律になっていると思うのですが、いかがか尋ねました。","respondent":"中道まちづくり立体化担当課長","answer":"先ほどの繰り返しになりますけれども、やはりここで区が何か限定的にこうした形で説明会をというふうに求めるものではないのかなと。そうした中で、やはり事業者の責任において、そこのやり方は、まずは検討していただくべきかなというふうに考えてあります。","id":"exchange-034"},{"speaker":"のだて委員","kind":"質問・要望","question":"限定的なことを求めるべきではないということですけれども、そうしたら、そこを確認させてほしいと求めました。私は、このリニア新幹線は中止をすべきだというふうに思いますけれども、いかがか尋ねました。","respondent":"中道まちづくり立体化担当課長","answer":"こうした中で陳情で教室型説明会といったことが出てきていますので、そうした声があるといったことは伝えていきたいというふうに考えてあります。","id":"exchange-035"},{"speaker":"西本委員","kind":"質問・要望","question":"確認ですが、これはＪＲ東海のやっている事業なのですけれども、品川区の位置づけはどういう関係になるのでしょうか。民間に対して品川区はどういう立ち位置で審議していけばいいのかなと思うのですけれども、そこをご答弁をお願いできますか。","respondent":"中道まちづくり立体化担当課長","answer":"１つに、大深度法を適用するときに、そうした委員会が開かれました。そうした立ち位置、位置づけといったところです。","id":"exchange-036"},{"speaker":"西本委員","kind":"質問・要望","question":"非常に品川区としても立ち位置が違うものですから、権限があるとかというのであれば、そこをはっきりしていただきたいということがあります。区としては、どういうふうにＪＲ東海に対して物申すことができるのだろうかというのが、こういうことはがんばれるみたいなところがあるのか尋ねました。","respondent":"中道まちづくり立体化担当課長","answer":"ですので、基本的には、今までもこういった区民に対しての説明とか工事の状況は、全てお願いという形でお示しをしていただいているところです。やはり教室型説明会が区民から求められているといったところで、そこは非常に協議の要る内容なのかとは思うのですけれども、なかなか。","id":"exchange-037"},{"speaker":"西本委員","kind":"質問","question":"こういうことは立ち位置が違うのですよというふうに、はっきりと態度を示していくことが私は必要だなと思っているのです。もっと説明してほしいという意見がありましたということは、今後、。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"芹澤副委員長","kind":"意見","question":"そういう個別具体的な話を特定して指示というか、依頼するのは、少し行き過ぎかなという思いで不採択とします。他方で、もちろん担っていく必要がありますので、事業者とそこは連携をしながら協力してしっかりと安心・安全をつくり上げてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-039"},{"speaker":"塚本委員","kind":"質問・要望","question":"本日結論を出すで、不採択でお願いいたします。働きかけということはやっていただきたいというふうには思いますけれども、本陳情については、不採択ということでお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"のだて委員","kind":"質問・要望","question":"もともとこのリニア中央新幹線は中止にすべきだと、工事をする上でも、説明会を住民に行っていくということは大前提だというふうに思います。教室型説明会の要望もあるわけですから、ぜひこれを行うべきだというふうに思いますので、採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"西本委員","kind":"質問・要望","question":"自分の住んでいるところの下を掘られているわけですから、その不安の解消という意味では、こういう声がありましたというのはお伝えしていただきたい。採択、不採択関係なく、お伝えしていただきたいなというふうに意見を申し上げたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"}]},{"id":"topic-04","title":"品川区まちづくりマスタープラン改定に向けた検討状況","agenda":"品川区まちづくりマスタープラン改定に向けた検討状況","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"そこの地域など、追加される部分、あるいは削除される部分があるのか伺います。ちょっと今はやめておこうとか、そういった位置づけが変更になるのかどうか、ここを伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"拠点市街地の整備については、今後もしっかり改定の検討、改定の計画の中でも位置づけていきたいです。２点目の特定整備路線につきましても、先ほどご説明したように、東京都と一体になってしっかり進めていきたいという考えです。まちづくりの取組についての現行計画をうたっているわけですが、それぞれの地域ごとで、この１０年間で新たに加わったものはしっかりうたっていくと。","id":"exchange-043"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうすると、位置づけの変更はないということかどうか、そこを確認させてほしいと求めました。今、ワークショップを行っていくということが必要ではないかというふうに思うのですが、その実施について伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"それから、今後、検討を進めていく上で、ワークショップの実施についてですが、改定委員会の中では公募区民の方にも入っていただいております。","id":"exchange-044"},{"speaker":"のだて委員","kind":"質問・要望","question":"その点も、ぜひマスタープランに位置づけていただきたいというふうに思いますが、いかがでしょうか。そこにさらに力を入れていくということが私は必要ではないかというふうに思うのですが、いかがか尋ねました。","respondent":"鈴木都市計画課長、竹田住宅課長","answer":"復旧・復興の考え方ですが、これも改定の中で継続していくのですが、より立ち上がりをスムーズにできるような取組は何かないか。先ほどご説明したインフラの二重化ですとか、考え方としてあるのは… 公営住宅の質問については、私のほうからお答えします。今後は、民間賃貸住宅の活用を通じて住宅行政を推進していきたいと考えております。","id":"exchange-045"},{"speaker":"のだて委員","kind":"質問・要望","question":"困っているという状況もありますので、再開発を位置づけていくということはやめていただきたいというふうに思いますが、いかがでしょうか。そうした中で、なぜ一定確保されていると言えるのか、ぜひ増設していくべきだというふうに思うのですが、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"のだて委員","kind":"質問・要望","question":"その一定程度確保されているというところを具体的に聞いたのですが、そこを説明していただきたいというふうに思います。復旧・復興のほうは、この復旧・復興について再開発をやめてほしいということで質問しているので、そこはぜひ答弁ほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"のだて委員","kind":"質問","question":"そこで聞きたいということで聞いておりますので、私の質問権を否定するということなのでしょうか。〔「そうじゃない、効率よくやろうよ、効率よく」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"こんの委員長","kind":"質問・要望","question":"質問権を認めないと言っているわけではございません。その再開発ということについて、同じご答弁が繰り返されるというふうに判断したものですので、そのように取り扱わせていただきたいということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"のだて委員","kind":"質問","question":"そうすると、皆さんは、復旧・復興のところで再開発が位置づけられているというお考えだということですか。今までのまちづくりのところでは、位置づけられてきたというところで、復旧・復興についても同じだということであれば、そういうことなのか尋ねました。","respondent":"こんの委員長","answer":"この中に明確な文章があるわけではありませんが、その防災の観点の中で考えていくというもので、そのような取扱いをするということにいたしました。","id":"exchange-050"},{"speaker":"西本委員","kind":"確認","question":"これは定義があるのですか。このひと中心、前はどのようなテーマでしたかということを確認をさせてください。","respondent":"鈴木都市計画課長","answer":"６ページの景観の整備と誘導というところは、４地区を行って進めているところですが、「道半ば」という表現で書かせていただいたところです。ある意味、それが、まちづくりの目標がテーマというところで掲げているところです。","id":"exchange-051"},{"speaker":"西本委員","kind":"質問","question":"だけど、今度は、ひと中心のまちづくりとは何ですかというところが、ちょっとリンクしないのです。なので、これ、庁内の調整をどうされているのかをお聞きしたいと思います。","respondent":"鈴木都市計画課長","answer":"先ほどのご説明でもお話ししたとおり、１行、２行の表現でしか説明させていただいておりませんので。庁内の横断的な検討体制ですが、外部の学識経験者等に入っていただいている庁内の改定検討会の前には、必ず１回目も２回目も実施しましたが。","id":"exchange-052"},{"speaker":"西本委員","kind":"質問・要望","question":"どういう表現の仕方、どういう視点が必要なのかということを、ぜひ検討というところで上げていただきたいなというふうに思っております。私らは独自でというわけにはいかない状況になるので、そこは調整を図って進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"塚本委員","kind":"質問","question":"すみません、１点だけ教えてください。例えば情報というものをどういうふうに位置づけるかとか、あるいは区民の健康だとか、どのような状況なのかということを説明を求めました。","respondent":"鈴木都市計画課長","answer":"今、情報的な考え方は、やはりまちづくりに今後どう生かされていくのかというところの考え方はしっかり示していくことになろうかと思います。","id":"exchange-054"},{"speaker":"塚本委員","kind":"確認","question":"ありがとうございました。健康とかというのは１つの、すごく注目というか、関心も出てくるのかなというところがあったので確認をさせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"}]},{"id":"topic-05","title":"東京都市計画、防災街区整備方針の変更","agenda":"東京都市計画、防災街区整備方針の変更","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"住民を追い出してまちを壊すものだということで、それを延長するものだというものですので、やはりこれは私は反対です。これをやはりやめるべきだというふうに思いますけれども、そこだけ１点伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"このエリア指定の基本的な考え方は、各特別区、各区が一体となって整備を進めていくという趣旨です。先ほどからご説明しておりますとおり、不燃化の助成を今実施していますが、さらに防災上の向上に向けた取組はしっかり進めていきたいです。","id":"exchange-056"}]},{"id":"topic-06","title":"の３、報告事項を再び聴取いたします。 (5)しながわ水族館リニューアルの方向性","agenda":"の３、報告事項を再び聴取いたします。 (5)しながわ水族館リニューアルの方向性","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"都民と書いてあって、世界を対象にしたと書いてあるのですが、この世界を対象にしたというのはどういうことなのか伺いたいと思います。やはりそれを今回もぜひやっていただきたいというふうに思うのですが、どういった仕組みでやっていくのか、そこを伺いたいと思います。","respondent":"高梨公園課長","answer":"成功している水族館の１つのキーワードとなっておりますので、リニューアルについては展示を考えていきたい、そのように考えているところです。","id":"exchange-057"},{"speaker":"西本委員","kind":"質問","question":"そこの分析はどうされているのか。いろいろな考え方が、動きがあってということは分かるのですが、それについて専門家の方々はどう見られているのかをお聞かせ願いたいと思うのですが。","respondent":"高梨公園課長","answer":"令和２年度、令和３年度の分析の中では、必ずしもイルカショーだけがしながわ水族館のアイデンティティではないというふうに考えているところです。その辺りを総合的に考えて、今回、イルカショーを終了するべきという決断を下したところです。","id":"exchange-058"},{"speaker":"西本委員","kind":"質問","question":"１つ２つ文句を言いたいなと思っている部分があったのですけれども、いろいろと工夫のしようがあるかなというふうには思っております。おかしいよね」というような人も出てくるのではないかと思うのですが、その辺の表現の仕方になるかと思いますが、いかがか尋ねました。","respondent":"高梨公園課長","answer":"ネガティブな考え方だけではなくて、その他もろもろの状況により、イルカショーの終了を判断したです。しながわ水族館も加入しています動物園水族館協会の協会としての新たに野生のイルカを捕獲しないといったような方針であるとか、一定、今回。","id":"exchange-059"},{"speaker":"西本委員","kind":"提案","question":"もう１つ、予算・決算特別委員会、いろいろな方々が提案していることがあると思うのです。区民公園とのコラボレートも考えなければならないし、観光という意味でも、その反映というのはどういう形で示されているか尋ねました。","respondent":"高梨公園課長","answer":"公募の準備を進めてまいりますけれども、しっかりと周辺施設との連携、まずは区としては準備を進めていく。しっかりとそういう条件を基に、事業者と周辺施設との連携については積極的に協議していく、そのように考えているところです。","id":"exchange-060"},{"speaker":"西本委員","kind":"提案","question":"今、これから公募されるということなのですが、ぜひ柔軟な考えの下、提案をいただきたいと思うのです。そしてアイデアをたくさんいただけるような促し方、それをぜひやっていただきたいというふうに思いますが、どういう方法をとられますか尋ねました。","respondent":"高梨公園課長","answer":"あまりプロポーザルの実施要綱の中で、運営について、あまりがんじがらめに細かい条件をつけるべきではないのかなというふうに考えてあります。","id":"exchange-061"},{"speaker":"本多委員","kind":"質問","question":"２つ目なのですけれども、ほかのニーズがたくさんある中で、その辺を総合的にどう取り入れられるのか。その辺のマッチングとか、総合的な考え、方向性だけ説明を求めました。","respondent":"高梨公園課長","answer":"２点目の都市型観光拠点といったところですが、様々なニーズに対応できるように関係所管と連携をしていきたいというふうに考えてあります。それと、競馬場等の窓口になっている総務課等々としっかりと連携しながら、進めていきたいというふうに考えてあります。","id":"exchange-062"},{"speaker":"塚本委員","kind":"質問・要望","question":"その辺の手だてはしっかりしているのかというところを確認させてください。１つ教育施設としての役割というところに、２４ページ、お話しできることがあれば教えてほしいと求めました。","respondent":"高梨公園課長","answer":"２点目の学術連携については、検討委員会のメンバーにも、臨海部の品川区のすぐ至近にあります東京海洋大学の教授にも参画していただいております。","id":"exchange-063"},{"speaker":"塚本委員","kind":"意見","question":"広く一般に価値があるような、そういったテーマでやっていただくようにしてほしいと求めましたので、よろしくお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-064"},{"speaker":"西本委員","kind":"質問・要望","question":"すみません、１点だけ。５頭いるということで、やっぱりそこは品川区を挙げてちゃんと送り出すということをぜひ考えてほしいと求めましたが、いかがか尋ねました。","respondent":"高梨公園課長","answer":"この間やってまいりまして、５頭のうち２頭はしながわ水族館産まれのイルカですので、前向きに検討していきたいと思います。","id":"exchange-065"}]},{"id":"topic-07","title":"下水道管老朽化対策事業（再構築事業）","agenda":"下水道管老朽化対策事業（再構築事業）","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"これ、老朽化対策工事が、この間、何度か出てきていると思うのですけれども、今どこまで進んでいるのか、どこまでやる予定なのかというところで、テンポ感も含めて伺いたいと思います。","respondent":"栗原河川下水道課長","answer":"雨水排除能力の増強、また耐震性の向上も図ります再構築事業を、２３区を整備年代によりまして３つのエリアに分けて対策を実施しております。そのうち最初に実施します第一期再構築エリアというエリアが、都心の処理区で実施するものでございまして、左岸部が。","id":"exchange-066"},{"speaker":"のだて委員","kind":"質問","question":"そうすると、ほかの地域のところは、品川区では今後進んでいくことになる、その辺りを伺いたいです。","respondent":"栗原河川下水道課長","answer":"南側のエリアに関しましては、第二期再構築エリアということで、本格的に再構築を実施するのは令和１２年度以降ということになります。","id":"exchange-067"},{"speaker":"のだて委員","kind":"質問・要望","question":"この下水道の老朽化ということで、やはり地震とか災害の問題もありますので、ぜひできるだけ迅速に進めていっていただきたい。前倒しでできれば、そうしていただきたいというふうに要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-068"}]},{"id":"topic-08","title":"の４のその他","agenda":"の４のその他","exchanges":[{"speaker":"西本委員","kind":"確認","question":"このＪアラートの確認は、何か月ごとにやっているのですけれども、これ、確認をして、どういう結果があったらどうするというのはあるのですか。お願いします。","respondent":"五十嵐災害対策担当課長","answer":"不具合が発生した場合、不具合の原因を調べるとともに、東京都および内閣府のほうに、そういった事情があったということをご説明します。","id":"exchange-069"},{"speaker":"西本委員","kind":"質問","question":"その不具合をどういうふうに検出するのですか。区民のほうから通報するという形なのか、それとも庁舎内の中での、そういう不具合があるということを検査するというか、調査する何かがあるのか尋ねました。","respondent":"五十嵐災害対策担当課長","answer":"システムが正規のとおり動いているかどうかを確認すると同時に、必ずＪアラートの試験をやった後、区民の方からの声が大体入ってまいります。それなども参考にしながら対応しています。","id":"exchange-070"},{"speaker":"西本委員","kind":"確認","question":"なので、その不具合だというところを、どういう結果に基づいて不具合がありましたという報告をするのですか。どうやってＪアラートが正常に作動しているかどうかということを確認していくのか尋ねました。","respondent":"五十嵐災害対策担当課長","answer":"「今、何が鳴ったのですか」とか、そういったところを確認した上で対応しています。国から東京都を経由して区までの流れについて、一応確認できるような体制はとっております。","id":"exchange-071"},{"speaker":"西本委員","kind":"質問","question":"区民の人たちは、その調査があるので、ちょっといつもと違うものが鳴るよということでいいですか。不都合があったというのは、あくまでも区役所の中での不都合だということで、区民の人たちは関係ないですよね。","respondent":"五十嵐災害対策担当課長","answer":"西本委員おっしゃるとおりです。内部の、機器の不具合の確認になります。","id":"exchange-072"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/985406?Template=document&Id=4346#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":70705,"voices":227}},{"id":"r04-20220418-9","meetingId":"r04-cm04","date":"2022年4月18日","dateIso":"2022-04-18","committee":"文教委員会","time":"午後 １時００分～午後 ３時２３分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を43件整理しています。","topics":[{"id":"topic-01","title":"教育目標の改訂","agenda":"教育目標の改訂","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"今回の改訂案に関する議論が教育委員会で行われた日はいつで、何回になりますでしょうか。それで、どんな意見が出て、どんな議論があったのか、ご紹介ほしいと求めました。","respondent":"宮尾庶務課長","answer":"令和３年１２月１４日、令和４年３月２４日、令和４年３月３１日です。このようなご意見も頂戴したところです。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"前回の修正が１年前ということですが、この２つを挙げた理由は何なのか、教えてください。子どもに直接関わる大きな社会状況の変化があったと思うのですけれども、それが入っていないのはなぜなのか、伺いたいと思います。","respondent":"宮尾庶務課長、矢部教育総合支援センター長","answer":"それから１つ、これは基本方針のほうになりますけれども、こちらも項目を増やさせていただいているです。長期基本計画の動向等、区の進める施策との整合性を、可能な限り合致させるというところで対応させていただいたところです。 きちんと進めてまいりたいと考えておりますし、子どもたちの権利は大事にしてきたと考えていますので、趣旨は盛り込まれているものと判断しています。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"教育委員会ですから、私は、ぜひその辺は盛り込むようにしてほしいと求めました。５つの柱のうち１番に来ていて、ここに子どもの権利をぜひ入れるべきだと思うのですけれども、いかがか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"「人権教育の推進」の（１）に、子どもという記載もありますし、（２）番の「子どもたちが」という主語でもあります。教育ですので、やはり子ども中心ということは我々変えようもございませんので、これからもしっかりやってまいりたいと考えています。","id":"exchange-003"},{"speaker":"安藤委員","kind":"意見","question":"今の（１）のところも、子どもの権利条約というところを入れるべきだと、改めてご意見申し上げますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"吉田委員","kind":"質問・要望","question":"（２）のところの「子どもたちが」とあるとおっしゃったのですけれども、（２）については、そのようにしてほしいと求めました。本日は意見だけにとどめます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"}]},{"id":"topic-02","title":"令和４年度 学級編制","agenda":"令和４年度 学級編制","exchanges":[{"speaker":"安藤委員","kind":"確認","question":"これは区の独自教員を充てているということでよろしいのかという確認と、どういう場合に、区教育委員会としては認めていらっしゃるのでしょうか。説明がありましたけれども、様々なケースというものがほかにあれば伺いたいと思います。","respondent":"勝亦学務課長","answer":"荏原第六中学校につきましては、教員の定数の配置の中で学級増ができるということで、既定の定数の配置の中で対応しています。こういった固有教員や定数の中で対応できるという中で、可能な限り丁寧な対応、丁寧な対応ができないかということで学校の中で検討し。","id":"exchange-006"},{"speaker":"安藤委員","kind":"質問・要望","question":"昨年でしょうか、今年は１年生も法律どおり３５人学級だということで、子どもの基礎的な教育環境の向上にとって非常によかったと思っています。４クラスのまま、なぜこうした対応の違いが生まれたのか、両者には何の違いがあったのかということを伺いたいと思います。","respondent":"勝亦学務課長","answer":"例えということで出てまいりましたけれども、同じ対応というような形では、一律な対応はしていないような形となっています。昨年、４学級で編成いたしまして、低学年が１年・２年・３年と４学級で並んでいるというような状況をそのまま持ち上がったと考えています。","id":"exchange-007"},{"speaker":"安藤委員","kind":"質問・要望","question":"無理にそのまま４クラスにする必要はないのかと思うのですけれども、やはり物理的な問題なのかどうかというのは確認させていただきたい。大崎中学校をはじめ、５つの中学校がありますけれども、なぜそうしたのか尋ねました。","respondent":"勝亦学務課長","answer":"今回２年生を５クラスにしてしまいますと、大きな変更や、できたら４学級で統一しているのが望ましいと考えたと聞いてあります。３５人で教員を加配いたしまして、集団指導で、中１ギャップに対応していくといった目的を持ってあります。","id":"exchange-008"},{"speaker":"安藤委員","kind":"質問・要望","question":"では全ての５つの中学校が、教員加配、教育活動がすばらしいものになるという判断の下で選択したという認識でよろしいでしょうか。最後に伺いたいと思います。","respondent":"勝亦学務課長","answer":"それから、少人数の学級規模の縮小という形で、中１ギャップへの対応に取り組んでいるところです。これからも、手厚い丁寧な子どもへの対応、少人数学級にしても、チームティーチングをそのような形でやっていきたいと考えています。","id":"exchange-009"},{"speaker":"安藤委員","kind":"質問・要望","question":"やはりまずは教育環境としては３５人というのをしっかり守った上で、そういう支援の仕方が求められているのではないかと、私は思いました。最後、質問だけ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"安藤委員","kind":"質問・要望","question":"令和７年度までには完全な３５人学級が求められているということで、令和７年度で法律が完全実施されると、もうできないということなのでしょうか。そういう法律の立てつけになっているかどうかだけ確認させてください。","respondent":"勝亦学務課長","answer":"法律の立てつけ上、令和７年４月以降は、弾力的な運用は経過措置に入ってございませんので、全て３５人学級という形になります。","id":"exchange-011"},{"speaker":"吉田委員","kind":"質問","question":"基本的なことを伺って恥ずかしいのですけれども、あくまで３５人学級を目指すまでという、できないところに弾力的運用ということなのでしょうか。このままでいけば２クラスでいいのだけれども、手がかかるお子さんがいるために３人などといって、その辺について教えていただけますか。","respondent":"勝亦学務課長","answer":"上限が３５人という部分につきまして、令和７年度に実施されるという形になります。","id":"exchange-012"},{"speaker":"吉田委員","kind":"質問","question":"では、３５人学級が実現したとして、そういう配慮が必要なお子さんが複数いた場合、やはりその対応というのは必要になるのではないかと思うのですけれども、それは弾力的運用が続くと理解してよろしいか尋ねました。","respondent":"勝亦学務課長","answer":"先ほども申しました固有教員ですとか、教員の定数の範囲の中では、そういった柔軟な対応は可能かと考えております。","id":"exchange-013"},{"speaker":"吉田委員","kind":"質問・要望","question":"だから、そういう意味では、この弾力的運用というのは前向きに活用できればいいと思ったので、今、質問いたしました。これは、あくまでこれからの教育に向けての要望ということで終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"松本委員","kind":"質問","question":"教員の人数というところで少しお伺いしたいと思っていて、令和３年度は２２学級増えていて、２年で４０学級以上増えているという状況だと思います。教員のほうも負担がどんどん増えていくのかと考えていて、教員の定員はどういうふうになっているのか、教えてほしいと求めました。","respondent":"中谷指導課長","answer":"基本的に、学級数が増えることによって、教員の定数も増えるという形になっておりますので、今回、子どもたちが増えたことによって、教員の数が増えないということはございません。","id":"exchange-015"},{"speaker":"松本委員","kind":"質問","question":"例えば令和４年にばっと増えてしまったときに、人事は４月に行われるのかと思っていて、４月には間に合うように増やしているという理解でよろしいのか尋ねました。","respondent":"中谷指導課長","answer":"子どもたちの数の見込みを校長として立てながら、学級数に応じた教員の数ということで見込んでまいりますので、そのとおりです。","id":"exchange-016"},{"speaker":"つる委員","kind":"質問・要望","question":"評価という意味で伺っているところでもあるのですが、松本委員の質疑と関連して伺いたいこともあるのですけれども、まず小学校６年生の数と。この３６％ぐらいのさらに内訳というのでしょうか、この三十数％の内訳が分かれば教えていただきたいというところと、担任等の確保ですね。","respondent":"勝亦学務課長、中谷指導課長","answer":"こちらで現在つかんでいる数字としましては、中学生の私立への進学率は３３％程度となっているというような状況です。こちらは今、集計中でございまして、５月の文教委員会で、その増減の割合については詳細を報告して… 人事については各学校で考えておりまして、特に２月の、まず教員数の確保が決まってくると。３月の大体上旬から中旬頃に、見込みで転入してくる教員が分かってくるので、各学校で校長が人事組織を組んでいくと。","id":"exchange-017"},{"speaker":"つる委員","kind":"質問","question":"１点伺っていたところが抜けているかと思ったのですが、３６％とか３３％とか、この辺で推移してきているところ。なぜそういう傾向がずっとあるのかというところ、どういう分析で捉えていらっしゃるかというのを併せて、それも併せて教えてほしいと求めました。","respondent":"勝亦学務課長","answer":"私立への進学率に関しましては、年々、大体１％ずつ上昇していると考えております。それぞれの分析については、もう少し時間を頂いて、考えさせていただきたいと思います。","id":"exchange-018"},{"speaker":"つる委員","kind":"質問","question":"こういう文教委員会での報告事項になるかどうかはあれですけれども、そういう品川区の教育の１つの成果、改めて伺っていければと思います。引き続き。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"}]},{"id":"topic-03","title":"令和４年度品川区立幼稚園、小・中学校、義務教育学校 園長・校長・副校長異動者名簿","agenda":"令和４年度品川区立幼稚園、小・中学校、義務教育学校 園長・校長・副校長異動者名簿","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"１つは、独自に充てるという考えなのでしょうかというのを、まず伺います。３点目は具体的なのですけれども、どういったときにこういうふうに、教えてほしいと求めました。","respondent":"中谷指導課長","answer":"３年間の内閣府での業務を任期満了ということで終えまして、今回、こちらに昇任ということで転任しております。今回は多少多くなっているかとは思いますが、それぞれに、学校の経営状況も含みながら異動状況を配置しています。","id":"exchange-020"},{"speaker":"安藤委員","kind":"質問","question":"区としては、新たにここに募集をかけて園長を雇うという気はないということなのか、その辺を伺いたいのが２つ目です。大規模校というのはほかにもあると思うのですけれども、２人目の副校長を置く基準というのですか、考え方があるのであれば説明を求めました。","respondent":"中谷指導課長","answer":"先ほど申し上げましたとおり、欠員状況があるというところがありますので、なかなか確保が難しいという背景があります。いろいろな状況がありますので、そういったところを総合的に判断した上での配置ということで取らせていただいております。","id":"exchange-021"},{"speaker":"吉田委員","kind":"質問","question":"それで、園長先生だからということなのでしょうか。幼稚園教諭の資格を持っていなくてよいのか尋ねました。","respondent":"中谷指導課長","answer":"他校種でもそうなのですが、管理職に関しては、このような他校種の配置ができるような形となっております。","id":"exchange-022"},{"speaker":"吉田委員","kind":"質問","question":"基本は園長先生として確保する場合の、その方の資格ということでいうと、どうなのでしょうか。できたら幼稚園教諭の資格者の中から採用していくけれども、それが難しいのでということなのか、その辺の考え方を説明を求めました。","respondent":"中島教育長","answer":"どちらの校長でもできるというように、この兼任の形で園長も、小学校の校長先生が実施することができるようになっております。実際に「そういうシステムですよ」というのをこれから説明していただくという状況にありますので、代わりに、説明をさせていただきました。","id":"exchange-023"},{"speaker":"吉田委員","kind":"意見","question":"教育長ご説明のとおり、できたら専任のということで、これからも努力を続けてほしいと求めました。ありがとうございましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-024"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"すみません。その他で１個だけ質問させてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"吉田委員","kind":"質問・要望","question":"予算特別委員会で取り上げられたのですけれども、その後、私どもも、昨年９月１４日開催の第１２回教育委員会の会議録を確認させていただきました。私どもも早速、資料５をくださいということを伺ったのですが、この件について文教委員会への報告はなかったと認識しております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"吉田委員","kind":"質問","question":"今ご説明のとおり、なるほどと思うところなのですけれども、教育委員会の会議録ではそこまで出ていなかったですかね。ＰＴＡ……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"吉田委員","kind":"意見","question":"要するに、学校にはすぐに伝達が行ったということは分かっております。それで、地域の方やＰＴＡへの報告はどの時点でどういうふうにされたのか、その点についてもご報告を頂ければ、頂きたいと思いますとの意見を述べました。","respondent":"矢部教育総合支援センター長","answer":"そして、保護者にも地域にもご説明するというのが筋でございまして、学校としては実際はそこからが周知になるということで考えております。ただ、必要な校区教育協働委員会やＰＴＡの会長にはお話ししている学校がほとんどだと認識しています。","id":"exchange-028"},{"speaker":"吉田委員","kind":"確認","question":"ＰＴＡへの報告については、どうしても３月とか、実際の土曜日授業の変更が始まる直前にならざるを得ないという理解でよろしいのでしょうか。その前に、ＰＴＡのしかるべき立場の方はもう既に把握しておられて、どうしても遅くなってしまうという理解でよろしいのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"安藤委員","kind":"質問・要望","question":"質疑というのは認められるべきだと思いますので、今後の委員会運営でも、ぜひその辺は柔軟に対応していただきたいという要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"}]},{"id":"topic-05","title":"「児童相談所開設に向けた計画書」の策定","agenda":"「児童相談所開設に向けた計画書」の策定","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"計画書の公開の方法はどうなっているのでしょうか。庁内の推進委員会をつくりましたけれども、メンバーをこの冊子の中に掲載すべきなのではないかと思うのですけれども、いかがか尋ねました。","respondent":"長谷川児童相談所移管担当課長","answer":"ホームページで計画書の公開を予定しておりまして、予定ですと明日、ホームページにアップする予定となっています。２点目としまして、計画検討委員会のメンバーということですが、設置に向けた計画検討委員会に関しましては。","id":"exchange-031"},{"speaker":"安藤委員","kind":"質問","question":"その検討過程も含めて、開所時間の点でそうした点が損なわれることというのはないということでよろしいのか、伺いたいと思います。これに照らして、人事異動の期間なども考える必要があるのではないかと思うのですけれども、いかがか尋ねました。","respondent":"長谷川児童相談所移管担当課長","answer":"特に、児童相談所における職種に関しては、児童福祉司と児童心理司というところで、庁内でも限定されていると認識しております。様々な支援サービスを理解した児童福祉司による指導が実現可能になるという点が、区の強みであると認識しておりますので、この点は。","id":"exchange-032"},{"speaker":"安藤委員","kind":"提案","question":"一つ、現場からの提案としましては、５年から１０年という、結構重い数字が出ておりますので、これも踏まえた上で考えてほしいと求めました。改めて、委託・直営のそれぞれのメリットというものを、どのように考えていらっしゃるのか伺いますとの意見を述べました。","respondent":"長谷川児童相談所移管担当課長","answer":"夜間休日対応をはじめ、他自治体での事例や業務に求められる専門性等の観点から、委託の可否を検討することが重要かと考えています。","id":"exchange-033"},{"speaker":"安藤委員","kind":"質問・要望","question":"結構、やはり高い専門性が求められる業務なのかというところで、果たして適切なのかという問題意識があります。よく分からなかったのですが、その辺は結局、つけることができるのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"安藤委員","kind":"意見","question":"そういうふうに、やはり正面からご意見が出たのかということで、そういう意見でしたとの意見を述べました。","respondent":"あくつ委員長、長谷川児童相談所移管担当課長","answer":"所管にはお伝えしているというようなことは聞いていますけれども、お答えできる範囲でお答えいただければと思います。職員が対応するのと同程度の対応が期待できるというところと、職員の２４時間３６５日対応体制を考える上では、委託にすることで。","id":"exchange-035"},{"speaker":"吉田委員","kind":"質問","question":"それをどういう体制でこれから進めていくのか、伺いたいと思います。だからこの計画の実施計画になるのでしょうか、例えば里親制度についてどういうふうに構築していくのか、現時点でお考えがあれば伺いたいと思います。","respondent":"長谷川児童相談所移管担当課長","answer":"あるいは庁内の子ども家庭支援センターと、今後も両輪体制で検討していきますので、プロジェクトチームという形で検討会議を持ちまして。いわゆる里親養育包括支援機関というフォスタリング機関のお話かと思いますが、実効性のある機関をこれから検討していきたいと考えています。","id":"exchange-036"},{"speaker":"吉田委員","kind":"確認","question":"確認させてください。このフォスタリング機関の在り方というのが、里親が具体的に機能していく中では重要かと思っているのですが、その点について確認させてください。","respondent":"長谷川児童相談所移管担当課長","answer":"児童相談所移管担当と子ども家庭支援センターとで中身の検討をしてまいりますので、里親制度であれば、里親制度の中身について検討していきます。委託のみではなく、そういったことも踏まえながら、広く検討していきたいと考えています。","id":"exchange-037"},{"speaker":"吉田委員","kind":"質問・要望","question":"この１８家庭から増えていくのか、それともこれは昨年３月時点なので、減っていくということも考えられると思います。取りあえず、今は、この計画に沿ってしっかりやっていただきたいという意見を申し上げて、以上としておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"つる委員","kind":"確認","question":"ちょっと教えていただいて、確認させていただいて、「分かりやすい通告窓口を検討しています」という現在進行形の形で書いていただいています。区が令和６年１０月に、今現在ある「１８９」を区内からかけると、まずここの確認だけ説明を求めました。","respondent":"長谷川児童相談所移管担当課長","answer":"通告窓口に関するお問合せです。児童相談所虐待対応ダイヤル「１８９」に関しましては、児童相談所に接続するのが適切と考えているところです。","id":"exchange-039"},{"speaker":"つる委員","kind":"質問・要望","question":"ただ、平成３０年に質問もさせていただいたのですけれども、これは無料化したほうがいいのではないですか。ただ、現時点において、いろいろな方法についてはどういうお考えか説明を求めました。","respondent":"長谷川児童相談所移管担当課長","answer":"それから「１８９」、どこを通告の第１窓口にするかというものは、全体を通じて検討していく流れになっております。区民にとって分かりやすく素早く対応できるという点は非常に重要なポイントと考えております。","id":"exchange-040"},{"speaker":"つる委員","kind":"提案","question":"そういう提案を求めたということも含めて、これは所管でしっかりと連携して、そこに対してどう対応が必要なのか。いやいや、自分たちの所管においては「１８９」で対応できれば十分だというようなことがあるのであれば、命綱の通告にしてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-041"},{"speaker":"吉田委員","kind":"質問・要望","question":"議事録を改めて確認したのですけれども、改めて品川区としてもそのようにすべきだし、事業者として私は報告すべきなのではないかと思います。それが、委員会報告の後どういうふうに確立されたかの確認を、できていたら教えてほしいと求めました。","respondent":"あくつ委員長、中元保育支援課長、立木保育課長","answer":"御会派としての様々なお考えを今述べられたのですが、我々がこの審査・調査予定表の中に載っている報告事項は、各委員からのご質問を頂いている。… 園から保護者の皆さんに対してもきちんと誠意ある説明がされ、管理職クラスの方が出向かれて、説明を受けられて。… 今回のケースに関しましては、中身の確認というところでは、きっちり運営されているという見方しかできないというところです。","id":"exchange-042"},{"speaker":"吉田委員","kind":"質問・要望","question":"ずっと質の向上ということを求めてきたのですが、保育の質の向上についての政策で予算がついたということを大変評価しております。以上、意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/921668?Template=document&Id=5062#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":41103,"voices":141}},{"id":"r04-20220418-5","meetingId":"r04-cm04","date":"2022年4月18日","dateIso":"2022-04-18","committee":"総務委員会","time":"午後 １時００分～午後 ２時５４分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を42件整理しています。","topics":[{"id":"topic-01","title":"請願・陳情審査","agenda":"請願・陳情審査","exchanges":[{"speaker":"渡部委員","kind":"質問・要望","question":"同時の竣工を要望しますというのは、質問する内容というよりも、委員の皆さんはいかがですか。そういう意味合いでも、議員間の質疑が必要かなと思うのですけれども、どうか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"おくの委員","kind":"質問・要望","question":"もともと建て替え自体に反対ですから、むしろ区民から求められているのは福祉施設、不採択を主張するつもりでおります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"須貝委員","kind":"意見","question":"それが第１点と、第２点として、新しい庁舎を中心とした地域が品川区のシンボルとして存在することが私は必要だと思います。健康を維持するという点ではいいのかもしれませんが、この場所で近くにまた新しくつくるということに関しては、私は反対ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"},{"speaker":"田中委員","kind":"質問","question":"今回は約８,３００m2の大きさというのが決まっていて、その中にアリーナをつくってほしいとか、とても無理ではないかなと思います。本当だったら陳情者の方に直接伺いたいのですけれども、どういうアリーナを想像しているのか、結構壮大です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"小芝委員","kind":"意見","question":"あまりにも時期尚早であるかなと思いますので、いろいろな社会の状況とか、地域の声も踏まえながら検討していくべきだと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"},{"speaker":"大倉委員","kind":"意見","question":"様々検討していくということなので、継続して、引き続き研究・検討していっていただければいいかなと考えていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"},{"speaker":"たけうち副委員長","kind":"意見","question":"にぎわい施設なのか、にぎわい的なものを考えていくというのは、ありなのかなと。アリーナも排除はしないのですけれども、今の段階では時期尚早なので、もう少し様子を見たいというところで継続がいいかなと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"渡部委員","kind":"意見","question":"多分、それぞれの会派でいろいろな考え方があって、にぎわいのつくり方も別にいろいろあると思います。皆さんの意見をどう取ってもそう取れて、考え方が違う人がいるから、決を採っていただいていいのかなと考えますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"},{"speaker":"田中委員","kind":"質問・要望","question":"障害者福祉施設を求めるものとかがありましたが、その際に、継続審査にはなっていないと思うのです。なぜこれだけ継続審査になるのか、障害者福祉施設を求めるものも、それをまた覆す状況を生むのではないかということを大変懸念します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"田中委員","kind":"質問","question":"６ページの平面図を見たときに、いつもの通りの質問になってしまうのですけれども、お知らせください。１０ページの電気設備工事の中に、それとも外部からの侵入者というか、外部を監視するものなのかといったところをお知らせください。","respondent":"小林施設整備課長","answer":"床暖房ですが、所管からは、乳児ほふく室、それから１歳児室等、小さな子どもが使う部屋に床暖房を設置する予定と聞いてあります。それから児童センターにつきましては、屋上であったり、あるいはエレベーターの中であったり、各利用室の諸室に設置するという計画になっています。","id":"exchange-010"},{"speaker":"田中委員","kind":"確認","question":"先ほど監視カメラが屋上にもあるというお話、児童センター利用者しか屋上が使えないということではないですよねというところの確認をさせてください。多分、保育園も使えるのかなと思うのですけれども。","respondent":"小林施設整備課長","answer":"園庭の一部を使用してプールを組み立てますので、必然的にプールを使う期間につきましては、一部狭くなると認識しています。児童センターがメインで使われる屋上広場に設置されてありますが、今お話がありましたように、保育園で使用することもあるという話を聞いてあります。","id":"exchange-011"},{"speaker":"田中委員","kind":"質問","question":"区立保育園は全体的に、１歳児だったり乳児だったり、小さい子のところには床暖房が設置されていく方針なのかという部分をお知らせいただければ。どうか尋ねました。","respondent":"小林施設整備課長","answer":"分かる範囲でのご回答になりますが、基本的には、昨年度完了しました南ゆたか保育園とかにつきましても、小さなお子さんが使う部屋については床暖房を設置していますので、今後その方針であると聞いております。","id":"exchange-012"},{"speaker":"須貝委員","kind":"質問","question":"今回、入札価格を出してきているわけですから、また値段の改定ということが起こり得る状況になってしまうのですかというのを質問したいのです。９月、１０月頃に、また急激に全体の１割・２割増しという状況になる可能性もあるという今回の入札価格なのか尋ねました。","respondent":"東野経理課長","answer":"ただ、今回の入札にどれだけ影響を及ぼすかといったところにつきましては、今後の動向につきまして注視をしていきたいと思います。都の動きといったところが、価格に影響がある場合も想定されますので、区としても十分その辺を認識した上で注視していきたいと考えています。","id":"exchange-013"},{"speaker":"須貝委員","kind":"質問","question":"上がったら上がったで、１割、２割、また価格が単品スライドで上がってしまうことになるのですか。どういうものなのですか、説明を求めました。","respondent":"東野経理課長","answer":"応札された会社のお考えがありますので、区として何かしら調べるとか、どういった形のものかというのを後から聴取することは考えてございません。","id":"exchange-014"},{"speaker":"須貝委員","kind":"意見","question":"極力建設業界の業者と話をして、どうすればこの値段で極力抑えられるかという努力も、私はしてほしいと思います。これは意見だけ出しますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"}]},{"id":"topic-02","title":"品川区西五反田三丁目付近再構築その３工事請負契約","agenda":"品川区西五反田三丁目付近再構築その３工事請負契約","exchanges":[{"speaker":"須貝委員","kind":"質問・要望","question":"品川区はいろいろなところで給排水設備、下水道排水施設をどんどん交換して、本当にありがたく思っております。できる限り、品川区はそういう力もあるのでありがたいと思いますが、進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"}]},{"id":"topic-03","title":"品川区東五反田一丁目付近再構築工事請負契約","agenda":"品川区東五反田一丁目付近再構築工事請負契約","exchanges":[{"speaker":"たけうち副委員長","kind":"質問","question":"５番は積算価格が予定価格を超過したということで、２・３・４番は配置予定技術者が配置できなくなったと。４番の日本ノーディッグテクノロジー株式会社というのは、ほかのところも考え方としては、足りなくなってしまったということか尋ねました。","respondent":"東野経理課長","answer":"入札公告時に監理技術者または主任技術者の配置を行うことという条件の下に、入札を行っているところです。主任技術者等の技術者を配置できる予定として、例えばほかの工事を受注されたとかということで、そのようにご理解いただければと思います。","id":"exchange-017"},{"speaker":"田中委員","kind":"質問・要望","question":"分かる範囲でいいのですが、東五反田一丁目の工事の範囲は、結構細々とした道だったのではないかと思うのですが、工事の際は安全性の確保というか、その部分がもし分かれば、お知らせいただきたいと思うのですけれども、いかがか尋ねました。","respondent":"東野経理課長","answer":"聞いている範囲ですが、例えば通行止め等の対策ですとか、場合によっては夜間工事の場合があると聞いてあります。近隣住民につきましては、お知らせ看板やビラなどを配布して、十分な周知を図っているというところまで聞いてあります。","id":"exchange-018"}]},{"id":"topic-04","title":"品川区総合実施計画の策定","agenda":"品川区総合実施計画の策定","exchanges":[{"speaker":"おくの委員","kind":"確認","question":"これに掲げられている各事業は、全部で１１５事業ということですけれども、まず、各常任委員会で審議あるいは報告されるものなのでしょうか。その点をまず確認しておきたいと思うのですけれども、よく分からない点もあったので、確認しておきたいと思います。","respondent":"佐藤（聡）計画担当課長","answer":"今回の実施計画につきましては、本総務委員会で報告するということになっておりまして、各委員会での報告、審議等は予定しておりません。","id":"exchange-019"},{"speaker":"おくの委員","kind":"質問","question":"１事業１事業はそれぞれ専門の、その点、いかがでしょうか。むしろ不可能ではないかと思うのですけれども、その点、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"おくの委員","kind":"質問","question":"これは大きな話だから、ここで聞いていいのかなというつもりで聞くのですが、この内容に関して少しだけよろしいでしょうか。あるいは、外国人観光客となると、羽田新ルートなども関係してくると思うのですが、それに対する区民の強い反対もあるという……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"おくの委員","kind":"質問","question":"１５０ページでは、地域特性を活かした計画的なまちづくりで、リニア中央新幹線や羽田空港アクセス線開業によるというものが出てくるわけです。そこが私は気になったので、伺ってみたいと思ったのですけれども、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"おくの委員","kind":"質問","question":"もう一つ、類似の質問でどうかなと言われるかもしれませんが、１５６ページ、武蔵小山駅周辺地区の整備促進というのがあります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"おくの委員","kind":"質問","question":"そういうものも考慮して、そういうことも考慮された上で、この実施計画の事業というのは考えられているのでしょうか。その点をお伺いしたいです。","respondent":"佐藤（聡）計画担当課長","answer":"実施計画自体が長期基本計画の実現に向けたロードマップのような形になりますので、２つの地区につきましては、このような記述になっているです。組合、準備組合等の動きに対して支援するような形で、区では進めていきたいと考えております。","id":"exchange-024"},{"speaker":"田中委員","kind":"質問・要望","question":"ほかのところも伺います。８０ページの区立児童相談所の開設・運営で、援助、この「施設を整備する」はハードではないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"田中委員","kind":"質問","question":"これが目標値で３か所、なぜ１か所しか増えないのかという部分を伺いたいのと、どういう計画に照らしてこの数なのかという部分を知りたいです。それは駄目か尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"田中委員","kind":"質問","question":"では、新しい障害児者福祉計画との整合性がどうなっているのかという部分、根本となっている計画と実施計画の整合性の部分を伺っています。具体的にどの数値からのマイナス４１％なのかも分からなくて、具体的になっていないですというところを聞きたかったのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"田中委員","kind":"確認","question":"まだよく分からないところが多々あるのですけれども、１個だけ確認させていただきたくて、今、個々の計画で策定中のものがあるではないですか。策定中の計画は、前年度というか、前の計画が反映されているという考え方でいいか尋ねました。","respondent":"佐藤（聡）計画担当課長","answer":"個別の計画と実施計画の関係ということかと思いますけれども、そのまま実施計画の中に反映していくとか、個別計画と実施計画について。","id":"exchange-028"},{"speaker":"渡部委員","kind":"質問・要望","question":"この先１年で品川区の状況がどうかというのを見ていって、第２次が出るというイメージでいいのか、どうなのかというところを教えていただきたい。出来上がった冊子版をどのように取り扱っていくのかというのを教えてほしいのと、要望は、説明を求めました。","respondent":"佐藤（聡）計画担当課長","answer":"１つ目ですけれども、実施計画の期間のお話ですが、前の実施計画は４次まで出ております。３年を計画期間としておりますので、基本的には３年後、第２次の実施計画を策定する予定です。","id":"exchange-029"},{"speaker":"渡部委員","kind":"質問","question":"お配りいただいて興味を持ってもらって、実は２００ページの冊子ができているわけだから、欲しい人は買えるような仕組みも取ってほしい。今回は３,０００部で、品川区は市民科という授業があるわけですから、考えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"田中委員","kind":"質問","question":"そことコロナの状況というのは重ならないではないですか。時期がずれてしまうというのを思うのですけれども、そこのスケジュール感について、もう一度伺いたいです。","respondent":"佐藤（聡）計画担当課長","answer":"実施計画を策定するという作業に入りましたので、あるいは令和３年からの計画ということで、実施計画を策定し始めたというところです。ちょうどそのときにコロナが発生したというところがありましたので、策定作業を一旦止めたです。","id":"exchange-031"},{"speaker":"田中委員","kind":"意見","question":"前回の実施計画が２０１８年までの計画だったので、２０１９年の当初から計画が。〔「長計が１年遅かったのだ」と呼ぶ者あり〕との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-032"},{"speaker":"田中委員","kind":"質問","question":"コロナが原因の社会情勢の変化という話だったと思うのですけれども、今説明された社会情勢の変化とは、どの部分を指しているのか。２０１８年に実施計画が終わるので、２０１７年には策定作業が始まるのかなと思ったのですけれども、２０１９年にずれ込んだという考え方か尋ねました。","respondent":"佐藤（聡）計画担当課長","answer":"長期基本計画の策定のときのお話になろうかと思います。新たな課題に対応していくために長期基本計画が必要ではないかということで、庁内での検討を十分に取るとか、そういったところのために１年間。","id":"exchange-033"}]},{"id":"topic-05","title":"ふるさと納税（寄附金）に係る体験型返礼品の追加等","agenda":"ふるさと納税（寄附金）に係る体験型返礼品の追加等","exchanges":[{"speaker":"田中委員","kind":"質問","question":"いかがですかという声が上がってくるのか、金額も決定していくのかという部分を伺いたいのですけれども、いかがか尋ねました。","respondent":"提坂税務課長","answer":"品川区の場合、そういうものがございませんので、まず品川区の魅力を発信するものということが大前提です。体験型に取り組んでいる団体を紹介していただいて、区内の魅力発信、返礼品ということで選定しています。","id":"exchange-034"},{"speaker":"田中委員","kind":"質問・要望","question":"区からの打診、担当課からの打診と共に、事業者からのアピールもあるということでした。教えていただきたいのですけれども、返礼品にならなかったものでどういったものがあったのか、お知らせください。","respondent":"提坂税務課長","answer":"断念というか、お断りしたとか、そういった類いのものが何件かあったかなと思います。","id":"exchange-035"}]},{"id":"topic-06","title":"ジュネーヴ市３０周年記念公式訪問団受入れの中止","agenda":"ジュネーヴ市３０周年記念公式訪問団受入れの中止","exchanges":[{"speaker":"田中委員","kind":"意見","question":"オンライン等を利用した交流について協議中ということで、昨年もされたというご説明があったと思うのですけれども、昨年どのような対象というか、どういう方がオンラインで交流したのか、子どもたちの交流があったのかという部分を知りたくて、お知らせいただけますかとの意見を述べました。","respondent":"古巻総務課長","answer":"品川区には姉妹都市・友好都市が３つございまして、アメリカのポートランド市、それからニュージーランドのオークランド市があります。今年度もそれプラス、また考えたいと思いますけれども、少なくとも電子メール等での交流はやっていきたいと考えているところです。","id":"exchange-036"},{"speaker":"たけうち副委員長","kind":"質問","question":"１年延期して、それで結果的にまた１年ということで、今回はここに書いてあるとおり、延期ではなく中止ということか尋ねました。","respondent":"古巻総務課長","answer":"５年ごとということで、２回延期をすると、周年事業としては中止をする。その辺りは柔軟にやっていければと思いますが、周年事業としては中止という判断を今回はさせていただいたということです。","id":"exchange-037"},{"speaker":"たけうち副委員長","kind":"質問","question":"そうすると、３０周年はこういう形で中止になって、次は３５周年ですか。まだ決まっていないか尋ねました。","respondent":"古巻総務課長","answer":"順番からいくと、３５周年はこちらから伺うという形なのですが、その辺りの細かいところは、またこれからの協議の中身によってということになると思います。","id":"exchange-038"},{"speaker":"たけうち副委員長","kind":"質問","question":"これは２０年ぶりだったらしいのですが、当時幹事長だったものですから、非常に残念に思っております。今回の３０周年のときに向こうに行かれて、大々的ではなくても、そのようにできるような連携は取られていらっしゃいますか。","respondent":"古巻総務課長","answer":"区として何か連携してということはしておりませんが、今後また小さな形ででも、交流が途切れることのないように様々進めていきたいと考えています。","id":"exchange-039"},{"speaker":"たけうち副委員長","kind":"質問・要望","question":"コロナの問題があるので軽々には言えないですけれども、またさらに交流が深まってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"}]},{"id":"topic-07","title":"その他","agenda":"その他","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"お聞きしたいのですが、支援といいますか、そういうものはあるのですか。それとも、東京都止まりなのか尋ねました。","respondent":"古巻総務課長","answer":"区としての動きということでいうと、基本的には東京都が中心になって、いろいろな手配でありますとか、いろいろなことをやっているという形です。","id":"exchange-041"},{"speaker":"田中委員","kind":"確認","question":"今、平和・国際担当ということでしたけれども、区民の方にお知らせするときには、そういうご相談があった場合には総合窓口の番号を教えれば、つなげていただけるのでしょうかという確認を。","respondent":"古巻総務課長","answer":"そのように調整がつくようにはしています。","id":"exchange-042"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/816435?Template=document&Id=2228#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":34603,"voices":181}},{"id":"r04-20220419-14","meetingId":"r04-cm04","date":"2022年4月19日","dateIso":"2022-04-19","committee":"行財政改革特別委員会","time":"午後 １時００分～午後 ２時４３分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を29件整理しています。","topics":[{"id":"topic-01","title":"新庁舎に関すること","agenda":"新庁舎に関すること","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"もう後付けは絶対にできないので、その辺についてご検討とか何かはされたのでしょうか、教えてください。そして、そういうことも私は必要ではないかと思うのですが、もし何かご見解がありましたら説明を求めました。","respondent":"山下新庁舎整備課長","answer":"いわゆる報道等にある侵攻が始まっていない状況でのアンケートの実施でございましたので、そういったところに取り上げてはもちろんいないところです。","id":"exchange-001"},{"speaker":"須貝委員","kind":"質問","question":"今なぜこの場で申し上げなくてはいけないのかと私自身もびっくりしているくらいなのですが、やはり１００年この建物を守っていく。ですから、そういうことも設計の段階で考えるべきではないかという意見だけは、ここで私は言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"あくつ委員","kind":"質問・要望","question":"やはりちらほらと質問が出たり、多目的利用とかどうなのですかというような質問を投げかけられたりもしましたが、答えていないのです。区のお考えは、その２点、教えてほしいと求めました。","respondent":"山下新庁舎整備課長","answer":"素案の検討の中で項目として含めておりまして、資料のほうに明示をする形でご説明をしてまいりたいと考えていますので、次回の場が一番。回収率としては大体６割は超えるところで来ているように聞いているのですけれども、皆様の意向の状況を確認してまいりたいと考えています。","id":"exchange-003"},{"speaker":"あくつ委員","kind":"確認","question":"では、後段の部分はこれからということで、どういう結果になるのかを見守りたいと思います。なぜこのような質問をしたかというと、議会に対してこういう発言があってもいいのではないでしょうかというご発言があったものですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"議会改革推進会議のほうは座長もやったので、そこはそこであれなのですが、全体的な考え方を教えていただきたい。だからそこら辺の今のお考えをお聞かせ願いたい。","respondent":"山下新庁舎整備課長","answer":"いわゆる物資、資材等について一定高騰といいますか、値段がかなり上がってきているというところは委員ご指摘のとおりと存じます。実際にその資材等が１.５倍というようなことで事業費が膨れ上がるといったような場合につきまして、対応としては考えてまいりたいと考えています。","id":"exchange-005"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"いろいろな情報を取っていただいて、行政側もいろいろな方ともお会いいただいて、そういう情報を多く取ってほしい。そういうことも含めて、ぜひそれは調査をかけるなり何なりして、そういうことをやっていただきたいというのは要望だけにしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"大倉委員","kind":"意見","question":"４ページで、駐輪場とかバイクの駐車場みたいなものが減ると困るなと思ったので、ここは聞いておきたいと思ったのです。逆に言うと駐輪を駅ではなくて、余計混んできてしまうのではないかと思ったので、その辺が少し心配で聞かせてほしいと求めました。","respondent":"大友新庁舎建設担当課長","answer":"こちらのほうの広町全体を考えた時には、ＪＲの開発のほうで５００m2ほど今よりもかなり台数が停められる駐車場を整備する計画で考えております。そちらの駐輪場の整備の台数を移行する考えがありまして、広町の大井町駅のほうに整備するようなイメージを考えている次第です。","id":"exchange-007"},{"speaker":"大倉委員","kind":"質問・要望","question":"駐輪場は料金がかかるところと、そうすると、やはり駐輪場はお金のかからないほうに置こうかなと思う人たちも多く増えてきてしまうかなと思うのです。停めやすいと思えば余計に区役所のほうを利用する方も増えてくるのかなという思いがありますので、その辺は考えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"のだて副委員長","kind":"質問","question":"この保健センターは４か所になるということなのかどうか、その辺りを伺いたいと思います。やはり自治体の業務は多岐にわたる部分もあって、なかなか民間ではできないという声も出ておりますけれども、区の考えを伺いたいと思います。","respondent":"山下新庁舎整備課長","answer":"障害者就労支援のお店についても区民協働・交流スペースにというところですけれども、区民協働・交流スペース、今後研究・検討を進めていくです。","id":"exchange-009"}]},{"id":"topic-02","title":"順序を入れ替えまして、はじめに、(2)品川区ＤＸ推進基本方針の策定","agenda":"順序を入れ替えまして、はじめに、(2)品川区ＤＸ推進基本方針の策定","exchanges":[{"speaker":"塚本委員","kind":"質問","question":"オンライン申請の件はよく分かりました。以前の質問でも同じような議論をさせていただいたと思うのですが、一応、どのように整理されているかというのを最後にお聞きしたいと思います。","respondent":"宮澤情報推進課長","answer":"サーバー室にサーバーを設置して自区で管理をするとうことは、そのサーバー室の保守運営を含めて対応していくということで行っているところ、ただ。","id":"exchange-010"},{"speaker":"あくつ委員","kind":"提案","question":"それは様々予算特別委員会等で、この発信のあり方などでも議会からもいろいろ指摘がありましたけれども、本当にそこのところは大丈夫なのでしょうか。そういうところをしっかりと誰が見ていくのか、ＰＤＣＡしてくのかというところを確認させてほしいと求めました。","respondent":"宮澤情報推進課長","answer":"２点目のところです。そういった視点を踏まえて、意識改革を含めて取り組んでいく必要があるなと感じて、今後進めていく予定です。","id":"exchange-011"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ＤＸをやるのであれば、その発信も区民に分かりやすいように、併せてしっかりやっていただきたい。一つの例ですけれども危惧をしたので、挙げさせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"芹澤委員","kind":"質問・要望","question":"ペーパーレスに関しても、上司が紙の資料を求めないというような結構とがった話までしないと、このＤＸというのは進まないと思うのです。２年でできることではないと思うのですが、どういった計画をお持ちなのか、改めて説明を求めました。","respondent":"宮澤情報推進課長、河西情報戦略担当課長","answer":"重点取組項目に限らず分野別の取組項目についても取り扱っていく、全体のデジタル・トランスフォーメーションについて進めていく予定です。もし現場からの反発等があったとしても、区の方針というのは大きな方針として決めておりますの… まさにそのとおりでして、品川区ＤＸ推進基本方針は、どちらかというと国の方針に従ってトップダウンでやるものになっています。","id":"exchange-013"},{"speaker":"芹澤委員","kind":"質問・要望","question":"すごく厳しい見方をすれば、東京都とかのデジタル戦略を見ると、これはできないのではないかなというようなものも結構入っているように思うのです。もしくは計画に入れなくても、これから方向性として考える時に、ぜひ前向きに取り組んでいただきたいという要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"渡部委員","kind":"質問・要望","question":"ですから、区の職員の方々というのは否応なしにこれからそちらに向いて進んでいかなければならないわけで、そこはしっかりやっていただきたい。成人として１８歳以上の区民の方々に１００％持っていただけるような努力というものは、その辺のところだけ聞きたいと思いまして質問しました。","respondent":"宮澤情報推進課長","answer":"取組の状況等につきましては、先ほどの全体のＤＸ推進戦略会議のほうでも進捗具合を含めて進めているところです。取得に対する支援という形を現状も行ってありますけれども、全庁的な取組、テーマ別の取組等で必要に応じて連携しながら進めていくという形です。","id":"exchange-015"},{"speaker":"渡部委員","kind":"確認","question":"ただ、これは素人考えなのでわからないですが、やはりマイナンバーカードを持っている人と持っていない人の差はつくじゃないですか。きっと本人確認をしなければいけなかったりもするわけだから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"西村委員","kind":"質問・要望","question":"少し細かいのですが、１点だけお伺いさせてください。どこまでこういった細かいところまで議論されるのかというのがまだイメージできておりませんが、お聞かせほしいと求めました。","respondent":"宮澤情報推進課長","answer":"基本的な進め方、組織づくり、意識改革というのを進めていきます。ただ、取組として全体的な区の目標を立てて方針を進めていきますので、その中で取組を進めていくです。","id":"exchange-017"},{"speaker":"西村委員","kind":"質問・要望","question":"どういったところが課題なのかという区民の方々の声を抽出することにぜひとも力を入れていただきたいと思っておりまして、実際に今。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"石田（秀）委員","kind":"質問","question":"１点だけ伺いたいのですが、これはどこが所管して、そちらのほうは誰が中心になってやっていくのか。それを説明を求めました。","respondent":"宮澤情報推進課長","answer":"例えばモニターを活用した働き方であったり、モバイル性のある端末でというところで、そういった配備は情報推進課を含めて進めてまいります。今回、基本方針の中にも盛り込ませていただきましたが、新庁舎のほうに成果をつなげていけるように進めていきたいと考えています。","id":"exchange-019"},{"speaker":"石田（秀）委員","kind":"質問","question":"要は令和８年になるということだろうと思っているのだろうけれども、それがもうここで言う１００％も大分あるわけだから、極端なことを言えばもう移転する時には全員そういう形に変わっているという理解でいいのかだけ説明を求めました。","respondent":"宮澤情報推進課長","answer":"取組は令和７年までＤＸを進めてまいります。その認識で合っているところです。","id":"exchange-020"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"確認させていただきたいのですが、Ａ３判資料の２ページ目で重点取組項目のところに、この手続きというのが業務とは違うということですか。そしてまた、この分野別取組項目のところに「データ利活用の推進」というのが書かれておりますけれども、これはどういうことか、伺いたいと思います。","respondent":"宮澤情報推進課長","answer":"２つ目のデータの利活用です。行政の施策にデータというのを活かしていくというのが１点と、あともう一つは、そういった形でデータの利活用につきましても推進していくです。","id":"exchange-021"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"例えば住民票を取る、その区民が１回行うのが１手続ということになるのか、そこを確認させてほしいと求めました。こうしたデータを活用していくということの前提に、個人情報保護を強化していくことが必要だと思うのですけれども、その点を伺いたいと思います。","respondent":"宮澤情報推進課長","answer":"２点目のデータ利活用の部分ですけれども、そういった情報、いわゆるデータという形のものを活用するものです。個人情報の取扱いについては、引き続き研修等も踏まえながら適正に管理・運用していくところです。","id":"exchange-022"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"工程表の８ページにおきまして、これがどういうことなのか、伺います。区が独自でやっている事業とか、そうした部分は狭めないようにしていただきたいと思うのですが、いかがか尋ねました。","respondent":"宮澤情報推進課長","answer":"１点目の、デジタル化を進める際の効率化等々を図ると、さらなる区民サービスの向上のほうに振り向けていくという考えです。それは新たなシステムで連携するような形を取るのかどうか、今、詳細な分析をしています。","id":"exchange-023"}]},{"id":"topic-03","title":"東大井三丁目における都有地（都営元芝アパート跡地）を活用した特別養護老人ホーム等の整備","agenda":"東大井三丁目における都有地（都営元芝アパート跡地）を活用した特別養護老人ホーム等の整備","exchanges":[{"speaker":"あくつ委員","kind":"質問・要望","question":"住民の意向として、地域の意向として伝えていただきたいという要望を受けているのですが、この点について教えてほしいと求めました。私もつい最近、約３,０００m2ということで相当広い跡地ということになっているのですけれども、この２点をお伺いしたいと思います。","respondent":"佐藤企画調整課長","answer":"２点目の多世代交流施設の必要性に関しましては、一定必要性はあるだろうということで認識を示していると聞いております。そこまでは今手元にないところですが、都のインフラ整備事業で、地元の自治体の要望を聞きながら都が事業を進めているという認識です。","id":"exchange-024"},{"speaker":"あくつ委員","kind":"質問・要望","question":"先様のある話なので、何で売らないのかという理由までは、先方からはそこは分からないということだったと思うのです。それとも今まである程度交渉をしてこられたと思うのですけれども、企画調整課からされるのか、その点について確認させてほしいと求めました。","respondent":"佐藤企画調整課長","answer":"企画調整課といたしましては、その先は所管のほうが豊富なノウハウがありますので、所管のほうで対応するというような切り分けをしております。地域交流施設等の設置等々につきましては、所管の福祉計画課のほうで申入れをしていくというところです。","id":"exchange-025"},{"speaker":"石田（秀）委員","kind":"提案","question":"私は厚生委員だから、昨日まさにこれをやっていたのだけれども、少し微妙な今の発言なので、確認だけさせてください。それからショートステイを１割併設してくださいねと、自由に提案してくださいねということですよねとの意見を述べました。","respondent":"佐藤企画調整課長","answer":"この事業ですが、この事業につきましては、都有地活用による地域の福祉インフラ整備事業実施要綱というもので東京都が定めて行うものです。聞かないにかかわらず、実現する面もあると思いますし、その辺は柔軟にバランスを取りながらやっていくと今の時点では考えています。","id":"exchange-026"},{"speaker":"あくつ委員","kind":"質問・要望","question":"確認していただきましたけれども、そういう地域要望というのは都のほうには伝わっていると思いますし、これからもさらに強く進めていくと。私も質疑についてはつまびらかに確認をしていますので、その上での発言だということはご理解をほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"須貝委員","kind":"質問","question":"東京都のほうで公募をするという話ですが、これは民間事業者だけしか入れないのですか。例えば品川区がここに応募するということはないのか尋ねました。","respondent":"佐藤企画調整課長","answer":"よりよい事業者が定期借地権で長期間の事業を運営するというものなので、公設というのは前提にしておりません。公設というのは、品川区が手を挙げて、事業を運営するというような前提になっていないということです。","id":"exchange-028"},{"speaker":"須貝委員","kind":"意見","question":"私は国民、都民、区民のことを考えたらやはり平等に公募すべきだと思うのですが、やはりそこはそういう約束事で駄目ということなのですね。一応公募というふうになっているので、差支えないのではないかと単純に思ったのですが、もう一度説明を求めました。","respondent":"佐藤企画調整課長","answer":"今、民設民営というところであれば都の補助金もありますので、基本は民間の力も借りてというところもあるのだと思います。そういった考え方になっているのだと考えております。","id":"exchange-029"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/474872?Template=document&Id=6126#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":33820,"voices":96}},{"id":"r04-20220420-19","meetingId":"r04-cm04","date":"2022年4月20日","dateIso":"2022-04-20","committee":"災害・環境対策特別委員会","time":"午後 １時００分～午後 ３時１８分","status":"正式会議録","sourceType":"formal","overview":"災害・環境対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を13件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査のまとめ","agenda":"特定事件調査のまとめ","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"意見","question":"備蓄について」というところの（６）ですが、「防災公園の設置に努められたい」という文言にしたほうが分かりやすいのではないかなというふうに思ったのですが、ご検討いただけたらと思いますとの意見を述べました。","respondent":"安藤委員長","answer":"誤解のあるような表現を避けたいというご意見だと思いますので、軽微な修正かと思うのですけれども、正式には正副で後日調整して、ご主旨を活かせるように修正したいと思います。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"（１）の区民のごみの分別やリサイクルの意識の向上についてのその後に「具体的な行動を起こしていただけるような啓発」と書かれているのですが、こういうところで書かれるのは適切かなという思いをしているのですけれども、ご検討いただけたらと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-002"}]},{"id":"topic-02","title":"エコルとごし開設およびオープニング式典・イベントの開催","agenda":"エコルとごし開設およびオープニング式典・イベントの開催","exchanges":[{"speaker":"湯澤委員","kind":"質問・要望","question":"は５月１日を過ぎても、ゴールデンウイークとか、その辺の駐輪場の対策というのがどうなっているのかというのが１個。ごみ評論家というのですか、大体今どのぐらい応募があったのかということを、まず分かれば教えていただきたい。","respondent":"河内環境課長","answer":"３７台分置くスペースがございまして、近隣の方にご迷惑のないような運営に努めてまいりたいというふうに考えているところです。それから２点目のトークイベントの応募状況ですが、８０名に対しまして現在１０４名ということで、適切に運営してまいりたいという考えです。","id":"exchange-003"},{"speaker":"湯澤委員","kind":"意見","question":"８０人に対して定員をオーバーするぐらいの方がいらっしゃっているということで、今後またやる機会があるときには、よろしくお願いしたいと思います。何かあれば、お願いしたいとの意見を述べました。","respondent":"河内環境課長","answer":"駐輪場対策につきましては、指定管理者とともに適切に対応していきたいというふうに考えているところです。記念講演も予定しておりまして、いろいろ講座を通じまして、環境の啓発を進めてまいりたいというふうに考えているところです。","id":"exchange-004"},{"speaker":"新妻委員","kind":"質問・要望","question":"２点、お伺いいたします。それと、フードドライブについてお伺いいたします。","respondent":"河内環境課長","answer":"そういったところはなるべく対応できるように、引き続き心がけてまいりたいというふうに考えているところです。フードドライブをやっていることを皆さんにまずご認識いただけるような工夫をしながら進めてまいりたいというふうに考えているところです。","id":"exchange-005"},{"speaker":"新妻委員","kind":"質問・要望","question":"要望します。フードドライブにつきましては、皆様が行きやすい場所に設置されているですので、引き続きどうぞ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"渡辺委員","kind":"質問","question":"やはり仕掛けることは、イベントを通じたりして仕掛けなければいけないと思うのですが、その辺の今後のオープニング以降の展開を教えてください。この２点説明を求めました。","respondent":"河内環境課長","answer":"５月につきましては、その後、夏休みの講座なども力を入れてまいりたいというところで計画しています。そういったところを合わせながら、隙間なく環境の啓発が行えますように、工夫を重ねてまいりたいというところで計画をしています。","id":"exchange-007"},{"speaker":"渡辺委員","kind":"質問","question":"最寄り駅から、お店の人に「エコルとごしどこですか」と聞いたときに、この応対がすごいポイントだと思うのです。その辺のところをどう取り組まれて、あるいは今後どのような設定をされているか説明を求めました。","respondent":"河内環境課長","answer":"地域との連携具合です。団体誘致など、きめ細かく地元の方を優先的に、まずご案内差し上げながら盛り上げてまいりたいというふうに考えているところです。","id":"exchange-008"},{"speaker":"渡辺委員","kind":"質問","question":"これは職員だけではなくて地域の方のサポート体制というのですかね。２年目も３年目も次々企画が打ち出されるような、そんな形であってほしいと思うのですが、抱負だけ説明を求めました。","respondent":"河内環境課長","answer":"こういった認証だとかポイント制度とか、そういった工夫を重ねながらやりたいということで、指定管理者とも今話合いを続けているところです。そのような形で進めたいと考えています。","id":"exchange-009"},{"speaker":"松澤委員","kind":"質問","question":"１個だけお聞きしたいのが、裏にＱＲコードがあるのですけれども、これは今現在人数が７０人。友達を大体どれぐらいつくるかとか、区としての目標値があれば説明を求めました。","respondent":"河内環境課長","answer":"全体的には年間で３万人と言っていますけれども、そういった目標値をだんだん年度で引き上げていきたいというふうに考えておりますので、そのような考え方の中で進めてまいりたいというふうに考えているところです。","id":"exchange-010"},{"speaker":"松澤委員","kind":"意見","question":"だから、まず７０人がどれだけ広がったとか、環境課の環境をやってくのだというその心意気をしっかり数字に表していただければと思っていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"}]},{"id":"topic-03","title":"令和４年度品川区・第二消防方面合同水防訓練および自主避難施設開設訓練の実施","agenda":"令和４年度品川区・第二消防方面合同水防訓練および自主避難施設開設訓練の実施","exchanges":[{"speaker":"こんの委員","kind":"質問","question":"実際災害時に２０名もつくほど職員がいらっしゃるのでしょうかというそこら辺のところ。訓練のためだけの人数だったり体制ではなく、その辺のこの人数の配置だとか訓練の内容だとか、もう少し詳しく教えていただきますか尋ねました。","respondent":"五十嵐災害対策担当課長","answer":"１校につき２０名、区の職員が開設訓練のほうを実施します。昨年に自主避難施設開設訓練を初めて実施したところですけれども、訓練を実施した検証をやりまして、その際に。","id":"exchange-012"},{"speaker":"こんの委員","kind":"確認","question":"自主避難施設ですから、あとの１０名は視察も兼ねてという形で、１５校が開設するに当たっての視察も兼ねてという理解でよろしいでしょうか。いわゆる学校、そこら辺の連携の取り方とかそういったこともするのですよねという確認をさせてください。","respondent":"五十嵐災害対策担当課長","answer":"委員ご指摘のとおり、そういった連携訓練も実施していきますし、どういったものが各学校のどこに配置されているかというのも確認します。今後その辺については実施していきたいというふうに考えておりますので、よろしくお願いします。","id":"exchange-013"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/781505?Template=document&Id=6612#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=19&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":16209,"voices":81}},{"id":"r04-20220428-10","meetingId":"r04-cm04","date":"2022年4月28日","dateIso":"2022-04-28","committee":"議会運営委員会","time":"午後 １時００分～午後 １時１０分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を1件整理しています。","topics":[{"id":"topic-01","title":"役職改選","agenda":"役職改選","exchanges":[{"speaker":"高橋（伸）委員","kind":"意見","question":"議論、そして、ご意見等々をいただいているところです。それによりまして、まだ議論途中の段階なので、取りあえず今そういった、私の会派の中では、報告ということで発言をさせていただきましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/982514?Template=document&Id=5458#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":3432,"voices":21}},{"id":"r04-20220513-10","meetingId":"r04-cm05","date":"2022年5月13日","dateIso":"2022-05-13","committee":"議会運営委員会","time":"午後 １時００分～午後 １時３５分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/982514?Template=document&Id=5460#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":10730,"voices":61}},{"id":"r04-20220516-6","meetingId":"r04-cm05","date":"2022年5月16日","dateIso":"2022-05-16","committee":"区民委員会","time":"午後 １時００分～午後 ２時３４分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を29件整理しています。","topics":[{"id":"topic-01","title":"令和４年度中小企業支援策","agenda":"令和４年度中小企業支援策","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"区が３年間無利子だったり、こちらも厳しい判断が求められるし、この点は指摘をさせてほしいと求めました。質問ですけれども、それに見合った支援策を講じていただきたいと思うのですけれども、いかがか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"１０％ぐらい、前年度比ですけれども、かなり増えてきていると認識しています。どういう部分の支援ができるかというところは、非常に私どもも考えているところですが、それを実行していきたいというふうに考えているところです。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"それも含めて仕事ですから、どうしても様々な手続をするのが、なかなか大変だということをよく伺うのです。手続の簡素化や、ぜひ強化できる部分がないのか点検しつつ進めてほしいと求めましたが、手続の支援についてご答弁ほしいと求めました。","respondent":"遠藤商業・ものづくり課長","answer":"お出でいただくという形で、簡素化できる部分については、この間ずっとやってきたというふうに考えているところです。ご相談いただければ、今どこが止まっている状態だとかというところで、専門家を派遣するなりして対応させていただいているところです。","id":"exchange-002"},{"speaker":"中塚委員","kind":"意見","question":"私も区議会議員になる前、飲食店にいたので分かるのです。片づけしてから１日の会計を閉じて、行政が、個人の業態や業種に沿った支援を重ねてよろしくお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"},{"speaker":"横山委員","kind":"確認","question":"何点かお伺いしてまいります。パンフレットのほうの4)で、使われた実感といいますか、どういった反応が入ってきているのかというところをまず確認させてください。","respondent":"遠藤商業・ものづくり課長","answer":"もともとは、いわゆる空気清浄機だとか、アクリル板だとかが多かったのですけれども、２年、３年とやらせていただく中で、そういうものに移ってきた。","id":"exchange-004"},{"speaker":"横山委員","kind":"確認","question":"確認していただいてありがとうございました。前回使っていただいて増えなかった企業に対しては、今後はいいのかななどというふうに私は考えているのですけれども、区のお考えを説明を求めました。","respondent":"遠藤商業・ものづくり課長","answer":"今後は、実際に自分で運営されているとか、あとは、今言った広告などで、どういうタイミングがいいかというところであろうかと思います。今申しましたセミナーとかでいろいろな支援施設がありますので、新たに新型コロナウイルス感染症対応特別助成から得た利用者の学びなども。","id":"exchange-005"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"１点だけ確認します。先ほど、この支援策の周知の仕方について、もう少し詳しく教えてほしいと求めました。","respondent":"遠藤商業・ものづくり課長","answer":"各支援策の周知方法ですけれども、こちらは区内にある全ての事業所に、シルバー人材センターを活用いたしまして配布させていただいているところです。そのほかの場面でも、いろいろな形で区民の方にこちらの支援策が届くよう、工夫して周知をしていきたいと考えております。","id":"exchange-006"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"こういうところだけでも、飲食店とか小さいお店に関しては、個々にまた歩いていただきたいなというふうにも思っています。声がけをしていただきながら、さらなる徹底した周知というところでの取組をちょっとお願いしたいのですが、いかがか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"先ほどの「産業ニュース」のところで、あえてチラシを１枚別に刷りまして、そういうものを挟み込んで配らせていただいているようなところがあります。今後もいろいろな形で使いながら、引き続き周知の方法につきましては、いろいろと工夫していきたいと考えております。","id":"exchange-007"}]},{"id":"topic-02","title":"エシカル消費イベントの開催","agenda":"エシカル消費イベントの開催","exchanges":[{"speaker":"西村委員","kind":"質問・要望","question":"他区ですと、かなりこういったイベントが、ＳＤＧｓに取組を盛り込んでやっていらっしゃるなという印象がとてもありました。商店の力を発揮できるような新たな取組もぜひご検討いただきたいなと思っていまして、何かご見解があれば、説明を求めました。","respondent":"遠藤商業・ものづくり課長","answer":"あるいは、徐々に大きくしまして、エシカル消費の普及という形で実施させていただければなと今のところ考えているところです。は今年度こちらでやってみまして、来年どうしようかという検討を進めるようと考えているところです。","id":"exchange-008"},{"speaker":"西村委員","kind":"質問","question":"例えば、今、巷でというか、地域でいろいろと評判になっているのが、ローソンで始まっている量り売りなども、消費という意味ではすごく面白いなと。利用している８割が女性ということで、もともと日本にあるものですから、期待をしております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"中塚委員","kind":"意見","question":"まず廃棄物となる物をどうしていくのかとか、生産地もそうだし、どこまで広がっていけるのかということも１つ大事な視点かなと思うのです。始まったばかりでなんですけれども、今後の展開か何か、展望や期待も込めてご説明いただけたらと思いますとの意見を述べました。","respondent":"遠藤商業・ものづくり課長","answer":"よく言うコーヒー１つ買うのでも、それがどういうふうな結びつきがあるのだとか、これは全ての消費物に値するかと考えています。今後、多分つながらないところはないぐらいの気持ちでおりますので、こちらのほうも含めまして啓発に努めていきたいというふうに考えております。","id":"exchange-010"},{"speaker":"高橋（伸）委員","kind":"質問","question":"それで、壊れたおもちゃでも、手軽に直せるものと、やっぱりちょっと手間がかかるようなものがあるではないですか。その２時間の枠の中でやるわけだから、その辺のところはどういうふうになっているのか説明を求めました。","respondent":"遠藤商業・ものづくり課長","answer":"一度センターでお預かりするのですけれども、やはり症状によって、すぐ直せないという部分もあるかと思います。いわゆる入院をしてもらいまして、こちらでお預かりして、できた段階でご案内して、こういうふうになりましたということで対応しています。","id":"exchange-011"},{"speaker":"高橋（伸）委員","kind":"質問","question":"もう１つ、ボランティア医師の方が直すということで、予算額で、ボランティアの謝礼として５万円計上されていますけれども、これは何名ぐらいのボランティアの方が具体的にいらっしゃるのか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"登録いただいているボランティアの方は、今、８名おります。当日恐らく６人か７人ぐらいが参加いただけるというふうに、今のところ調整しています。","id":"exchange-012"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"ご説明ありがとうございました。今回のこのエシカル消費イベントでの環境課の関わりというのは何かあるのか教えていただきたいのと、何か掲示がされていて、お知らせください。","respondent":"遠藤商業・ものづくり課長","answer":"それからもう１つは、こちらは、私どものほうでパネル設置をさせていただきたいと考えています。そういうもので、もう一歩踏み込んだ周知、普及啓発を進められるかと考えているところです。","id":"exchange-013"}]},{"id":"topic-03","title":"品川区立荏原平塚総合区民会館指定管理者候補者の公募","agenda":"品川区立荏原平塚総合区民会館指定管理者候補者の公募","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"そういう下で公募という原則を、区としてはどう考えているのかご説明いただきたいのが１つです。もう１つは、福祉系の指定管理者公募については外部委員の採用という話を伺っているのですけれども、その点もご説明ほしいと求めました。","respondent":"篠田文化観光課長","answer":"区と連携した文化事業を進める取組等ありますので、そういったものを踏まえた上で、今後の指定管理者を選んでいくということになります。その辺も踏まえた上で、今、検討しています。","id":"exchange-014"},{"speaker":"中塚委員","kind":"質問・要望","question":"外部の視点も加えるとしたその理由、期待するものということでもいいのですけれども、ご説明ほしいと求めました。","respondent":"篠田文化観光課長","answer":"検討中ではあるのですけれども、１つは、そういった施設管理に特化した詳しい方の視点も必要であろうということ。当然、様々な事業を実施していくですので、そういった部分でもプロポーザルできちんと反映ができるのではないかというふうに考えているところです。","id":"exchange-015"},{"speaker":"くにば委員","kind":"意見","question":"こちらが令和３年度、共に収支がどのように改善されたのか、稼働率、稼働状況が現在どのようになっているか。はこの２点を説明を求めました。","respondent":"篠田文化観光課長","answer":"当初、指定管理者に渡していた部分も、かなり返還が見込まれるような状況です。","id":"exchange-016"},{"speaker":"くにば委員","kind":"質問","question":"利用率、収入が大幅に減少している、この点１点のみが令和２年度総括シートの中では課題として挙げられております。今の第２期までの運営に、令和３年度において、どのような点を挙げられるのか尋ねました。","respondent":"篠田文化観光課長","answer":"令和３年度のスクエア荏原の運営につきましては、まずはそこに戻していこうという形で、現場の人間も一生懸命取り組んできているところです。","id":"exchange-017"},{"speaker":"くにば委員","kind":"提案","question":"きゅりあんに関しても、今、動画配信の設備をさらによりよく整えていく改修を進めているというふうに伺いました。次の第３期の指定管理者に創意工夫をどのように求めていくのか、その２点、説明を求めました。","respondent":"篠田文化観光課長","answer":"これから、予算化はまだ今年度はされていないのですけれども、そういった機材をどこまで施設として用意していくかということ。それから、環境として新たに整備するものが必要なのかどうかというのは見極めていきたいというふうに考えているところではあります。","id":"exchange-018"},{"speaker":"くにば委員","kind":"質問・要望","question":"今後、この事業運営に関してプラスアルファの能力を、ぜひとも第３期の指定管理者の選定においては求めていっていただきたいなというふうに思います。まだまだ長引く可能性もありますし、ぜひともその創意工夫の部分を、その視点を持って選定してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"}]},{"id":"topic-04","title":"品川歴史館の大規模改修に伴う休館","agenda":"品川歴史館の大規模改修に伴う休館","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"あれはやっぱり大森貝塚は品川区ですから、私、小さい頃から貝塚を見ていましたけれども。展示内容のリニューアル、貝塚がどうなるのか伺いたいのですけれども、いかがか尋ねました。","respondent":"篠田文化観光課長","answer":"それから、通常は茶室として使っていたりするところなのですけれども、こちらは基本的には大きな手を入れる予定はございません。これをまたさらに分かりやすい展示に変えていこうということで、現在、検討しています。","id":"exchange-020"},{"speaker":"中塚委員","kind":"質問・要望","question":"１点だけ確認で、この先もずっと残していただきたいと思うので、その点だけ確認させてください。","respondent":"篠田文化観光課長","answer":"非常に古い施設でございまして、実は土台からかなり傷んできているということがあって、まず土台をきちんと造り直さないといけない。１回、やはり価値を考えれば、これをずっと後世まで継承していくというような対応をこれからとっていきたいというふうに考えているところです。","id":"exchange-021"},{"speaker":"藤原委員","kind":"質問","question":"５番の事務室移転等について伺いたいのですけれども、まず初めに、今いる事務室の方々の人数です。区から何人、事務員が何人、あと学芸員が何人、具体的に説明を求めました。","respondent":"篠田文化観光課長","answer":"それから、区の常勤の職員としましては、副館長と、それから事務員が２名という形ですので、合計で３名の職員がおります。それから、常勤の学芸員が１名いまして、それから会計年度の学芸員が３名いるという状況です。","id":"exchange-022"},{"speaker":"藤原委員","kind":"質問","question":"人数的には、多くもないけれども少なくもないと思うのですけれども、まず、特に学芸員の方たちの雇用は、約２年間閉じる中で守られるのかということが質問と、それと、区内各地での巡回展とか、各種講座等を行うとなっていますけれども、これは具体的にどういうふうにするのか尋ねました。","respondent":"篠田文化観光課長","answer":"それから、様々検討する課題はありますので、これは学芸員に引き続き現在の形の職員を雇用してまいるということで対応してまいります。区内の四、五か所ぐらい、様々な文化センターですとかの施設等の一角をお借りして対応していきたいというふうに考えているところです。","id":"exchange-023"},{"speaker":"藤原委員","kind":"質問・要望","question":"歴史館でたしか副区長に偶然ではなくてお会いしたことがあったと思っていたもので、今回、大規模改修するに当たって２年間閉める。２年間閉めるということで、その辺について、副区長からご意見をほしいと求めました。","respondent":"和氣副区長","answer":"やはりもっと来たときに体験したり、いろいろわくわくするような、そういう仕掛けをつくろうということで考えているところです。いろいろと意見は言わせていただく立場でありまして、私なりの考えがありますので、少しは反映していただきたいというふうに思っているところです。","id":"exchange-024"},{"speaker":"くにば委員","kind":"質問","question":"令和６年、２年後になると、かなり技術進化が見込まれております。何かその新たな取組というものを、私もぜひ期待をしているのですけれども、何か目玉の取組等のご計画があれば説明を求めました。","respondent":"篠田文化観光課長","answer":"ＶＲ等も検討したのですけれども、そうは言っても、いわゆる映像に関して展示をしていけないかと考えているところです。これも現在検討中のものですから、まだ最終的な決定はしていないのですけれども、そういった取組も念頭に置いて検討しているところではあります。","id":"exchange-025"},{"speaker":"くにば委員","kind":"質問・要望","question":"ぜひとも２年後の春という大分先のことですので、デジタル技術の活用に関して、検討を引き続き進めていただきたいというふうに思います。さらにその技術が発展していく中で、ぜひとも魅力がある施設にリニューアルの際に進めていただければと考えていますので、ぜひ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"２点お伺いします。何かそういうものを掲示していただくことが可能かというところが１点と、もう１つが、そこら辺の兼ね合いを教えてほしいと求めました。","respondent":"篠田文化観光課長","answer":"特に外装に関しましては、ちょっとまだ検討の余地があるのですけれども、そのような検討をさせていただければというふうに思ってあります。ですので、今回の事務所の移転に関しましても、区民の方の利用に支障のないような形での移転ということを念頭に置いて対応していますので。","id":"exchange-027"},{"speaker":"横山委員","kind":"質問・要望","question":"休館期間中の、どういった形で行っていく予定なのかということで、何か通常と変更があるのであれば教えていただきたいということが１点です。２点目が、この１年間の保管の状況について、どのように行われていくのかというところを確認させてください。","respondent":"篠田文化観光課長","answer":"できるだけ今までやってきたような講座については継続していきたいというふうには考えているところですので、これは何分、その辺を検討しながらです。こちらもそういった特別な対応がとれる事業者を選びまして、その辺は吟味をしまして、必要な対応をとっているです。","id":"exchange-028"}]},{"id":"topic-05","title":"大井ホッケー競技場再開業イベント","agenda":"大井ホッケー競技場再開業イベント","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"この先もここがオリンピックの会場だったという名前だったり、見て分かるものだったり、そういうものはないのですか。何かオリンピックの会場として使われた場所ということが残らないものなのか、その辺の状況だけご説明ほしいと求めました。","respondent":"辻スポーツ推進課長","answer":"ここはいついつホッケー競技が行われたところですということで、東京都の施設ですので、東京都がつけていると思います。中央公園のところに、そういった銘板をつけたりというようなことはしておりますので、同じような形で実施するような予定にはなってあります。","id":"exchange-029"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/227651?Template=document&Id=2926#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":33593,"voices":98}},{"id":"r04-20220516-7","meetingId":"r04-cm05","date":"2022年5月16日","dateIso":"2022-05-16","committee":"厚生委員会","time":"午後 １時００分～午後 ３時１３分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を40件整理しています。","topics":[{"id":"topic-01","title":"小山台住宅等跡地複合施設整備","agenda":"小山台住宅等跡地複合施設整備","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"行政需要の変化というところで、保育園は毎年増設もされているというところから見ると、よかったのかと思います。これは建物としては階高というのはどのぐらいなのかというのと、あと、区で建てて指定管理にしていくという考えでいるのかを説明を求めました。","respondent":"寺嶋福祉計画課長","answer":"３年前に行った説明会の資料では、３階建てから４階建てということになっていまして、そこまでの情報となっております。これは現時点ですけれども、区で区立施設を設置して指定管理ということを、まずは一番に考えているところです。","id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問","question":"１つの指定管理者が管理運営するということになるのか、また得意分野というか、管理運営できるところが変わってくると思うのです。これはそれぞれに管理運営されていくのか、それとも一体で考えているのか、その辺がもしあれば説明を求めました。","respondent":"寺嶋福祉計画課長","answer":"建物が３つの棟に分かれるというのが３年前の計画になっておりまして、それについては、特段まだ大きな見直しの変更等は考えておりません。まだ指定管理かどうかも含めて検討しているところなので、今、指定管理を第一の案として考えているです。","id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"改めて伺いたいのと、でも今年の８月なので、その辺もおよそあれば教えていただきたい。８月以降のスケジュールのところではなっていますけれども、いつ頃開設の見通しになるのか、伺いたいと思います。","respondent":"寺嶋福祉計画課長","answer":"用地取得につきましては、これはまだ見込みということなので、既に取得した都有地につきましては、約１０億円ということで取得しております。","id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"これから土地取得ということなのですけれども、これがスムーズにいったとして、見通しとして、いつ頃開設か、スムーズにいくとこれぐらいかというのがあれば教えていただきたいです。","respondent":"寺嶋福祉計画課長","answer":"全てが順調にいったらということで、全く不確定要素が多いのであれなのですけれども、恐らく令和８年、９年辺りぐらいでいけばいいかと考えてはいるところです。","id":"exchange-004"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ほかにも要望の多い障害者施設というのは、経緯というのですか、そこを教えていただきたい。それで、ほかの施設の検討というのもあった上で生活介護ということになったのかというのを伺いたいと思います。","respondent":"川崎障害者施策推進課長","answer":"改めて現場の声もお伺いしまして、生活介護の需要が増加するということを認識したため、追加させていただきました。","id":"exchange-005"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"現場の声というのは、今、運営している施設ということで、利用者団体とか、そういったところには、特に要望の聞き取りなどは、この小山台住宅等跡地複合施設についてのところでは特にされなかったということか尋ねました。","respondent":"川崎障害者施策推進課長","answer":"現場の声というのは、生活介護の事業者になります。","id":"exchange-006"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"事前にもうどこかの委員会で報告があったのかどうか分からないのですけれども、この土地に何を造るというふうなことは決まっているのでしょうか。もし決まっているのであれば教えていただきたいのと、その平米数と、その土地に何が造られるというふうなことが決まっているのか。","respondent":"寺嶋福祉計画課長","answer":"地域の説明会のときの資料ということになるのですけれども、いわゆる都有地のところが恐らく従来保育園であったという説明になっていたと思います。考え方としては、今、最終的に計画（案）を進めているです。","id":"exchange-007"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"それで、小山台住宅跡地のほうに障害者施設ができるということで、設計をこれから進めていくという考えでいいのか、ちょっと伺いたいと思います。２０名で、３つの機能が入った障害者施設ができるようになると思うのですけれども、その点も伺いたいと思います。","respondent":"寺嶋福祉計画課長","answer":"峰友寮と小山台住宅については、３階建てであったり５階建てであったりという、今それを解体しているということなのです。やはり地元の方のお考えに配慮すると、その辺は１つの目安にはなってくるのではないかということで、基本計画（案）を進めているところです。","id":"exchange-008"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"２０名、２０名となっているので、この人数が出てくるのかと思うのです。分かったら教えていただきたいのと、公立であるのかどうなのかというところも、ちょっと教えてほしいと求めました。","respondent":"寺嶋福祉計画課長","answer":"今日の段階では、これから基本計画ということになりますので、まだお示しできるほどの数値はまず持っていないということ。今の段階で考え得る方向性として、検討案の候補にはなってはいるのですけれども、まさにこれからの検討ということになりますので。","id":"exchange-009"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"こういう公有地を区が取得して建設するということなので、そうではないやり方も今後検討していくという、そういうこともあり得るという。区が土地を購入するけれども、民設で民営みたいなことの検討というのもあり得るということで、検討の中に入っていくということなのか尋ねました。","respondent":"寺嶋福祉計画課長","answer":"考え方としてはそれぞれあると思いますので、どういった形態が一番いいのかという、まさにそれを検討するのが我々の役目だと思っています。民間事業者を誘致するのかといったあたりは、その辺りまでには区の方針を決めて、国等にも示していかなければならないと考えております。","id":"exchange-010"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"これは国有地・都有地を区が購入して、障害者施設・高齢者施設を建設していくということですので、ぜひ公立、区立で建設していただきたいということで、要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"石田（秀）委員","kind":"質問","question":"３階、５階という既存の建物があったわけでありますので、こういう方向でいこうと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"４年、５年先なのですけれども、ご相談されたい方あるいは利用されたい方が増えることが予想されます。ですから、あるいは相談体制等をきちんとしていただきたいというところなのですが、その辺りはいかがか尋ねました。","respondent":"川崎障害者施策推進課長","answer":"今、委員がおっしゃったように、児童発達支援センターの件も、私どもでセンターとして療育拠点としての機能を有しておりますので、どのような形で支援体制の充実を図れるかということも含め、今後検討してまいります。","id":"exchange-013"},{"speaker":"若林委員","kind":"質問・要望","question":"今の石田秀男委員と高橋しんじ委員のご要望は、私も同じ要望をさせてほしいと求めました。区の対応も確認しているわけですが、その辺の近隣等のその後のご要望、姿勢を確認させていただきたいのが１つ。","respondent":"寺嶋福祉計画課長、松山障害者支援課長","answer":"基本方針の中に、それから委託施設等々の基本方針がある中で、しっかり対応していきたいとお答えをさせていただいたところです。まずは３年前に説明会があったときのご意見、丁寧にご説明していきながらご理解を、対応して。 箇所数は、１０か所の生活介護のうち、就労継続支援Ｂ型施設を併設しているところは２か所です。生活介護および就労継続支援Ｂ型施設の併設の考え方についてです。","id":"exchange-014"},{"speaker":"せお委員","kind":"質問・要望","question":"２点お聞かせいただきたいのですけれども、こちらを利用するかもしれない方々のご要望などを、お伝えする機会があるのかどうかということと。そういうものが決まっているようでしたらお聞かせいただきたいです。","respondent":"寺嶋福祉計画課長","answer":"変更がかかっているということなので、６月の下旬に説明会をした後、計画として正式に決めていきたいと。で地元の方のお考えもありますので、そこはしっかりご説明して、可能な限りご納得いただける方向に進めていきたいと考えております。","id":"exchange-015"},{"speaker":"せお委員","kind":"質問・要望","question":"住民、例えば障害者などが主かと思うのですけれども、ここを使うかもしれない当事者の方々などのご要望は聞く機会があるのかということ。ここは要望なのですけれども、林試の森公園も一緒にうまく活用できるような方向も入れていただきたいと、そちらは要望します。","respondent":"川崎障害者施策推進課長","answer":"先ほど委員におっしゃっていただいた、障害者の方がここを使うかもしれない、当事者の声を聞く機会ということですけれども、その辺りについては、今後どう機会を得て聞けるかどうかも含めて検討いたします。","id":"exchange-016"},{"speaker":"石田（秀）委員","kind":"確認","question":"ちょっとお聞きしたいのは、２か所でやっているということだったのだけれど、その辺はしっかりやってくださいというのが１点。国側は「ないですよ」と言うのだろうけれども、その確認というのは、区だったら誰がやるのか。","respondent":"寺嶋福祉計画課長","answer":"結論としては、「はい」と言って買ってしまうという。１年ぐらいかかっているのですけれども、その中には当然、その結果をきちんと説明を受けた上で購入するという段取りになるとは理解しております。","id":"exchange-017"}]},{"id":"topic-02","title":"認知症検診推進事業（もの忘れ検診）の実施","agenda":"認知症検診推進事業（もの忘れ検診）の実施","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"何か、国の計画の中で示されているというものなのか、要は実施の経緯を伺いたいです。表紙を開いた１ページ目の一番下に、今後どういうふうに検診が行われていくのかというのを、ちょっと伺いたいのです。","respondent":"川原高齢者地域支援課長","answer":"委員がおっしゃるとおり、今年度は６月１日から８月３１日までの３か月ということで、医師会を通じて９月以降に検討委員会をする予定です。１１月と予定していますが、どういった形で進めていくか、今年度に関しては短くなってあります。","id":"exchange-018"},{"speaker":"石田（ち）委員","kind":"質問","question":"９月から３月は、それで次年度の計画も検討していくということなのですけれども、検討委員会というのはどういうメンバーでされるのでしょうか。その次の丸のところの、「区より、これは受診者に向けて区が個別に支援していくということでいいのかということを伺いたいと思います。","respondent":"川原高齢者地域支援課長","answer":"委員のご質問の１点目の、検討委員会の委員の皆様のご紹介です。アフターフォローの個別支援を実施というところにつきましては、１回目、今後検討委員会で話し合っていきたいと考えているところです。","id":"exchange-019"},{"speaker":"石田（ち）委員","kind":"意見","question":"そうすると、検討委員会は荏原医師会から３名、品川区医師会から３名、そして事務局、そして品川区で、医療機関の先生方もと聞こえたのですけれども、そうすると、合計で何人ぐらいの検討委員会になるのか、聞かせてくださいとの意見を述べました。","respondent":"川原高齢者地域支援課長","answer":"現在のところでは、医師の方が６名、事務局が２名から３名、あと区の私ども職員が２名から３名の予定です。","id":"exchange-020"},{"speaker":"石田（ち）委員","kind":"質問","question":"高齢者地域支援課に、認知症サポート係という形で移ったと思うのですけれども、何か理由があるのか。何でかなと素朴に思ったもので、伺いたいと思います。","respondent":"寺嶋福祉計画課長","answer":"令和４年度に向けての組織改正の中で、理由は様々なのですけれども、１つはやはり、認知症に関しては予防という観点が非常に強いということから、そういった意味では、介護予防等をやっている高齢者地域支援課の業務とするということで、組織改正を行わせていただいたところです。","id":"exchange-021"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"認知症サポート係の体制はどれぐらいでされているのかを伺いたいのと、たしか認知症初期集中支援チームとか、そういう取組もされていたと思うのです。その辺の体制と現状と実績も併せて教えていただけたらと思います。","respondent":"寺嶋福祉計画課長、川原高齢者地域支援課長","answer":"そのままスライドしたと考えていただければいいのですけれども、「サポート」という名前を使わせていただいて、認知症サポート係。５名でやっていますけれども、認知症初期集中支援チーム… 引き続き検討に当たっているところです。今年度も私どもの課で実施する予定になってあります。","id":"exchange-022"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"よく聞こえなかったのですけれども、令和３年度が１回ですか。どういう中身になっていくのか、検診の内容について具体的に教えていただきたいのと、医師会委託みたいな形になるのか尋ねました。","respondent":"川原高齢者地域支援課長","answer":"予算額の見込みというところをご質問いただいていたと思うのですけれども、３８０人ほどの方に受診は頂ける見込みを考えてあります。もう一つが、口頭試問３問をする予定です。","id":"exchange-023"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"もの忘れ検診の箇所数が１５か所ということで、荏原医師会と品川区医師会と、それぞれたくさん書かれているのです。どういう方が、この１５か所のドクターなのかというのを教えていただきたいのと、その辺の状況を教えていただけたらと思います。","respondent":"川原高齢者地域支援課長","answer":"実際には、医師会を通じてご協力いただける機関ということで、１５か所ご紹介いただいたところです。令和４年２月現在で５４人、今年度は１５機関という形で、申し上げられることです。","id":"exchange-024"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"どう対応したらいいのか、検診の大事さを分かってもらう取組についてはどう考えられているのかということを教えていただきたいのと、それからあと。そういう場合は、そういう要請に応えるというのが、していただけるものなのかどうなのかというあたりも教えていただけたらと思います。","respondent":"川原高齢者地域支援課長","answer":"今回は７５歳のみになってしまいますけれども、そのようにお声がけをして検診を進めていただくという、一つひとつ積み重ねていければと考えています。２点目の、これからどのような形で連携していくかというところは考えて、いいような形で実施していきたいとは考えてあります。","id":"exchange-025"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"もの忘れ検診ガイドブックの１０ページのところに、区との連携や、それから区が委託しているという形になるのか。センターという形になっているのは、どのような役割で、具体的にどういうことをされているのか、その点について教えていただけたらと思います。","respondent":"川原高齢者地域支援課長","answer":"特別、病院に対して区が委託を図っているという形ではなくて、認知症に対する相談のメインの拠点という形でさせていただいているところです。代表として挙げさせていただいている形です。","id":"exchange-026"},{"speaker":"若林委員","kind":"質問・要望","question":"この５,０００人にはそういう方は入っていないということなのかという確認がもう一つと、認知症というのは、いわゆるファジーな部分がありますよね。そういう設定をされると約３５０名、１つのクリニックで２０名前後というところで、その辺を確認させてほしいと求めました。","respondent":"川原高齢者地域支援課長","answer":"ご質問いただきました検査方法についての３点のご説明です。軽度の認知症に関しては、もちろん、この検診を受けていただいて、かかりつけ医以外の先生のご判断をしていただくことができることを見込んです。","id":"exchange-027"},{"speaker":"若林委員","kind":"確認","question":"あえて先生が、あなたは違いますと現場でするのか、そこを確認します。そうすると米印自体が、何か意味があるのかという議論にもなってしまうのですけれども。","respondent":"川原高齢者地域支援課長","answer":"説明の仕方が分かりづらくて申し訳ありませんでした。医療機関では柔軟に対応していただく形になってありますので、その方に対しても郵送はさせていただいているところです。","id":"exchange-028"},{"speaker":"若林委員","kind":"意見","question":"例といえば例なのですけれども、今はいつも、エビデンスがとか、根拠は何というご時世なのでという疑問です。米印の扱いについては、これはもう届けられているということなので、柔軟なというところで、今後、また表現等にご配慮いただければいいかとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-029"},{"speaker":"高橋（し）委員","kind":"質問","question":"地域的に、希望があっても、ここは行けないかという感じを受けるのです。地域的なバランスでしょうか、今回はこの１５か所で、今後のことについてはどのようにお考えになっているか尋ねました。","respondent":"川原高齢者地域支援課長","answer":"委員のおっしゃるとおり、地区によって多少のばらつきのあるところがあります。最終的な調整で１５医療機関と、さらに医師会の先生方にもご協力いただいて実施できるクリニックを増やしていきたいという形では考えてあります。","id":"exchange-030"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"せっかく、例えばご家族の方やご本人が、では行こうというふうに、ご家族に説得していただいたときに、「ちょっと遠いね」みたいになってしまったときに機会を失うと思うので、せっかくよい施策ですので、多くの方がサービスを受けられるように、今後、医師会の方のご協力を何とか求めてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"}]},{"id":"topic-03","title":"新型コロナウイルス感染症に係る保健所・保健センターの対応","agenda":"新型コロナウイルス感染症に係る保健所・保健センターの対応","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"前回この委員会で求めたときに、確かに延長されているのですけれども、でももう来週で終わってしまうのですね。そういう段階なので、ぜひ東京都に引き続き延長を求めていただきたいと思うのですけれども、いかがか尋ねました。","respondent":"坂野保健予防課長","answer":"すみません。よろしくお願いします。","id":"exchange-032"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"お伝えいただきたいのと同時に、区として求めていただきたいと思うのですけれども、そういった考えはないということか尋ねました。","respondent":"坂野保健予防課長","answer":"区として独自に延長をという趣旨でございましょうか。それは現在、考えているところではございません。","id":"exchange-033"},{"speaker":"若林委員","kind":"確認","question":"こことは違うのかもしれないのですが、日本に、ウクライナからの避難民の方が東京都の中にいらっしゃって、こういう方のワクチンはどういう考え方なのか、何か方針が出ているのか、これからどうするのか、全く情報がないか、それだけ確認を。","respondent":"坂野保健予防課長","answer":"どうこうしているかというのは、申し訳ないのですが、今のところ情報はございません。","id":"exchange-034"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"１日どれぐらいの、入院患者がこれだけ減ってきていないというのはどういう状況と捉えられているのか、その点についても伺いたいと思います。その辺の区の見解と品川区の感染状況について教えていただけたらと思います。","respondent":"坂野保健予防課長","answer":"今は検査が必要な人を全て受け入れていますので、そういう点においては、足りている。陽性率だけ見ると、確かに２０％とかあるわけなのですが、それをもってすぐ、足りていないというふうにはならないだろうと考えております。","id":"exchange-035"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"ここ１週間ぐらい、前の週に比べて増え続けているという状況が続いていますし、まだまだコロナは収束という状況には程遠い状況だと思うのです。区は検査を延長してほしいということを、私は改めて申し入れてほしいと求めましたし、改めてこれは要望として申し上げておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"}]},{"id":"topic-04","title":"品川区新型コロナウイルスワクチン追加接種","agenda":"品川区新型コロナウイルスワクチン追加接種","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"ワクチン接種の接種率のところで、先ほどもワクチンを廃棄しなくてはいけないという説明もありましたけれども、全体的に３回目の接種が、６０歳以上の方でも２回目接種より低い接種率というところでは、これはなぜなのかというのは、区としてはどう考えられているのかというのをお聞きしたいのです。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"この９３.８％、打った方の９割ぐらいが打つであろうと考えていましたので、計算すると８６％ぐらいの数字になってくるのです。もう少し数字は増えていくのではなかろうかとは考えているのですが、打ちたい方は、ほぼ打ち終わったのではなかろうかとは考えております。","id":"exchange-037"},{"speaker":"鈴木（博）委員長","kind":"質問","question":"では私から少し質問。１つは、どういう方を対象にして、どういう形で製造するのでしょう。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"一番最初に要求した７００人分が終わったら、初めだけ区でやって、あとの方は東京都にということは考えておりました。もしかしたら若い方が食いつくのではないかとは考えておりますので、ＳＮＳ、要はウェブを使って宣伝をしていくということで現在考えております。","id":"exchange-038"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"５,０００人もいるのですけれども、それはどういうことなのか、教えていただけたらと思います。それから、これも基礎疾患のある方の１万３,０００人の中に入っているということなのか、その点も伺いたいと思います。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"順番にご説明、回答します。こちらで把握できるものではありませんのと、この文言のみの説明で、これ以上の説明は現時点ではまだありません。","id":"exchange-039"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"自ら手を挙げないと、こういう方には発送されないわけではないですか。これを広報しないと手を挙げることができないと思うのですけれども、その広報というのはどういうふうにされようとしているのかも伺いたいと思います。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"ＢＭＩ３０以上の方は、もう自らのご申告という形で間違いございません。基本的に６０歳未満の方になりますので、もちろん広報しながわ６月１日号で、ホームページ等々を中心に使って広報していきたいと考えております。","id":"exchange-040"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/567724?Template=document&Id=3626#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":36972,"voices":120}},{"id":"r04-20220516-8","meetingId":"r04-cm05","date":"2022年5月16日","dateIso":"2022-05-16","committee":"建設委員会","time":"午後 １時００分～午後 ２時１７分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を17件整理しています。","topics":[{"id":"topic-01","title":"八潮五丁目地区まちづくりワークショップの実施状況","agenda":"八潮五丁目地区まちづくりワークショップの実施状況","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"主な意見として、これがどこになるのか、どういったところなのかというところを伺いたいと思います。総勢３４名というような、この自治会・管理組合の推薦の方が１４名で、ほかの方はどういった方がいらっしゃるのか伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"そうした形でご参加いただく予定だったのですけれども、昨年の５月で、実施はさせていただいたというところです。これから２回程度会を予定していますが、ご意見を全体からいただくという形も考えておりますので、その中で進めていきたいです。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"庁内での検討の体制というのですか、そういったところは、このガイドランの位置づけなども含めてどのようになっているのか伺いたいと思います。今月５月に骨子案が示されるということなのですけれども、どういったものなのか、ご説明できるということがあればご説明ほしいと求めました。","respondent":"鈴木都市計画課長","answer":"そうした中でも、いろいろご意見をいただきながら進めていきたいというふうに考えてあります。今のところ６月、６月中旬ぐらいに実施をしていきたいというところで、お示ししてご議論をいただきたいというふうに考えております。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ多くの方が参加をして、住民の意見を反映できるようにしていってほしいと求めましたが、いかがでしょうか。今予定では９月になっておりますが、そこの位置づけというのですか、その辺りも伺いたい。","respondent":"鈴木都市計画課長","answer":"そうした中でも、先ほど口頭でご説明しましたけれども、いろいろご意見をいただきながら進めていきたいというふうに考えております。〔「意見募集とパブコメが同じか」と呼ぶ者あり〕 パブコメの実施条例に基づいて、それを八潮に限定という形にはなりますが、八潮にお住まいの方に全戸配付をして意見をいただくと。まさに内容的にはパブコメと同様の中身になろうかと思います。","id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"飲み屋がないという話も聞きまして、そういったさらなる充実をしていっていただきたいと思うのですけれども、いかがでしょうか。医師会との連携なども含めて、そうしたお考え、方向性などあれば伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"いろいろな説明をして、それぞれが取組を進めていたところに横串を刺して、連携を図りながら進めていくと。様々な検討をされながら進めていくのではないかというところで考えてございまして、しっかりそのような連携、いろいろな検討。","id":"exchange-004"},{"speaker":"のだて委員","kind":"提案","question":"そういった調査、把握をしていくことがニーズ把握にもつながってくるのかなと思うのですが、そういったことはお考えかどうか伺いたいと思います。１つ住民の方から伺ったのは、子どもとその家庭を支えていく施策なども必要ではないかと思うのですが、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"いろいろな取組をこれから検討して改定を進めていきたいというふうに考えてありますが、今現在は、全体の検討の中ではそうした考えはございません。","id":"exchange-005"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ若い人たち、新しい人たちが住みやすいようにしていくということも、自治体の１つの取組として取り組んでいってほしいと求めました。ですから、住み替えをするような仕組みというものがあると住み続けられるのかなと思うのですが、そういったお考えはいかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"例えばその賃貸を行っている事業会社のほうで、こうしたアンケートの結果などは、そうした八潮団地内の賃貸のほうの事業者の方とも共有をしています。","id":"exchange-006"},{"speaker":"西本委員","kind":"質問","question":"そうではなくて、これからのことを聞きたいのですけれども、八潮地区をどうしたいのですか。民間の力を借りていくのか、どのような方向で持っていくのか尋ねました。","respondent":"鈴木都市計画課長","answer":"例えば５年前から進めているなどということだと思うので、１５年前から検討が開始されて、八潮のまちづくり担当が組織立てられたと。","id":"exchange-007"},{"speaker":"西本委員","kind":"質問・要望","question":"そこの八潮地区というものをこれからまとめていくのでしょうから、そのようにしていただきたい、話合いをして。細かいところなどと、そのような話ではないと思うのですけれども、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"ご説明してご意見をいただいたときに、基本的に先ほどからご説明している、組織立てられたというところの理解です。","id":"exchange-008"},{"speaker":"西本委員","kind":"質問・要望","question":"八潮地区をどう思いますかでもいいし、そういう要望でいろいろな立場の人、外から見るときの意見というものも大切だと思うのです。そのようなものがあったらいいね、ぜひ将来像をみんなで想像できるような、そのようなまちづくりというものをぜひ実現してほしいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"塚本委員","kind":"確認","question":"最初に、八潮は昭和５８年、第１回の入居が開始ということで、ほぼ４０年前ですか。築５０年ぐらいになったらもう住めませんよというような話とか、その辺、そのところをまず確認させてほしいと求めました。","respondent":"鈴木都市計画課長","answer":"このまちづくり検討経費、あるいは５年、１０年で建て替えるということは全く考えていませんと。そうした中で、空き家も非常に少ないということで聞いておりますので、当面は適正に管理をしながら使っていくということで理解しています。","id":"exchange-010"},{"speaker":"塚本委員","kind":"質問・要望","question":"今度住み続けたいですかというアンケートで、当然と言えば当然かもしれませんが、住み続けたいと。見落としたかもしれませんが、そこのところ、どのような人たちが入居してくるのかという傾向性等が分かれば教えてほしいと求めました。","respondent":"鈴木都市計画課長","answer":"アンケートの問１の居住開始年というところをご覧いただいて、１４％ですとか、二年で出ていくと。一定程度継続して住んでいらっしゃる方もいるのですけれども、どういった方々が入居を考えて、ちょっと今現在把握していないです。","id":"exchange-011"},{"speaker":"塚本委員","kind":"質問・要望","question":"１回住んだ方には、今度はなるべくずっと長く住んでいただきたいというのが、多分考え方としてはあるのかなと。最後に、その視点についてどのようなお考え、議論等があるかということを説明を求めました。","respondent":"鈴木都市計画課長","answer":"そうしたものにもつながっていくということで考えておりますので、これからは八潮については考えていかなければいけないのかなと、八潮に住み続けていきたいというようなことを外にも発信していただけるような地域にしていかなければいけないのかなです。","id":"exchange-012"}]},{"id":"topic-02","title":"品川区立区民住宅（ファミーユ西五反田西館・東館）指定管理者候補者の公募","agenda":"品川区立区民住宅（ファミーユ西五反田西館・東館）指定管理者候補者の公募","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"質ですか、むしろ向上させていかなければならないと思うのですけれども、経費の縮減というのはどのようなことなのか伺います。","respondent":"竹田住宅課長","answer":"指定管理者との契約の中で、いかにランニングコストを抑えていくかということが指定管理の課題だと思っています。そういった点で、新しい提案を出していただけるように求めていきたいと考えております。","id":"exchange-013"}]},{"id":"topic-03","title":"の２のその他","agenda":"の２のその他","exchanges":[{"speaker":"西本委員","kind":"質問","question":"できれば今期、やはり最終的には決断は出さなければいけないのではないかと思うのですが、その議論をしていないのです。継続という議論はしているのですけれども、今期どうするかという話はしていないのですが、それはどのように考えたらよろしいのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"西本委員","kind":"確認","question":"ですから、今年度、令和３年度の建設委員会の継続審査になっている案件というものはどうされるのか。ですから、今日はその話があるのかなと思ったのですが、それはもうなしということなのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"西本委員","kind":"確認","question":"ですから、私は確認したかったのですけれども。ですから、継続かどうかということの報告を含め、議論はあるのかなと期待をしていたのですけれども。","respondent":"こんの委員長","answer":"皆さんに諮ってこれをするというよりは、もう継続ということなので、今期についてはしません。この建設委員会で取り扱っていただくという流れは、ここは継続されていきますので、ご心配要らないと思うのです。","id":"exchange-016"},{"speaker":"西本委員","kind":"質問・要望","question":"どうなのかなと思うのですけれども、継続審査というものが次年度への継続審査という形で出さないとおかしいのではないですか。最終的には出てくるのですが、ただ委員会としての仕切りはしなければいけないのではないですかというように指摘をさせていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/985406?Template=document&Id=4348#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":24949,"voices":50}},{"id":"r04-20220516-9","meetingId":"r04-cm05","date":"2022年5月16日","dateIso":"2022-05-16","committee":"文教委員会","time":"午後 １時００分～午後 ３時４６分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を46件整理しています。","topics":[{"id":"topic-01","title":"令和４年度学校別新入学者の増減要因","agenda":"令和４年度学校別新入学者の増減要因","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"今回、学校選択を希望した方は小学校・中学校で何人いるのかという数字を改めて伺いたいのと、（ａ）は何人だったのか伺いたいというのが一つです。それと、こういったことを報告するということの区としての目的というのは、改めてどのように考えているのか伺いたいと思います。","respondent":"勝亦学務課長","answer":"令和３年度の新入学の（ａ）につきましては、小学校が４７７人、中学校につきましては３８５人となっています。お考えの中で、数字として全体的なものを把握し、そちらをご報告させていただいていると考えています。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"伺いたいのですけれども、去年質問すると、学校教育法の施行令第８条にある制度なのですと。伺いたいのは、品川区として指定校変更を認める場合の基準について教えてほしいと。","respondent":"勝亦学務課長","answer":"指定校変更ですけれども、委員にご説明いただきました中で、指定校変更の申請をいただいた中で。指定校変更の申請の数ですけれども、正確な数字については現在、手元に数字がございませんので、ご了承いただければと思います。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"ざっとどういう内容なのかというのを伺いたいし、感触、割合とかがあるのではないか。ほとんど受け入れていますという話なのか、その辺だけもう少し伺いたいのですが。","respondent":"勝亦学務課長","answer":"指定校変更につきましては、一律に申請を受けたら認めるといった形ではなく、一つ一つ審査をさせていただいた上で認めているものです。基準に合致しないものは指定の変更が認められないということで申請を却下していますので、数としましては、正確には分からないですが。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問","question":"なので、それは必要な大事な制度だと思うのですけれども、１点だけ最後に伺いたいのは、時期は選択制が先ではないですか。なぜ半分も切られるのか、その辺が少し不安なのですけれども、どうなのか尋ねました。","respondent":"勝亦学務課長","answer":"そういった中で、教育的配慮は最大限尊重したいと考えますけれども、キャパシティーを超えての入学はできないという部分があります。学校を教育委員会が指定するに当たりまして、就学の指定をした後に教育的配慮をする指定校の変更とは、また別の制度と考えております。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"指定校変更で、どうしても教育的配慮上、今の区域内の学校に通えないという子どもたちを優先すべきなのではないかと思うのです。そういう実態はないのですか、必要な教育上の配慮ができないようになっていないですかということだったので、もう一度お伺いします。","respondent":"勝亦学務課長","answer":"キャパシティーの問題はありますけれども、指定校変更に関しましては、あくまでも学校を指定した後に行うものでございまして、学校選択に関しましては、就学の指定をする前に参考としてやるものという形の制度の違いで、順番につきましては前後するものです。","id":"exchange-005"},{"speaker":"つる委員","kind":"質問","question":"もし過去の質疑とか、今日の説明の中にあったら大変申し訳なかったのですが、増要因・減要因とか、それぞれの項目でのその他、（ｅ）とあると思うのですが、その他というのはどういう項目か、改めて説明を求めました。","respondent":"勝亦学務課長","answer":"その他につきましては、主なものとしましては、就学の猶予ですとか免除をされている方になります。外国籍で区立の学校に入ってこないという方ですとか、そういった方がその他という形になってあります。","id":"exchange-006"},{"speaker":"つる委員","kind":"質問・要望","question":"ずっと確認できていることなのですが、１か月程度お時間を下さいという、その辺を参考に説明を求めました。","respondent":"勝亦学務課長","answer":"指定校変更につきましては、変更したいという申請をいただくものでございまして、制度的には厳密には。保護者の意見を聞いた上で１２月に学校を指定していますので、学校の指定をした後から入学までの期間に指定校変更の申請をいただいているものです。","id":"exchange-007"},{"speaker":"つる委員","kind":"確認","question":"すみません、前半のその他のところの認識の確認なのですが、何か補足があれば説明を求めました。","respondent":"勝亦学務課長","answer":"失礼いたしました。多くが外国人ですとか、就学の猶予をされた方という認識です。","id":"exchange-008"}]},{"id":"topic-02","title":"令和４年度（５年度採用）品川区立学校教育職員採用候補者選考日程","agenda":"令和４年度（５年度採用）品川区立学校教育職員採用候補者選考日程","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"昨年は３名採用しますということだったのですけれども、目標としている３０名になったと思うのですが、今回の採用数がなぜ４名になるのでしょうか。それとも退職者などが出られたのか、それとも３０名を超えて採用することにしましたということなのか、その辺を伺いたいと思います。","respondent":"中谷指導課長","answer":"予定どおり最終合格者の３名を確保したところですが、実際に採用した人数につきましては１名ということで、辞退者が出たという経緯があります。令和３年度をスタートして１年間の中で、ご案内をさせていただいている４名ということで、このような募集をさせていただいているです。","id":"exchange-009"},{"speaker":"安藤委員","kind":"質問","question":"分かりました。４名採用しなくてはいけないということになるかと思うのですが、特に教育行政として何か要因があるとはお考えなのか、その辺を伺いたいと思います。","respondent":"中谷指導課長","answer":"今回の４名の募集ということにつきましては、先ほどお伝えさせていただいたとおりです。これまでの１０年間を見たところによっても、こういったことも含めて、毎年採用をしていくように考えております。","id":"exchange-010"},{"speaker":"吉田委員","kind":"質問","question":"だから、これは確かに品川区だけで解決できる問題ではないと思うのですけれども、同様の課題を品川区としても認識しておられると思うのです。例えば、何か対策みたいなことを考えておられることがあったら伺いたいと思うのですが、いかがか尋ねました。","respondent":"中谷指導課長","answer":"３０名というところを目標にずっとやってきておりましたので、この計画どおり進めていくというものになります。小学校のほうで、そういったところもしっかり活用しながら、教員の確保ということについてはしっかりやっていきたいと考えています。","id":"exchange-011"},{"speaker":"吉田委員","kind":"確認","question":"大学時代に、カリキュラムとは違うのでしょうか、何かそういうことがあるということなのでしょうか。すみません、もう一回確認させてください。","respondent":"中谷指導課長","answer":"研修のような体制で１年間を過ごすというものになっておりまして、１日２日では経験できないことを、実地の体験も含めてしっかり学べるというプログラムになっております。","id":"exchange-012"},{"speaker":"吉田委員","kind":"質問","question":"整理をすると、固有教員を育てるという言い方は変ですが、そちらへの応募者を増やすような取組をしているという理解でいいでしょうか。ごめんなさい、もう一回。","respondent":"中谷指導課長","answer":"教育実習とは別にやっていくものになります。採用の日程ですとか、案内をしっかり大学にしていきたいと考えていますので、そちらを並行しながらやっていくというものです。","id":"exchange-013"}]},{"id":"topic-03","title":"品川区立図書館第三期指定管理者選定","agenda":"品川区立図書館第三期指定管理者選定","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"委託契約上はどうなっているのでしょうか、伺いたいのと、伺いたいと思います。図書館司書資格を持っている方の配置については、指定管理の委託契約上はどうなっているのか、伺います。","respondent":"吉田品川図書館長","answer":"２番目の図書館資料の選定に当たりましては、募集要項の中でも、図書館資料の一次選定というのが指定管理の業務内容として入っているところです。","id":"exchange-014"},{"speaker":"安藤委員","kind":"質問・要望","question":"本来なら利潤を上げるということが使命なのが株式会社なわけですから、それでも参入するというところがあるのはなぜなのでしょうか。当然持続的に従事できないわけですから、なるべくお金をかけないで管理運営するということを求めるのは、そこについてはどうか尋ねました。","respondent":"吉田品川図書館長","answer":"一定程度、司書資格だとか、そういうものを持った者に図書館業務を担ってもらうという形で書いてあるところです。施設の効用を最大限に発揮するとともに、そちらにつきましても、その見合いが取れるような形で指定管理を進めていただければと考えているところです。","id":"exchange-015"},{"speaker":"安藤委員","kind":"質問・要望","question":"見合いが取れる範囲で進めてほしいということをやると、２番目の質問にも重なってくるのですけれども、もうけを上げる施設ではないわけです。公立施設の図書館としての考え方を持っていらっしゃるわけですから、きちんとした待遇で採用して、図書館への指定管理制度はやめていただきたいと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"吉田委員","kind":"提案","question":"こういうことがいつもの具体的な選定では行われていますというような、意欲的な選定の仕方というのがあったら、事例を伺ってみたいと思います。それをプロポーザルの提案の中で、何かあるのではないかと思うのですけれども、その辺について事例があったら伺いたいと思いますとの意見を述べました。","respondent":"吉田品川図書館長","answer":"それなりに条件がいろいろ、１０施設があって、１０館全てそれなりに異なる施設です。大崎図書館につきましてはリハビリテーションパークとの連携で、いろいろな提案、その中で審査していくという形になるところです。","id":"exchange-017"},{"speaker":"吉田委員","kind":"質問・要望","question":"この辺については要望です。ごめんなさい、難しい質問かもしれませんけれども、伺いたいと思います。","respondent":"吉田品川図書館長","answer":"それから、毎年１回、各施設で利用満足度調査というのをやっております。各館でも、例えば７割から８割以上のその図書館についての満足度が出ておりますので、それなりの一定の評価は受けているものと考えているところです。","id":"exchange-018"},{"speaker":"吉田委員","kind":"質問","question":"すみません、難しい質問をいたしました。ぜひその辺については、難しいのは承知ですが、具体的なご報告を今後いただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"湯澤副委員長","kind":"質問・要望","question":"はどういった成果を求められているのかというのが１点と、それから、図書館運営にも大きな影響があったのではないかと思います。そういった場合はお願いや、あとは場合によっては指導とか、そういうのもされていらっしゃるのかというのをお伺いさせてほしいと求めました。","respondent":"吉田品川図書館長","answer":"コロナ対応につきましては、令和３年度以降につきましては、費用として含めているところです。どういう対応をしなければならないとかというのは、保健所の指導の下に、このような対応をするようにという形で連携を取っているところです。","id":"exchange-020"},{"speaker":"湯澤副委員長","kind":"質問・要望","question":"より開かれたとか、より多くの方に使っていただくというところで、民間のノウハウを活用するというところはあると思います。要望といったものを、管理をしてほしいというところ、そういった要望というのもしっかりと叶えられるところもお願いしたいと思いますし。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"つる委員","kind":"提案","question":"選考のときに事業者からいろいろ提案等があるとは思うのですが、今伺っている取組だとか、そう差はないと思うのです。その部分が、いわゆるノウハウが画期的に違うのですかというものがどうなのだろうかとの意見を述べました。","respondent":"吉田品川図書館長","answer":"ＳＤＧｓの７館のところの質問につきましては、今は分かれた感じになっておりますけれども、そこのところは今後調整してまいります。全体的にはそのような形で周知を図っているところです。","id":"exchange-022"},{"speaker":"つる委員","kind":"質問・要望","question":"ノウハウのところは、いろいろなやり方があると思うのです。品川区が求める、こういうものをやってほしいという、品川区からぜひ伝えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"}]},{"id":"topic-04","title":"請願・陳情審査","agenda":"請願・陳情審査","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"今、子育て応援課として取り組んでいる内容について伺いました。具体的に、そういうときにはこの制度が使えますというご案内というのは、何かあるのか尋ねました。","respondent":"飛田子育て応援課長","answer":"その場合、養育費とかは取れるのかとか、そういう相談から入ってきています。そういう家庭相談というところで、こちらで受け付けていますというアピールというか、周知をしているところです。","id":"exchange-024"},{"speaker":"吉田委員","kind":"確認","question":"そうすると、制度として示されているのは、ざっくりとした家庭相談で、その中に、具体的にこういうことも相談の対象になっていますというところまで、制度として示されているのか、もう一回確認させてください。","respondent":"飛田子育て応援課長","answer":"そうです。この人にとって何が必要なのか、何を聞きたいかということに合わせて、こちらで相談に応じているところです。","id":"exchange-025"},{"speaker":"吉田委員","kind":"質問","question":"その後、相談をしました。これも具体的な制度というのでしょうか、例えばこういう合意書をお互いに交わしたらどうですかというところまで何かあるのか、伺いたいと思います。","respondent":"飛田子育て応援課長","answer":"人によってはその一歩先ということで、養育費プランの作成支援というのも令和３年度から、こちらで養育費相談支援事業ということで行っております。その中で、公正証書の作成支援ということで、公正証書の作成費用の補助ということも令和３年度から開始したところです。","id":"exchange-026"},{"speaker":"安藤委員","kind":"質問","question":"お話を伺っていたときに、子どもにとってどうかというか、とても意味があると。離婚したといえども、品川区としてはどのようにお考えなのかということも、２つ目として伺いたいと思います。","respondent":"飛田子育て応援課長","answer":"面会交流をどのように考えているかということですが、面会交流は非常にお子さんにとって大事なこと、それは区でも受けております。そういうところを考えると、子どもにとって何が一番幸せなのか、そういうところはしっかり考えていかないといけないことだと思います。","id":"exchange-027"},{"speaker":"安藤委員","kind":"質問","question":"私はこれはやるべきだと思うのですが、どんどん子どもが大きくなってしまって、区はまだそういう立場で変わらないということなのでしょうか。品川区の中でそういう声が出ているわけですから、実態があるわけですから、いかがか尋ねました。","respondent":"飛田子育て応援課長","answer":"令和２年度のところから、皆さん周りを見て、面会交流の難しさというところで立ち止まっているような現状があります。取りあえずこちらで支援を令和３年度から始めていますが、また今後２人の生活にとって何がいいのか、話し合っていくように進めているところです。","id":"exchange-028"},{"speaker":"松本委員","kind":"質問","question":"離れている親に会いたいという相談を受けるような体制というのは、何かしら品川区内にあるのか、伺いたいと思います。子どもの権利を考えるのだったら、子どもが会いたいと言ったときに対応できるかどうかという体制は重要だと思うので、そちらのご答弁をお願いします。","respondent":"飛田子育て応援課長","answer":"子育て応援課としましては、まず大人の話合いのところで相談業務をやっているところです。子育てについて、子どものところから、保護施設とか、そういうところでまた話が上がってくることだろうと考えております。","id":"exchange-029"},{"speaker":"松本委員","kind":"質問・要望","question":"別のところからというご見解なのだと思うのですけれども、そういうところと連携はしていただきたいと思うのですが、そこはいかがか尋ねました。","respondent":"飛田子育て応援課長","answer":"もちろん、お子さんを取り巻く環境というのは様々で、お子さんなりの考えもあると思いますので、そういうところは関係機関とも相談しながら、丁寧に応じていきたいと考えております。","id":"exchange-030"},{"speaker":"松本委員","kind":"質問・要望","question":"それが難しいのも理解していて、一方でこの陳情者が一番訴えている点というのは、面会交流のコーディネートをやってほしいというところだと思います。区としても研究して、少しでも進めてほしいと求めましたが、いかがか尋ねました。","respondent":"飛田子育て応援課長","answer":"ただ、面会交流とかそういうところを実施しているかというところでは、まだ国や都でも明確に言われていないところもあります。ですので、そういうところも鑑みながら、また様子を見て検討していきたいと考えております。","id":"exchange-031"},{"speaker":"松本委員","kind":"質問・要望","question":"実は日本弁護士連合会とかは、場合によっては反社がこういうところに入り込む可能性もあるという話をしています。実は日本の法律上は、何とか地方自治の段階から少しコーディネートできるようにお願いいたしまして、これを要望として申し上げて終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"松澤委員","kind":"質問","question":"私もこの陳情を伺ったときに、港区や明石市の情報を収集、調べておりました。面会交流の援助に取組むために、現段階で品川区からここに相談を依頼したとか、そういった件数が分かりましたら説明を求めました。","respondent":"飛田子育て応援課長","answer":"こちらでご案内というか、こういう相談事業がありますということでご紹介しますが、その後、その家庭で話し合われて、そこを利用するかしないか、そこまではこちらで把握できていない状況です。","id":"exchange-033"},{"speaker":"つる委員","kind":"質問","question":"先ほど松本委員の質疑を伺っていて、今回の場合は、それぞれの方が相談をする場というのがあるのですけれども、子どもの相談というのはまた別である。でも、家庭の中の不和という課題についての子どもからのアプローチというのはどの程度あるのか、分かる範囲で教えてほしいと求めました。","respondent":"染谷子ども家庭支援センター長","answer":"児童家庭相談の実施状況の部分につきましては、養育困難の家庭ですとか、そういった方からのご相談もお受けしている状況です。そこに対して、こちらで実際に持っている資源などをご紹介させていただきながら、ご相談に応じていくという対応をしています。","id":"exchange-034"},{"speaker":"つる委員","kind":"質問","question":"その辺りのバックヤード、さっき松澤委員もおっしゃったようなバックヤードの連携というのが、行政としてどの程度までできるのか。どういう入り方で、子どもに対する支援についてはやってこられているのかというのを、改めて説明を求めました。","respondent":"飛田子育て応援課長","answer":"はっきり言って、そんなに面会交流のところでは、あまりぎくしゃくはしていない。そういう時間を与えて、子どもが会いたいときに会える環境というように、話がスムーズにいくところがほとんどだと聞いております。","id":"exchange-035"},{"speaker":"つる委員","kind":"確認","question":"分かりました。この陳情のところで確認すると、私も６年前、そういう状況が分かれば教えてほしいと求めました。","respondent":"飛田子育て応援課長","answer":"実績は、令和２年度は３件、令和３年度は２件、コーディネートの申込みがあったと伺っております。そして、文京区は令和３年度よりということで、文京区の実績は１件のみと報告を聞いております。","id":"exchange-036"},{"speaker":"つる委員","kind":"確認","question":"まさに今、また課題の困難性があるからこそ、例えば裁判所とかにお願いをするという現状があろうかと思うのです。先ほど確認させていただいた子どもの相談事に対する体制の在り方というのは、一定程度必要かと、そこについては引き続きお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"安藤委員","kind":"意見","question":"そういうときでも、子どもが両親から愛情を感じて、適切な愛着関係が形成できているというのが、私は成熟した社会ではないかと。検討を進めて、実施できるところは実施していくべきだと思いますので、採択を主張いたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-038"},{"speaker":"吉田委員","kind":"質問・要望","question":"お話を伺っていて、子育て応援課だからやむを得ないかと思いますけれども、親のほうの相談という視点が多いかと思いました。この陳情者は具体的な支援策と整備体制の充実を求めておられますので、採択は妥当ではないかと思って、採択を主張いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"松本委員","kind":"質問・要望","question":"会えないのはつらかったし、なぜ誰も助けてくれなかったのかという話もあります。ぜひ品川区においては進めてほしいと求めましたし、議会の対応としてやっていくことが重要ではないかと思い、採択を主張します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"}]},{"id":"topic-05","title":"を改めて聴取いたします。 (4)法改正に伴う児童手当事業の変更点","agenda":"を改めて聴取いたします。 (4)法改正に伴う児童手当事業の変更点","exchanges":[{"speaker":"安藤委員","kind":"確認","question":"今回の変更の理由をどのように聞かれているのかというのを伺いたいのが一つと、資料の１の（２）の届出義務の廃止のところなのですが、２行目の「公簿のみでは現況を確認することができない」と書いてある公簿というのは、具体的には何を指しているのか伺いたいと思います。","respondent":"飛田子育て応援課長","answer":"国からの通知につきましては、今回上限を０円というところでは、その分、消費者対策にお金を回すように国は考えていると伺っております。そこでは分からない方に対しては、現況届が引き続き必要になります。","id":"exchange-041"},{"speaker":"松本委員","kind":"質問","question":"扶養親族等の数が０人のところも表に載っているのですけれども、０人だったらここは想定する必要がないのではと思ったのですが、０人が載っているのはどういう理由なのか尋ねました。","respondent":"飛田子育て応援課長","answer":"こちらは前年度の収入が適用されますので、お子さんがその後、生まれた場合ということになりますので、扶養家族が増えたとか、そういうところで０人と記載をしています。","id":"exchange-042"}]},{"id":"topic-06","title":"令和４年４月入園申請状況等","agenda":"令和４年４月入園申請状況等","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"４０点のＤ２５の方は全て入れていますと聞こえたのですが、そこは私の勘違いだったのでしょうか、伺いたいと思います。指数の点で伺いたいのですが、４０点となると結局、共働きフルタイムということですよね。","respondent":"立木保育課長","answer":"指数が４０点で、税の階層がＤの２５の方までが入園したという形になりますので、例えばＤの２６階層の方は入れなかったということになります。区としては目指していますので、特に点数、指数での目標ということを設けていることはございません。","id":"exchange-043"},{"speaker":"安藤委員","kind":"確認","question":"最下指数のことでもう一度確認なのですが、４０のＤ２５と表記されている場合は、４０でＤ２５の人が複数いた場合もあるのではないですか。今年度内あるいは来年４月とか、目標数も併せて、計画としては何園増やしますという数も説明を求めました。","respondent":"立木保育課長、中元保育支援課長","answer":"指数が４０点で、税の階層がＤの２５のところに複数の方がいらっしゃった場合、その中でも優先順位というものがついてまいります。この状況、今回出しているものに関しては、Ｄの２５の方は入れているという表示の仕方をしています。 今予定しているところは以上です。一度に世帯数が多く入られる、分譲が３００戸ほどのものが予定されておりますので、そちらのほうには新規開設を予定しています。","id":"exchange-044"},{"speaker":"安藤委員","kind":"質問・要望","question":"もう少し伺いたいのですが、区に報告を求めて公表しています様々な数値があるのですけれども、いわゆる定期保育事業というのが品川区にはあります。１園のみ希望している方は、１園のみ希望していない方というのはたくさんいるわけで、その辺の数を伺いたいと思います。","respondent":"中元保育支援課長","answer":"東大井、東品川地区につきましては、厳しい状況があるというところは認識しています。継続して利用申請が確認できない方、求職する書類が確認できなかったなど、こちらにつきましては２４名の方。","id":"exchange-045"},{"speaker":"安藤委員","kind":"質問・要望","question":"最後に要望を含んで質問したいのですが、それはいつぐらいになったら確定するのかというのを伺いたいのと、それが実態なわけではないですか。国への公表を改めて求めたいと思いますけれども、いかがか尋ねました。","respondent":"中元保育支援課長","answer":"現在、国との調整時期は、国のほうで公表時期等が決められるところがありますので、私のほうでは知り得ないところです。区におきましては、待機児童というのはあくまで国の基準での考え方で取ってありますので、これが全てということで考えているところです。","id":"exchange-046"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/921668?Template=document&Id=5064#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":45121,"voices":134}},{"id":"r04-20220516-5","meetingId":"r04-cm05","date":"2022年5月16日","dateIso":"2022-05-16","committee":"総務委員会","time":"午後 １時００分～午後 １時３９分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を13件整理しています。","topics":[{"id":"topic-01","title":"冒頭で申し上げたとおり、取り上げる順番を変更し、まず、(2)参議院議員選挙における執行要領","agenda":"冒頭で申し上げたとおり、取り上げる順番を変更し、まず、(2)参議院議員選挙における執行要領","exchanges":[{"speaker":"おくの委員","kind":"質問・要望","question":"これも何人かの方にお伺いしたし、やっぱり自分の地元ですぐに投票できるようにしていただきたいという声も聞くし、私自身も思っているところです。この２点をまずお伺いしたいと思います。","respondent":"鈴木選挙管理委員会事務局長","answer":"様々な集客のためのイベントなどを予定を組んで実施するということで、予定していたものを調整して実施するのは難しいということと、感染予防上。","id":"exchange-001"},{"speaker":"おくの委員","kind":"質問・要望","question":"しかも２週間程度のことですので、１３地域センター全部とは言わないまでも、何か考えていただきたい。やっぱり区役所１か所だけしか最初から投票できる期日前投票が、２週間ずっとできるところがないというのは、いかがか尋ねました。","respondent":"鈴木選挙管理委員会事務局長","answer":"基本的には、やはり、ある程度の制約は仕方ないかと考えております。そのときの住民の方の公平性等の担保も含めて、検討の余地はあるのではないかと考えているところです。","id":"exchange-002"},{"speaker":"おくの委員","kind":"質問・要望","question":"品川区としても、こういう側面からの働きかけもやっていくとよいのではないかと思うのですが、そのようには考えておられないのでしょうか。この点、伺いたいと思います。","respondent":"鈴木選挙管理委員会事務局長","answer":"選挙制度自体ですので、区の単独の意見でというようなところで何か働きかけをするところは、現在考えておりません。今、検討されて定められた年齢要件なり供託金ですので、これの議論については国のほうに任せるべきだというふうに考えております。","id":"exchange-003"},{"speaker":"おくの委員","kind":"質問・要望","question":"ものだとは思うのですが、やはり大きく政治参加を促していくという角度から、いま一度考えてほしいと求めました。これは要望ということで言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"田中委員","kind":"質問・要望","question":"もうちょっと前倒しにできないのかということを伺いたいのと、あと、投票所への移動に関する支援などのお知らせがあるではないですか。ここに関しても何かあれば答えていただきたいということと、あと、選管ではどのように考えているのかというところを伺いたいということが１点。","respondent":"鈴木選挙管理委員会事務局長","answer":"区のホームページにおける投票所移動の支援についてのお知らせですが、ご利用いただけるようにしたいというふうに予定をして準備しております。","id":"exchange-005"},{"speaker":"田中委員","kind":"質問・要望","question":"そこを確認したいのと、投票済証について、ぜひ「ありますよ」というお知らせをお願いしたいと思います。選挙公報についても、なるべく早めに、８日までということですけれども、なるべく早く配布ができるようにということは要望したいと思います。","respondent":"鈴木選挙管理委員会事務局長","answer":"啓発についての詳細な予定ですが、通常行っている街頭の啓発は自粛をする予定ですが、できるだけ広く呼びかける予定です。なお、国や都のほうで、それぞれ独自の啓発も並行して行われる予定です。","id":"exchange-006"},{"speaker":"須貝委員","kind":"質問","question":"我々の活動に対する魅力ですか、実際そういうことならば、所管事務調査でまたしっかり委員会で検討すればいいのではないかと思います。参議院議員選挙なのですか、区議会議員選挙なのですか、都議会議員選挙なのか尋ねました。","respondent":"鈴木選挙管理委員会事務局長","answer":"それ以外の場所については、特に私有地の場合は、なかなか場所の確保が難しいということがあります。今後も引き続き、選挙啓発と併せて、しっかりと見ていただける場所を確保したいというふうに考えております。","id":"exchange-007"},{"speaker":"田中委員","kind":"意見","question":"感染症が広がったときの対応は、そういうお知らせも、もし感染した場合の投票のやり方も、ぜひ広く広報してほしいなということを思っています。そのことについてもぜひお知らせいただければ……との意見を述べました。","respondent":"鈴木選挙管理委員会事務局長","answer":"今回も事前の選挙特集の広報しながわで欄を１つつくりまして、あまり件数はないと思われるので、しっかりとご案内できるというふうに考えております。ただ、広報による周知は行います。","id":"exchange-008"},{"speaker":"田中委員","kind":"質問・要望","question":"今ご答弁いただいたような内容を、ぜひホームページ等でもお知らせしてほしいと求めました。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"}]},{"id":"topic-02","title":"品川区・早川町ふるさと交流３０周年記念事業","agenda":"品川区・早川町ふるさと交流３０周年記念事業","exchanges":[{"speaker":"田中委員","kind":"質問","question":"ホームページで見ると、標高４８２ｍの丸山というのですか、その山の上に鐘を設置するのですか。それとも下に設置するのか尋ねました。","respondent":"古巻総務課長","answer":"交通費というか、これは先ほどちょっとお話のありました鐘の設置のための費用を含めまして、１３９万３,０００円ということで予定をしております。最終的には山の上に設置をするということで考えておりますけれども、式典の際には麓のほうに仮設置をして、考えているところです。","id":"exchange-010"},{"speaker":"須貝委員","kind":"質問","question":"何人ぐらいの方がここに行かれて、そして、自然と親しむような利用をされているのですか。もし分かれば説明を求めました。","respondent":"古巻総務課長","answer":"新型コロナの関係もありまして、例えば宿泊施設の助成とかの利用は、あまりなかったかなというふうに思っています。定員は大体２５人ぐらいで、一昨日と昨日にかけて交流バスツアーも久しぶりに実施いたしまして、大型バスで３０数名ということで。","id":"exchange-011"},{"speaker":"須貝委員","kind":"質問","question":"見直し等も検討されているのでしょうか。もし何かそういうものがありましたら説明を求めました。","respondent":"古巻総務課長","answer":"ツアーとかではなくて、面での交流というのでしょうか、連携みたいなものも一定進んできているということもあるかなというふうに思います。早川町との合同の防災訓練を実施したというようなこともありますので、様々な分野で、広げていくというようなことで考えているところです。","id":"exchange-012"},{"speaker":"須貝委員","kind":"質問・要望","question":"やはりそういう交流事業に持っていかなければ、なかなか理解を得られなくなるかなと思いますので、その辺はご検討ほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/816435?Template=document&Id=2230#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":12820,"voices":38}},{"id":"r04-20220517-14","meetingId":"r04-cm05","date":"2022年5月17日","dateIso":"2022-05-17","committee":"行財政改革特別委員会","time":"午後 １時００分～午後 １時０３分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/474872?Template=document&Id=6128#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":1631,"voices":11}},{"id":"r04-20220518-19","meetingId":"r04-cm05","date":"2022年5月18日","dateIso":"2022-05-18","committee":"災害・環境対策特別委員会","time":"午後 １時００分～午後 １時３５分","status":"正式会議録","sourceType":"formal","overview":"災害・環境対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を15件整理しています。","topics":[{"id":"topic-01","title":"フードドライブの実施","agenda":"フードドライブの実施","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"もちろん生ものはないでしょうけれど、やはり保存というのは、その先のことを考えると気を遣うべきことだと思うのです。その保存のことはどのようにお考えか、伺いたいと思います。","respondent":"河内環境課長","answer":"保存のことを考えまして、生鮮食料品、冷凍・冷蔵食品、また包装・外装が破損しているもの、アルコール類は受け付けておりません。賞味期限まで４か月以上あるということで、一定の期間を設けまして保存し、活用いただくような想定で進めているものです。","id":"exchange-001"},{"speaker":"吉田委員","kind":"質問","question":"集まってきたものは速やかに次の段階まで持っていって、適正な賞味期限で必要な人の手元に届くようにお願いする、ということでしょうか。子ども食堂ネットワーク事務局が、その辺はうまく配分してくださると思うのですけれど、その辺だけ気になったので説明を求めました。","respondent":"河内環境課長","answer":"その際、汚れや傷などがないことを確認しながら種類ごとに分けまして、お渡ししている状況です。その際、それらを役立てる献立といったものも想定しながらやることによりまして、さらに無駄が生じないような工夫をもとに進めているものです。","id":"exchange-002"},{"speaker":"吉田委員","kind":"質問","question":"私が今まで出していたところは、基本、新しいものがいいに決まっているのですけれども、搗精から２年以内はお受けしますというところだったのです。やはりあまり古い搗精のものは、と思うので、その辺どのようにお考えか伺いたいと思います。","respondent":"河内環境課長","answer":"その精米の日付によりまして活用される方にご判断いただき、お引取りいただく形で進めてあります。バラで量を測って仕分けるということは、傷みますのでやっておりません。","id":"exchange-003"},{"speaker":"吉田委員","kind":"質問","question":"分かりました。たまたま私が寄附していたところは搗精日から２年以内ということだったのですが、そういうことをお考えなのか、伺いたいと思います。","respondent":"河内環境課長","answer":"中身につきましては、いつまでのもの、というふうな仕切りでは進めておりません。あくまで現場主義で進めているものです。","id":"exchange-004"},{"speaker":"吉田委員","kind":"意見","question":"分かりました。現場主義と今おっしゃいましたけれども、ご意見を聞きながら今後の調整というか、そういうものはしていただけたらと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"},{"speaker":"新妻委員","kind":"質問・要望","question":"ご説明ありがとうございました。冒頭に一つ確認させていただきたいのですが、その時の状況を、数とか分かりましたらお知らせください。","respondent":"河内環境課長","answer":"大体人数的には２０人前後ですが、６０キロから７０キロと、驚くやら何やらという点がございました。平成３０年から取り組んでいる事業でありますが、こういったところでもやはり、いろいろな形で集まるのだなと実感できたところです。","id":"exchange-006"},{"speaker":"新妻委員","kind":"質問・要望","question":"受付窓口はこの３か所ですけれども、社会福祉協議会での受付というのは、あえてこの中に入れていないのでしょうか。こちらとの関連も教えてほしいと求めました。","respondent":"河内環境課長","answer":"福祉的側面はもちろん認識していますが、また廃棄するものという中で、食品ロスという観点で進めているものです。その辺りの考え方は今後変化していく可能性もありますので、検討しながら進めてまいりたいと考えているところです。","id":"exchange-007"},{"speaker":"渡辺委員","kind":"質問","question":"単年度というよりは３年後、５年後どうするか、というようなビジョンがあっていいかなと。イコール、その成果物、成果が見えるような事業計画があってもいいかと思うのですが、現状と今後というところで説明を求めました。","respondent":"河内環境課長","answer":"想定や具体的な数値はありませんが、まだまだ説明が必要な用語と捉えておりまして、コラム的に必ずご案内申し上げているところです。３年、５年ではなかなか落ち着かないと思いますが、多くの方が参加できるような仕組みをとらまえて進めてまいりたいと考えているところです。","id":"exchange-008"},{"speaker":"渡辺委員","kind":"質問・要望","question":"それと、いいことだけれども、押しつけてしまうのも、よくありがちではないですか。それはどこかへ委託でも何でもいいですから、その辺をお願いしますとともに、ご答弁お願いします。","respondent":"河内環境課長","answer":"多様な団体との連携ですが、連携につきましては今後も検討を進めてまいりたいし、また拡大してまいりたいと考えているところです。そういったところを検討してまいりたいと考えているところです。","id":"exchange-009"},{"speaker":"こんの委員","kind":"質問","question":"１点お伺いしたいと思います。例えば環境課は、日曜開庁はあるものの開いている窓口は限られているはずですから、そこがどうなっているのか。","respondent":"河内環境課長","answer":"土日は基本的に上がってこられませんし、中小企業センターにつきましては、なかなか中に入りづらいというところもあります。今おっしゃられた電子媒体と含めまして周知するとともに、のぼりなどにつきましては、また検討していきたいと考えているところです。","id":"exchange-010"},{"speaker":"こんの委員","kind":"意見","question":"確かに４階まで上がる方というのは必要のある方だけで、４階に上がってみても、そこは工夫されたほうがいいかなと。あえて周知というか、当日の工夫が必要かと思うのですが、何かございましたらとの意見を述べました。","respondent":"河内環境課長","answer":"今、委員からご指摘いただきましたとおりです。ご利用いただくときに混乱がありませんように、周知、ご案内につきましても工夫をして進めてまいりたいと考えているところです。","id":"exchange-011"},{"speaker":"こんの委員","kind":"質問・要望","question":"どうか最初の一歩の、いかに次につながるかというところもあると思いますので、どうぞ工夫をしながら進めてほしいと求めました。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そういうところに対してはどう考えられているかということと、たくさん集まったものは、そこら辺は今後どう考えられているのか。先ほどもビジョンを持つべきだというお話がありましたけれど、そういう点ではどう考えられているのか、伺いたいと思います。","respondent":"河内環境課長","answer":"難しい点もありますので、そちらにつきましては活用の方法などを今後の検討事項としたいと考えているところです。事業者の方の知恵も拝借しながら、そういったところの検討を進めていきたいということで、今も進めているところです。","id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"本当に格差と貧困が広がる中で、フードバンクの取組みも各地で行われ、そういうところに列をなして人が来られるという状況もあります。フードロス削減というのは本当にいい取組みだと思いますし、そういうところにもつなげていっていただけたらと思っていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-014"}]},{"id":"topic-02","title":"特定事件調査のまとめ","agenda":"特定事件調査のまとめ","exchanges":[{"speaker":"たけうち委員","kind":"意見","question":"表面の４番で、話し言葉では使うのでしょうけれど、こういう文章にするときには「地域の声」などにしたほうがいいのではないかと。内容的な問題ではなく、一応どうかなということですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/781505?Template=document&Id=6614#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=19&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":12361,"voices":53}},{"id":"r04-20220520-10","meetingId":"r04-cm05","date":"2022年5月20日","dateIso":"2022-05-20","committee":"議会運営委員会","time":"午前１１時００分～午前１１時１４分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を1件整理しています。","topics":[{"id":"topic-01","title":"議会構成等","agenda":"議会構成等","exchanges":[{"speaker":"須貝委員","kind":"確認","question":"ちょっと質問なのですが、今回は無所属の方が入りました、１名。ちょっと前回は、総務委員会に無所属が入るということを意識して確認しなかったので、ちょっとご見解だけ説明を求めました。","respondent":"石田（秀）委員長","answer":"無所属の議員の方が５名いらっしゃるということで、どこを７名にするのかというような検討もさせていただいて、委員長案という形をつくらせていただいたということであります。","id":"exchange-001"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/982514?Template=document&Id=5462#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":4684,"voices":21}},{"id":"r04-20220526-10","meetingId":"r04-cm05","date":"2022年5月26日","dateIso":"2022-05-26","committee":"議会運営委員会","time":"午前１０時３０分～午前１１時０３分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を6件整理しています。","topics":[{"id":"topic-01","title":"議事日程（１）、追加議事日程および追加議事日程（２）","agenda":"議事日程（１）、追加議事日程および追加議事日程（２）","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"改めて原点に戻って、監査委員は第１会派および第３会派から選任されることを要望したいと思います。監査委員は第１、第３会派からセットで選任すべきだと考えていますので、どちらにも反対ということを表明します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"須貝委員","kind":"意見","question":"その時々、このように誤解を与えるようなことではなくて、こういう形で選任しますというルールづくりはしておいたほうがいいのではないかと思います。今回は両名とも賛成しますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-002"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"須貝委員","kind":"提案","question":"会計管理室のほうでもそういうことに対応できるような仕組みをつくってもらえないかという要望と、皆さん、教えていただければありがたい。その２点について、今回提案しますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"},{"speaker":"あくつ委員","kind":"質問・要望","question":"公金扱いなのだから、みずほ銀行にきちんとやってほしいというのが正直な思いです。ただ、事務局の工夫でどうにかなることではないということは、何か改善はしていただきたいというのは前々から申し上げているところです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"須貝委員","kind":"意見","question":"私は１年に１回のことなのですが、あくつ委員はもっと回数が多いかもしれないですが、一応ここの場で申し上げておきたいと思います。ご検討をとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"},{"speaker":"あくつ委員","kind":"確認","question":"みずほ銀行が公金を下で扱うのを、法人のものはやめたということが問題なのです。そこは議会として共通認識を持っておかないと、話がおかしな方向に進んでしまうと思うので、そこだけご確認をほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/982514?Template=document&Id=5464#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":10729,"voices":53}},{"id":"r04-20220527-6","meetingId":"r04-cm05","date":"2022年5月27日","dateIso":"2022-05-27","committee":"区民委員会","time":"午前１０時０７分～午前１０時４８分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を21件整理しています。","topics":[{"id":"topic-01","title":"第３９号議案 令和４年度品川区一般会計補正予算（歳出 区民委員会所管分）","agenda":"第３９号議案 令和４年度品川区一般会計補正予算（歳出 区民委員会所管分）","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"幾つか伺いたいのですけれども、どういった問題が中小企業の中で起きているのか、区の認識を伺いたいと思います。そして、区内中小企業の資金調達を支援するということですけれども、財源は一般財源ということなのか、お伺いいたします。","respondent":"遠藤商業・ものづくり課長","answer":"まだ消費者物価では２％程度ということで、ただ、なかなか要するに転嫁できていないような状況があると聞いているところです。そちらの充当について考えているような形になっておりますが、今回は一応、一般財源でということで聞いているところです。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問","question":"このハードルの高さはどのように考えているのかを伺いたいと思います。私はやはり、融資あっ旋にとどまらず、事業所への直接支援、補助制度をしっかり充実させていくことが必要だと思いますが、いかがか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"支援策は様々なところをいろいろ検討させていただいていたところです。２００万円をそのまま負担、今回、こういう融資あっ旋制度を設けさせていただいたです。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"粗利が５％減っているということですけれども、もう少し詳しくご説明いただきたいと思いまして、対象要件をもう少しご説明ほしいと求めました。事業者が見て分かりやすい工夫が必要かと思うのですけれども、併せてご説明いただきたい。","respondent":"遠藤商業・ものづくり課長","answer":"売上高を５％下げるという、それで今回、売上げ総利益のほうも５％以上下がった。将来、この後こんなふうになりそうだというところも踏まえて、丁寧に対応させていただければと思っているところです。","id":"exchange-003"},{"speaker":"藤原委員","kind":"質問","question":"あえて５％とつけたのはなぜでしょうかということと、そこにお金を融資してというふうに、窓口を少し広げてもらいたかったという思いがあるのです。１社で２００万円とおっしゃっていたけれども、いかないわけですから、これは５％と決めてもらいたくなかった。","respondent":"遠藤商業・ものづくり課長","answer":"この数字が、見えない部分ではあるのですけれども、２７５件あれば十分対応できるだろうという形で試算させていただいたです。これまで使っていただいている方々には、こちらも併せてお使いいただくことができるようになっているところです。","id":"exchange-004"},{"speaker":"藤原委員","kind":"質問","question":"１と２と分けるから分からなかったのですけれども、直近の３か月の売上げ等が落ちているなどとしていればいいのだけれども、あまりないですよね。ちょっと細かいけれど、その辺はいかがか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"資料が大変分かりづらくて申し訳ございません。（１）、（２）のいずれの要件にも該当しているということで対象になっておりますので、なおかつ売上高がというような形で考えていただければです。","id":"exchange-005"},{"speaker":"藤原委員","kind":"質問","question":"実際的に２００万円ぐらい１社にやる。そこも押さえておきたいとは思うのですけど、方法としてあるのかという思いがあるので、その辺についてはいかがか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"考えていかなくてはいけない部分もありますし、２００万円がどういう企業に効果があるかというところも、その辺の設定も必要かと考えています。","id":"exchange-006"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"建設・建築関係の事業者のことについてお尋ねしたいのですけれども、支援策の冊子というか、町場の地場の建設に従事している人たちというのは。区内の建設の４団体の組合の方、今回のことで区切っていくと、どういうふうな広報の仕方をするのか教えてほしいと求めました。","respondent":"遠藤商業・ものづくり課長","answer":"考えられる全ての方法で周知はしたいと考えていますけれども、また特に団体には個別にご説明したりというところもあります。その辺は連携しながら、今後、周知は進めていきたいと考えています。","id":"exchange-007"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ぜひ所管と連携していただいて、私は特に特化はしていますけれど、建設に従事されている方たちに対しても、ぜひ周知してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"くにば委員","kind":"質問","question":"伺いたい部分が、広告の出稿が抑えられてしまって売上げが下がってしまった広告代理店といったところに関しては、対象になるのか。それで、そういったところが対象になるのか、ならないのかという部分を、まず１点伺います。","respondent":"遠藤商業・ものづくり課長","answer":"今回、例えば中国のロックダウンなどで物が入ってこないなどという影響もあるので、いろいろなケースが考えられるかと思います。間接的であれ影響が出ているということを、当然ご説明いただく形になろうかと思いますけれども、そういう部分では広く対応したいと考えております。","id":"exchange-009"},{"speaker":"くにば委員","kind":"質問","question":"それをやられるのかどうかという部分と、困っていらっしゃる企業に貸出しをするという理念だと、あまり細かく定義しないほうがいいのか。その両方の概念があると思うのですけれども、その辺りについての見解をお伺いしたいです。","respondent":"遠藤商業・ものづくり課長","answer":"その中で、「もしあれでしたら、こちらの原油価格・物価高騰対応資金というのがあります」という形の紹介は可能かと考えています。工夫しながら、もしかすると対象になるのかということで、取りあえずお電話を頂くというスタイルが取れればと思っているところです。","id":"exchange-010"},{"speaker":"くにば委員","kind":"意見","question":"経営変化対策資金２０２２に対応している方が、経営変化対策資金２０２２のものプラス、今回のメニューの２,０００万円。これは両方、上乗せで使えるのかどうか、説明を求めました。","respondent":"遠藤商業・ものづくり課長","answer":"こちらは併用していただいて結構です。","id":"exchange-011"},{"speaker":"くにば委員","kind":"質問","question":"さらに、先日の委員会でご説明いただいた、例の、あっ旋限度額３,０００万円、３年間無利子の借換え専用資金とも併用できるということか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"恐らく、経営変化対策資金２０２１や経営変化対策資金２０２２を借りていらっしゃる方が借換え専用資金という形になろうかと思います。そちらの併用も可能です。","id":"exchange-012"},{"speaker":"くにば委員","kind":"確認","question":"私の認識を再確認したいのですけれども、今回のあっ旋限度額２,０００万円で、さらに１,０００万円。トータルで１企業が、マックスで６,０００万円、同時並行で受けられるということか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"借換え融資につきまして、３,０００万円が限度額ではありますけれども、それまでに借りていた額が最大となりますので、その範囲内でということであれば、同時に併用するということはできるようになっております。","id":"exchange-013"},{"speaker":"くにば委員","kind":"質問","question":"それはもう、あくまで金融機関がリスク等に関しては審査して判断するということで、そこの金融機関の審査を受けて、区では対象を選ぶのかどうか。そこのスキームに関してお伺いします。","respondent":"遠藤商業・ものづくり課長","answer":"実際に銀行で否決となるのは、ゼロではないのですけれども、それほど多くないという印象があります。経営改善計画策定支援という、その中でいろいろやっていきながら事業を継続するというような、私どもの道筋を立てているというのが考えです。","id":"exchange-014"},{"speaker":"くにば委員","kind":"質問・要望","question":"言葉では大変、上から目線で申し訳ないのですが、非常にすばらしいメニューだと考えております。ぜひとも引き続き、様々なご判断基準で、区で支えていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"西村委員","kind":"質問","question":"この後されるのかというのを伺いたくて、品川区はいろいろとあるかと思っているのですが、その辺りを改めて伺います。","respondent":"遠藤商業・ものづくり課長","answer":"ビジネスカタリストの派遣などを通じて、今のところ、きめ細かくという形でやらせていただいているところです。今後いろいろ変わってくるかと思いますので、その辺の枠を増やしたところということは、今後検討していければと思っているところです。","id":"exchange-016"},{"speaker":"横山委員","kind":"確認","question":"少し細かいところなのですが、確認させてください。全体のスケジュールを確認させてください。","respondent":"遠藤商業・ものづくり課長","answer":"二日は今、埋まってしまうような状況がありますので、ただ１週間はかからずにご案内できるかと考えています。できるだけ早くということではお願いしています。","id":"exchange-017"},{"speaker":"横山委員","kind":"質問","question":"大変スピード感を持って、今、対応の準備をしていただいているということで、安心いたしました。２７５件の申請を想定しているということで、体制について、どのように整えているのかというところも説明を求めました。","respondent":"遠藤商業・ものづくり課長","answer":"経営変化対策資金２０２２を借りる方が流れてくるということもありますので、中小企業診断士協会と一度連携させていただいて、状況を見ながらいろいろ考えていきたいと考えています。","id":"exchange-018"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"かなり深まっていると思うのですけれども、５％の条件というところなのですが、どうしても条件は決めざるを得ないと思います。そういう体制をつくっていただきたいと、お願いしたいと思っているのですけれども、いかがでしょう。","respondent":"遠藤商業・ものづくり課長","answer":"審査などはあるので難しい面もありますけれども、そういう部分でいろんな選択肢をご提示できるかと思っているところです。三回とおいでいただいて、いろいろ考えて一緒になって、事業者と進められればと考えているところです。","id":"exchange-019"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"１年間据え置いて、実質９年での返済ということになると思うのですが、「うち据置１２月」という表記になるのでしょうか。少し分かりにくいと思ったのですが。","respondent":"遠藤商業・ものづくり課長","answer":"返済期間につきましては、１０年で、据置１２月という表現が、企業が一般的に分かるかというところがありますので、今、委員がおっしゃったような書き方で掲載する形になるかと思っているところです。","id":"exchange-020"},{"speaker":"中塚委員","kind":"質問・要望","question":"一言、より一層の支援の充実を求めて、賛成したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/227651?Template=document&Id=2928#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":14231,"voices":53}},{"id":"r04-20220527-7","meetingId":"r04-cm05","date":"2022年5月27日","dateIso":"2022-05-27","committee":"厚生委員会","time":"午前１０時０６分～午前１０時５６分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を16件整理しています。","topics":[{"id":"topic-01","title":"第３９号議案、令和４年度品川区一般会計補正予算（歳出 厚生委員会所管分）","agenda":"第３９号議案、令和４年度品川区一般会計補正予算（歳出 厚生委員会所管分）","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"令和４年６月末から８月末まで延長されたために、対象のところで、総合支援資金の不承認になった方というのはどれぐらいいらっしゃるのでしょうか。これ以降、再貸付はやっていないので、再貸付の件数は３,１３５件という件数でいいのかというのを確認させていただきたいのです。","respondent":"櫻木生活福祉課長","answer":"これは、令和３年７月から令和４年４月末までの実績です。大変恐縮ですが、総合支援資金につきましては、社会福祉協議会の事業になりまして、私のほうで現時点の数値というものは把握しておりません。","id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、生活困窮者自立支援金のほうで、初回が７４９件、再支給が３９２件と、結構増えているのですね。再支給のところで、ぐっと数が減っていく理由というのを、区はどう考えられているのか、説明を求めました。","respondent":"櫻木生活福祉課長","answer":"３ヶ月受けられた後に、３ヶ月後に状況が変わって受給要件を満たさないという方が一定いらっしゃると認識しております。タイミングが分からないのですが、生活困窮者自立支援金を受けられた方で生活保護を受給されている方の実績としては１８人という形になります。","id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問","question":"やはり６万円ではやり切れないから、そうすると、では改善してきているという方のほうが多いということなのでしょうか。この予算額というのは、そして推計対象者数の１００世帯というところは、どういうふうに出されているのか尋ねました。","respondent":"櫻木生活福祉課長","answer":"２人世帯が１７％、３人以上世帯が１７％という形で、それぞれ案分して掲載しているものです。実際に初回申請の方の見込み数、再支給につながるであろう方の見込み数を積み上げた金額に、この数値となるものです。","id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"質問","question":"単身世帯の方が多いということなのですね。それで、この対象者数の推計値が上回っていった場合というのは、どういう対応をされるのか尋ねました。","respondent":"櫻木生活福祉課長","answer":"ある程度、予算の中でカバーできる範囲であれば対応いたしますが、大きく増えるということがあれば、また補正予算をお願いすることになると考えております。","id":"exchange-004"},{"speaker":"石田（ち）委員","kind":"質問","question":"家計急変世帯というのが４,０００世帯を想定されていたわけですけれども、それで本当に皆さんが自ら手を挙げられるのかどうか。そうすると、家計急変世帯が４,０００世帯と想定されていたので、区としてどう見られているのかという見解を伺いたいと思います。","respondent":"櫻木生活支援臨時給付金担当課長","answer":"４,０００世帯という数値を算定するに当たっては、一定の比率を示されておりましたので、都の見積りの数字が比較的多めであったという認識です。こちらも今回の８,４００世帯というのは、そこにそごが出てしまうのは、やむを得なかったのかと考えています。","id":"exchange-005"},{"speaker":"石田（ち）委員","kind":"確認","question":"５月６日が確認書返送受付期限となっているので、そうすると、要は非課税世帯等の皆さんは５月６日で受付が終わったという認識でいいのか。今回、対象になってくると思うのですけれども、それがどれぐらいなのかというのを説明を求めました。","respondent":"櫻木生活支援臨時給付金担当課長","answer":"今回、令和４年度の非課税給付金を大々的に広報しますので、併せて未申請の方への周知・注意喚起等を同じようにやっていきたいと考えています。申請期限は過ぎておりますが、申請期限を過ぎても申請できますという旨も添えて周知します。","id":"exchange-006"},{"speaker":"石田（ち）委員","kind":"確認","question":"未申請の６,６２５件には、申請してくださいというやり方でやっていくということでいいかという確認と、これは結構進んだのか。申請に大分、貢献したではないですけれども、そういうことなのかを説明を求めました。","respondent":"櫻木生活支援臨時給付金担当課長","answer":"高齢者に関しては２０か所の在宅介護支援センター、障害者の方につきましては５か所の地域拠点相談支援センターに、周知と。まだ報告書等が上がってきておりませんので、実績等はまだ上がってきておりませんが、そのような形で周知を進めていくことになります。","id":"exchange-007"},{"speaker":"石田（ち）委員","kind":"意見","question":"５万９,０００世帯ということで、約６万世帯、６０億円の予算をつけているということも聞いたのです。やはりこういう対応が品川区としても必要なのではないかと思うのですけれども、いかがでしょうとの意見を述べました。","respondent":"櫻木生活支援臨時給付金担当課長","answer":"今、お話のあった給付金の拡大等を区独自にというお話です。個人向けの経済的な支援や助成につきましては、区全体の観点で、都や国の動向を踏まえながら検討していくものと考えております。","id":"exchange-008"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ぜひ区民の実態というものをもう少し見ていただいて、非課税世帯のみならず、コロナで本当に大変な世帯、そして物価高騰で大変になっている世帯や事業者がありますので、ぜひ区独自の対策としても、今後検討してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"生活困窮者自立支援金のことについて伺いたいのですけれども、これまでの実績で、先ほど、単身世帯、２人世帯と３人以上世帯というもののパーセンテージをおっしゃっていただいたのですけれども、聞き取れなくて、もう一度お願いしたいと思います。","respondent":"櫻木生活福祉課長","answer":"単身世帯が６６％、２人世帯が１７％、３人以上世帯が１７％という比率です。","id":"exchange-010"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"その辺のところはどういうことで、これだけの額になっているのか、伺いたいのが１つです。一人ひとりに対して、どういうことになっているのか、その辺のところはどう考えられているのかについても伺いたいと思います。","respondent":"櫻木生活福祉課長","answer":"やはり状況としては単身世帯の方が多いということがあり得るのかということで、下がっている可能性はあるのかと思います。再支給の案内ですが、申請を促させていただいていますので、受給者の方がご判断で申請されないということが多いのかと考えています。","id":"exchange-011"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"総合支援資金は単身世帯でも１５万円が出るものが、もう６万円となってしまうので、当初から問題にされていた部分もあるのです。どういう状況になっているのかというのは、つかんでほしいと求めましたが、いかがか尋ねました。","respondent":"櫻木生活福祉課長","answer":"基本的に、ご申請されてきて、例えば収入超過や資産超過で却下です分は、ある程度、こちらでも把握できるところですが、本人から申請が来ないということですと、なかなか把握しづらいところではあります。","id":"exchange-012"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"結構、区の通知を見る習慣がないというか、そういう方もいらっしゃるのです。本当にこの１０万円が、漏れている方に対してのきめ細やかな配慮で受給できるようにということで、お願いしておきたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-013"},{"speaker":"若林委員","kind":"質問・要望","question":"ファイザー、モデルナ、あとノババックスが承認されたと思うのです。その辺、３回目と４回目があると思うのですが、概略、ワクチンの種類についてお知らせいただきたい。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"今まで６カ月だったものが５カ月に短縮され、３回目から４回目も５カ月の間隔で、いずれのワクチンも４回目として使用が可能です。１回目・２回目ないし３回目接種にのみ接種が可能でございまして、４回目の対象とは現在なっておりません。","id":"exchange-014"},{"speaker":"若林委員","kind":"質問","question":"そうすると、４回目にはノババックスは使われないということですか。全くの素人なので、３回目まではよくて、４回目が駄目だという公式見解というのは、どんなものなのか尋ねました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"薬事承認が下りていないというところで、国から通知が出ておりますので、それ以上のことは、申し訳ありませんが、現在は私では分からないです。","id":"exchange-015"},{"speaker":"若林委員","kind":"質問・要望","question":"国から示されているということだと思うのですが、推計値の中身というのを教えてほしいと求めました。住民税非課税ということも、どこまで明確なご答弁か分かりませんけれども、その辺の内容を教えていただきたい。","respondent":"櫻木生活支援臨時給付金担当課長","answer":"それに、こちらは令和３年度の非課税者ということで人数になりますので、今回、世帯に引き直さなければいけません。世帯割合を掛けますと８６.７％でございましたので、そちらを非課税世帯数に掛けて算出したものです。","id":"exchange-016"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/567724?Template=document&Id=3628#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":13426,"voices":51}}]);
